    ["|cffff8800Switch the Class Specific module on to use this.|r"] = "|cffff8800이 기능을 쓰려면 직업별 기능 모듈을 켜세요.|r",
    ["Class-specific tools, grouped by class: the Priest Vampiric Touch mana tracker, DoT trackers, the Shaman totem bar and the Paladin seal twist helper."] = "직업별 도구를 직업에 따라 묶어 제공합니다. 사제의 흡혈성 손길 마나 계산기, 지속 피해 추적기, 주술사의 토템 막대, 성기사의 인장 전환 도우미가 들어 있습니다.",
    ["Simplified Chinese and Traditional Chinese. Both are complete: every interface text, every option and every patch note, 2528 entries each. They are separate translations, not one converted into the other. Pick yours under General, or leave the setting on Auto and it follows your game client."] = "간체 중국어와 번체 중국어. 둘 다 완역입니다. 모든 인터페이스 문구, 모든 설정, 모든 패치 노트까지 각각 2528개 항목입니다. 하나를 변환한 것이 아니라 서로 다른 두 개의 번역입니다. 일반에서 원하는 쪽을 고르거나, 설정을 자동으로 두면 게임 클라이언트를 따라갑니다.",
    ["Spam Filter"] = "스팸 필터",
    ["Hide (and optionally ignore) chat spammers whose names spell 'casino' & co. with look-alike letters."] = "이름을 비슷한 모양의 글자로 ‘casino’ 등으로 쓰는 대화 스패머를 숨기고, 원하면 무시 목록에도 추가합니다.",
    ["|cffaaaaaaHides chat from gold/casino spammers whose names use look-alike letters (e.g. Gãsïnô, Casinòbâbe). The name is folded to plain letters, then matched against the keywords below. Applies to whisper, channels, say, yell and emotes — not guild/party/raid.|r"] = "|cffaaaaaa비슷한 모양의 글자를 쓰는 골드/카지노 스패머(예: Gãsïnô, Casinòbâbe)의 대화를 숨깁니다. 이름을 일반 글자로 바꾼 뒤 아래 키워드와 대조합니다. 귓속말, 채널, 일반 대화, 외침, 감정 표현에 적용되며 길드/파티/공격대에는 적용되지 않습니다.|r",
    ["Hide their chat messages"] = "해당 대화 메시지 숨기기",
    ["Also add them to your ignore list"] = "무시 목록에도 추가",
    ["Adds matched senders to /ignore too. The ignore list holds only ~50 names and spammers keep changing names, so hiding is usually enough — leave this off unless you want it."] = "일치하는 발신자를 /ignore 목록에도 추가합니다. 무시 목록에는 약 50명만 저장되고 스패머는 계속 이름을 바꾸므로 보통은 숨기기만으로 충분합니다. 꼭 필요한 경우가 아니면 꺼 두십시오.",
    ["Also match the message text"] = "메시지 내용도 검사",
    ["Also checks the message body for the keywords, not just the sender's name. Catches more spam but can have false positives."] = "발신자 이름뿐 아니라 메시지 본문에서도 키워드를 찾습니다. 더 많은 스팸을 잡지만 오탐이 생길 수 있습니다.",
    ["Keywords"] = "키워드",
    ["|cffaaaaaaBuilt-in: casino / asino / gasino / kasino. Add your own below, comma-separated (look-alike letters are handled automatically).|r"] = "|cffaaaaaa기본 제공: casino / asino / gasino / kasino. 아래에 쉼표로 구분해 직접 추가하십시오(비슷한 모양의 글자는 자동으로 처리됩니다).|r",
    ["Extra keywords"] = "추가 키워드",
    ["Block messages with web links"] = "웹 링크가 포함된 메시지 차단",
    ["Hides any message containing a web link (http://, www., domain.tld) in the filtered channels. Whitelisted names are exempt. Opt-in — can catch the occasional legit link."] = "필터가 적용되는 채널에서 웹 링크(http://, www., domain.tld)가 포함된 메시지를 모두 숨깁니다. 허용 목록의 이름은 예외입니다. 선택 기능이며, 가끔 정상적인 링크도 걸릴 수 있습니다.",
    ["Whitelist"] = "허용 목록",
    ["|cffaaaaaaNames here are never filtered. Comma-separated, or use |r|cff9b6cff/vcui spam <name>|r|cffaaaaaa to toggle one.|r"] = "|cffaaaaaa여기에 등록한 이름은 절대 필터링되지 않습니다. 쉼표로 구분하거나 |r|cff9b6cff/vcui spam <name>|r|cffaaaaaa 명령으로 하나씩 전환하십시오.|r",
    ["Never filter these names"] = "항상 예외로 둘 이름",
