    ["Spam filter: '%s' added to the whitelist (never filtered)."] = "스팸 필터: ‘%s’을(를) 허용 목록에 추가했습니다(항상 예외).",
    ["|cff9b6cffBlocked this session: %d|r"] = "|cff9b6cff이번 접속에서 차단: %d|r",
