    ["Profit"] = "수익",
    ["Bind-on-Socket Fix"] = "보석 장착 귀속 오류 수정",
    ["Re-adds the missing BIND_SOCKET confirmation dialog so socketing a gem that binds the item no longer throws a Lua error (Anniversary client)."] = "누락된 BIND_SOCKET 확인 창을 다시 추가해, 아이템을 귀속시키는 보석을 장착해도 더 이상 Lua 오류가 발생하지 않게 합니다(Anniversary 클라이언트).",
    ["Socketing this gem will bind the item to you. Continue?"] = "이 보석을 장착하면 아이템이 귀속됩니다. 계속하시겠습니까?",
    ["The Anniversary client is missing the |cffffffffBIND_SOCKET|r confirmation dialog. Socketing a gem that would bind the item then throws \"Dialog BIND_SOCKET does not exist\" and aborts. This re-adds the dialog so socketing works."] = "Anniversary 클라이언트에는 |cffffffffBIND_SOCKET|r 확인 창이 없습니다. 아이템을 귀속시키는 보석을 장착하면 「Dialog BIND_SOCKET does not exist」 오류가 발생하며 작업이 중단됩니다. 이 기능은 해당 창을 다시 추가해 보석 장착이 정상 작동하게 합니다.",
    ["|cff66ff66Dialog defined|r"] = "|cff66ff66창 등록됨|r",
    ["not defined yet"] = "아직 등록되지 않음",
    ["Nameplate Role Fix"] = "이름표 역할 오류 수정",
    ["Stops the Lua error that fires every time a nameplate appears (Blizzard's nameplate code calls a specialization API this client does not support)."] = "이름표가 나타날 때마다 발생하는 Lua 오류를 막습니다(Blizzard의 이름표 코드가 이 클라이언트에서 지원하지 않는 전문화 API를 호출합니다).",
    ["Blizzard's own nameplate code asks for your specialization role - an API the Anniversary client rejects. The resulting Lua error fires on every nameplate spawn and aborts part of the nameplate setup. This fix answers the question safely with 'no role'."] = "Blizzard의 이름표 코드는 여러분의 전문화 역할을 묻지만, Anniversary 클라이언트는 이 API를 지원하지 않습니다. 그 결과 이름표가 생성될 때마다 Lua 오류가 발생하고 이름표 설정 일부가 중단됩니다. 이 수정은 ‘역할 없음’으로 안전하게 응답합니다.",
    ["not needed on this client"] = "이 클라이언트에서는 필요 없음",
    ["Combat Indicator"] = "전투 표시기",
    ["Restores the missing 'in combat' glow on the Player frame (Anniversary default-UI bug). Pulses a red glow around your portrait while you are in combat."] = "플레이어 프레임에서 사라진 ‘전투 중’ 광원을 되살립니다(Anniversary 기본 UI 버그). 전투 중에는 초상화 주위로 붉은 광원이 맥동합니다.",
    ["|cffaaaaaaThe default Player frame on Anniversary no longer shows when you are in combat. This restores it: a red glow pulses around your portrait while you are in combat.|r"] = "|cffaaaaaaAnniversary의 기본 플레이어 프레임은 전투 중인지 더 이상 표시하지 않습니다. 이 기능이 그것을 되살려, 전투 중에는 초상화 주위로 붉은 광원이 맥동합니다.|r",
    ["Disenchant Queue"] = "마력 추출 대기열",
    ["For enchanters: a window with one button that disenchants your bag items one click each, auto-advancing through the queue (no casting + picking each item by hand)."] = "마법부여사를 위한 기능: 버튼 하나로 가방 속 아이템을 한 번에 하나씩 마력 추출하고 대기열을 자동으로 넘겨주는 창입니다(직접 시전하고 아이템을 고를 필요가 없습니다).",
    ["%d item(s) to disenchant"] = "마력 추출할 아이템 %d개",
    ["|cff888888Nothing to disenchant.|r"] = "|cff888888마력 추출할 아이템이 없습니다.|r",
    ["You need the Enchanting profession (Disenchant) to use this."] = "이 기능을 사용하려면 마법부여(마력 추출) 전문 기술이 필요합니다.",
    ["This module is disabled."] = "이 모듈은 비활성화되어 있습니다.",
    ["Disenchant"] = "마력 추출",
    ["Skip"] = "건너뛰기",
    ["Disenchanting…"] = "마력 추출 중…",
    ["|cffaaaaaaA window with one button that disenchants your bag items one click each and auto-advances through the queue. WoW does not allow fully unattended disenchanting, so this is one click per item — but you never have to cast and pick each item by hand again.|r"] = "|cffaaaaaa버튼 하나로 가방 속 아이템을 한 번에 하나씩 마력 추출하고 대기열을 자동으로 넘기는 창입니다. WoW는 완전 자동 마력 추출을 허용하지 않으므로 아이템당 한 번씩 눌러야 하지만, 매번 직접 시전하고 아이템을 고를 필요는 없습니다.|r",
    ["|cff1eff00You know Disenchant.|r"] = "|cff1eff00마력 추출을 배웠습니다.|r",
    ["|cffff5555You are not an enchanter — this tool will do nothing.|r"] = "|cffff5555마법부여사가 아니므로 이 도구는 아무 일도 하지 않습니다.|r",
    ["Open disenchant queue"] = "마력 추출 대기열 열기",
    ["|cff888888Also: /disenchant or /entzaubern|r"] = "|cff888888또한: /disenchant 또는 /entzaubern|r",
    ["Quality range"] = "품질 범위",
    ["Lowest quality"] = "최저 품질",
    ["Highest quality"] = "최고 품질",
    ["|cff888888Only weapons and armour are listed. Each item is shown before you click, so you always see what you are about to disenchant.|r"] = "|cff888888무기와 방어구만 표시됩니다. 누르기 전에 아이템이 먼저 표시되므로 무엇을 마력 추출하는지 항상 확인할 수 있습니다.|r",
    ["Ignore"] = "무시",
    ["Skip this item for now (it comes back next time)."] = "이 아이템을 지금은 건너뜁니다(다음에 다시 나타납니다).",
    ["Never disenchant this item (add it to the ignore list)."] = "이 아이템을 절대 마력 추출하지 않습니다(무시 목록에 추가).",
    ["Ignored items"] = "무시한 아이템",
    ["|cff888888No ignored items yet. Use the Ignore button in the window to protect an item.|r"] = "|cff888888아직 무시한 아이템이 없습니다. 창의 무시 버튼으로 아이템을 보호하십시오.|r",
    ["|cff888888Click an entry to remove it from the ignore list.|r"] = "|cff888888항목을 누르면 무시 목록에서 제거됩니다.|r",
    ["Clear ignore list"] = "무시 목록 비우기",
    ["Enabled"] = "활성화",
    ["Windows & Professions"] = "창 및 전문 기술",
    ["Quest log, profession windows and the disenchant queue, all in one place."] = "퀘스트 목록, 전문 기술 창, 마력 추출 대기열을 한곳에 모았습니다.",
    ["Gold & Vendors"] = "골드 및 상인",
    ["Gold tracking and automatic buying at vendors."] = "골드 추적과 상인에서의 자동 구매.",
    ["Chat & Tooltips"] = "대화 및 툴팁",
    ["Chat spam filter and tooltip IDs."] = "대화 스팸 필터와 툴팁 ID.",
    ["VuloClassicUI — commands:"] = "VuloClassicUI — 명령어:",
    ["jump to that module's page"] = "해당 모듈 페이지로 이동",
    ["list all modules with on/off state"] = "모든 모듈과 켜짐/꺼짐 상태 표시",
    ["toggle a name on/off the spam-filter whitelist"] = "스팸 필터 허용 목록에 이름 추가/제거",
    ["reset the gold tracker session"] = "골드 추적 세션 초기화",
    ["Type |cff9b6cff/vcui help|r for the full command list."] = "전체 명령어 목록은 |cff9b6cff/vcui help|r 를 입력하십시오.",
    ["Spam filter not available."] = "스팸 필터를 사용할 수 없습니다.",
    ["Usage: /vcui spam <name> — toggle a name on/off the spam-filter whitelist."] = "사용법: /vcui spam <name> — 스팸 필터 허용 목록에 이름을 추가하거나 제거합니다.",
    ["Swing Timer"] = "공격 타이머",
    ["MH"] = "주무기",
    ["OH"] = "보조무기",
    ["Weapon swing timer for your melee auto-attacks (any melee class). Shows a main-hand bar and, while dual-wielding, an off-hand bar."] = "근접 자동 공격의 무기 공격 타이머입니다(모든 근접 직업). 주무기 바를 표시하며, 쌍수 착용 중에는 보조무기 바도 표시합니다.",
    ["|cffaaaaaaShows when your next melee auto-attack lands (any melee class). The off-hand bar only appears while dual-wielding. The bar fills up toward the swing; the number is the time left.|r"] = "|cffaaaaaa다음 근접 자동 공격이 언제 들어가는지 표시합니다(모든 근접 직업). 보조무기 바는 쌍수 착용 중에만 나타납니다. 바는 공격 시점을 향해 차오르며, 숫자는 남은 시간입니다.|r",
    ["Enable swing timer"] = "공격 타이머 사용",
    ["Foreground texture"] = "전경 텍스처",
    ["Foreground transparency"] = "전경 투명도",
    ["Background texture"] = "배경 텍스처",
    ["Background transparency"] = "배경 투명도",
    ["|cffffffffSWING TIMER|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffff공격 타이머|r\\n|cffaaaaaa드래그 또는 방향키|r",
    ["|cffffffffLOADOUTS SIDEBAR|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffff장비 세트 사이드바|r\\n|cffaaaaaa드래그 또는 방향키|r",
    ["Swing Timer position: x=%.0f, y=%.0f"] = "공격 타이머 위치: x=%.0f, y=%.0f",
    ["Swing Timer mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "공격 타이머 이동 모드가 켜졌습니다. |cff9b6cff보라색 상자를 드래그|r하거나 |cff9b6cff방향키|r를 사용하십시오(SHIFT = 5px). 마치려면 ‘잠금 해제 / 테스트’를 다시 누르십시오.",
    ["Swing Timer mover disabled."] = "공격 타이머 이동 모드가 꺼졌습니다.",
    ["Show off-hand bar (while dual-wielding)"] = "보조무기 바 표시(쌍수 착용 중)",
    ["Show time remaining"] = "남은 시간 표시",
    ["Only show while attacking"] = "공격 중에만 표시",
    ["Hides the bars unless you're auto-attacking. Turn off to always show them."] = "자동 공격 중이 아니면 바를 숨깁니다. 끄면 항상 표시됩니다.",
    ["Bar color"] = "바 색상",
    ["Gap between bars"] = "바 사이 간격",
    ["Blue"] = "파랑",
    ["Violet"] = "보라",
    ["Cyan"] = "청록",
    ["Green"] = "초록",
    ["Gold"] = "금색",
    ["Red"] = "빨강",
    ["Fishing"] = "낚시",
    ["Loadouts"] = "장비 세트",
    ["Save and quickly equip gear sets for different specs, content, or roles."] = "특성, 콘텐츠, 역할에 맞춰 장비 구성을 저장하고 빠르게 착용합니다.",
    ["Save your current equipment as named gear sets and quickly switch between them. Equipping requires you to be out of combat — items in your bags are auto-equipped via Use."] = "현재 장비를 이름 붙인 장비 구성으로 저장하고 빠르게 전환합니다. 착용하려면 전투 중이 아니어야 하며, 가방 속 아이템은 사용을 통해 자동으로 착용됩니다.",
    ["Save current equipment as a new loadout. Enter name:"] = "현재 장비를 새 장비 세트로 저장합니다. 이름을 입력하십시오:",
    ["Confirm before deleting a loadout"] = "장비 세트 삭제 전 확인",
    ["Saved Loadouts"] = "저장된 장비 세트",
    ["Equip"] = "착용",
    ["Overwrite"] = "덮어쓰기",
    ["Delete"] = "삭제",
    ["Save"] = "저장",
    ["Cancel"] = "취소",
    ["Yes"] = "예",
    ["No"] = "아니요",
    ["items"] = "아이템",
    ["Please provide a name for the loadout."] = "장비 세트의 이름을 입력하십시오.",
    ["Loadout '%s' saved (%d items)."] = "장비 세트 ‘%s’을(를) 저장했습니다(아이템 %d개).",
    ["Loadout '%s' updated with current gear."] = "장비 세트 ‘%s’을(를) 현재 장비로 갱신했습니다.",
    ["Loadout '%s' deleted."] = "장비 세트 ‘%s’을(를) 삭제했습니다.",
    ["Loadout '%s' does not exist."] = "장비 세트 ‘%s’이(가) 존재하지 않습니다.",
    ["Loadout '%s' equipped (%d items swapped)."] = "장비 세트 ‘%s’을(를) 착용했습니다(아이템 %d개 교체).",
    ["Loadout '%s' equipped (%d swapped, %d missing from bags)."] = "장비 세트 ‘%s’을(를) 착용했습니다(%d개 교체, %d개는 가방에 없음).",
    ["Loadout '%s': %d items missing from bags, nothing swapped."] = "장비 세트 ‘%s’: 아이템 %d개가 가방에 없어 아무것도 교체하지 않았습니다.",
    ["Loadout '%s' already equipped."] = "장비 세트 ‘%s’은(는) 이미 착용 중입니다.",
    ["Delete loadout '%s'?"] = "장비 세트 ‘%s’을(를) 삭제하시겠습니까?",
    ["Cannot change equipment in combat."] = "전투 중에는 장비를 바꿀 수 없습니다.",
    ["Equipment swap API not available on this client."] = "이 클라이언트에서는 장비 교체 API를 사용할 수 없습니다.",
    ["No loadouts saved yet."] = "아직 저장된 장비 세트가 없습니다.",
    ["|cffaaaaaaNo loadouts saved yet. Use the button above to save your current gear.|r"] = "|cffaaaaaa아직 저장된 장비 세트가 없습니다. 위의 버튼으로 현재 장비를 저장하십시오.|r",
    ["Saved loadouts:"] = "저장된 장비 세트:",
    ["Usage: /loadout equip <name> | save <name> | delete <name> | list"] = "사용법: /loadout equip <name> | save <name> | delete <name> | list",
    ["Usage: /loadout delete <name>"] = "사용법: /loadout delete <name>",
    ["|cffaaaaaaSlash commands: /loadout save <name>, /loadout equip <name>, /loadout delete <name>, /loadout list. Short alias: /lo|r"] = "|cffaaaaaa슬래시 명령어: /loadout save <name>, /loadout equip <name>, /loadout delete <name>, /loadout list. 단축 명령: /lo|r",
    ["No account-wide loadouts to import."] = "가져올 계정 공용 장비 세트가 없습니다.",
    ["Imported %d account-wide loadout(s) onto this character."] = "계정 공용 장비 세트 %d개를 이 캐릭터로 가져왔습니다.",
    ["You have account-wide loadouts from an older version. Type /lo import to copy them onto this character."] = "이전 버전에서 저장한 계정 공용 장비 세트가 있습니다. /lo import 를 입력하면 이 캐릭터로 복사합니다.",
    ["Import from older version"] = "이전 버전에서 가져오기",
    ["|cffaaaaaaYou have gear sets saved account-wide by an older version. Loadouts are now per-character — import copies them onto THIS character.|r"] = "|cffaaaaaa이전 버전이 계정 공용으로 저장한 장비 구성이 있습니다. 장비 세트는 이제 캐릭터별로 저장되며, 가져오기를 하면 이 캐릭터로 복사됩니다.|r",
    ["Import account-wide loadouts"] = "계정 공용 장비 세트 가져오기",
    ["Head"] = "머리",
    ["Chest"] = "가슴",
    ["Feet"] = "발",
    ["Finger 1"] = "반지 1",
    ["Trinket 1"] = "장신구 1",
    ["Both trinkets"] = "장신구 둘 다",
    ["Set focus"] = "주시 대상 지정",
    ["Healing potion"] = "치유 물약",
    ["Macro Factory"] = "매크로 제작기",
    ["|cffaaaaaaOne click builds a ready-made macro (per character). Then open |cffffffff/macro|r and drag it onto your action bar. Works on any client — uses item slots / IDs, no English needed.|r"] = "|cffaaaaaa한 번 누르면 바로 쓸 수 있는 매크로가 만들어집니다(캐릭터별). 그다음 |cffffffff/macro|r 를 열어 행동 단축바로 끌어다 놓으십시오. 아이템 칸과 ID를 사용하므로 영어 없이 모든 클라이언트에서 작동합니다.|r",
    ["Macro Factory: can't create macros in combat."] = "매크로 제작기: 전투 중에는 매크로를 만들 수 없습니다.",
    ["Macro Factory: nothing to build (e.g. no healing potion in your bags)."] = "매크로 제작기: 만들 것이 없습니다(예: 가방에 치유 물약이 없음).",
    ["Macro Factory: couldn't create it (character macro slots full?)."] = "매크로 제작기: 만들지 못했습니다(캐릭터 매크로 칸이 가득 찼습니까?).",
    ["Macro '%s' updated — drag it from |cffffffff/macro|r onto your action bar."] = "매크로 ‘%s’을(를) 갱신했습니다 — |cffffffff/macro|r 에서 행동 단축바로 끌어다 놓으십시오.",
    ["Macro '%s' created — open |cffffffff/macro|r and drag it onto your action bar."] = "매크로 ‘%s’을(를) 만들었습니다 — |cffffffff/macro|r 를 열어 행동 단축바로 끌어다 놓으십시오.",
    ["Back"] = "등",
    ["Main Hand"] = "주장비",
    ["Save All..."] = "전체 저장...",
    ["Save Trinkets..."] = "장신구 저장...",
    ["Save Weapons..."] = "무기 저장...",
    ["Save current as new..."] = "현재 장비를 새로 저장...",
    ["Save trinkets only..."] = "장신구만 저장...",
    ["Save weapons only..."] = "무기만 저장...",
    ["Settings..."] = "설정...",
    ["Minimap Button"] = "미니맵 버튼",
    ["Left-click for a quick set-switcher menu, right-click to open settings, drag to reposition."] = "왼쪽 클릭하면 세트 전환 메뉴가 열리고, 오른쪽 클릭하면 설정이 열리며, 드래그하면 위치를 옮깁니다.",
    ["Left-click: switch set"] = "왼쪽 클릭: 세트 전환",
    ["Right-click: settings"] = "오른쪽 클릭: 설정",
    ["Drag: reposition"] = "드래그: 위치 이동",
    ["Auto-Switch on Stance/Form"] = "태세/변신 자동 전환",
    ["Enable auto-switching"] = "자동 전환 사용",
    ["Automatically equips a loadout when your stance/form changes (warrior stances, druid forms). Out-of-combat only — if a stance change happens in combat, the swap is deferred until combat ends."] = "태세나 변신이 바뀌면 장비 세트를 자동으로 착용합니다(전사 태세, 드루이드 변신). 전투 중이 아닐 때만 작동하며, 전투 중에 태세가 바뀌면 전투가 끝난 뒤 교체합니다.",
    ["Auto-equip on form"] = "변신 시 자동 착용",
    ["Equip this loadout automatically when the chosen stance/form is activated."] = "선택한 태세/변신이 활성화되면 이 장비 세트를 자동으로 착용합니다.",
    ["Auto-Switch on Dual Spec"] = "이중 특성 자동 전환",
    ["Enable spec auto-switching"] = "특성 자동 전환 사용",
    ["Automatically equips a loadout when you switch between Spec 1 and Spec 2 (dual spec). Bind each loadout to a spec below. Requires dual spec to be active."] = "특성 1과 특성 2를 전환할 때(이중 특성) 장비 세트를 자동으로 착용합니다. 아래에서 각 장비 세트를 특성에 연결하십시오. 이중 특성이 활성화되어 있어야 합니다.",
    ["Auto-equip on spec"] = "특성 전환 시 자동 착용",
    ["Equip this loadout automatically when you switch to this spec."] = "이 특성으로 전환하면 이 장비 세트를 자동으로 착용합니다.",
    ["None"] = "없음",
    ["No Form"] = "변신 없음",
    ["Form %d"] = "변신 %d",
    ["Character Frame Sidebar"] = "캐릭터 프레임 사이드바",
    ["Show sidebar on character frame"] = "캐릭터 프레임에 사이드바 표시",
    ["Attach a quick-access sidebar to the right of the character window. Click a set to select, double-click or button to equip, right-click for context menu."] = "캐릭터 창 오른쪽에 빠른 접근 사이드바를 붙입니다. 세트를 누르면 선택되고, 두 번 클릭하거나 버튼을 누르면 착용되며, 오른쪽 클릭하면 메뉴가 열립니다.",
    ["|cffaaaaaaTip: with the character window open, enable edit mode (Unlock) to drag the sidebar; right-click the purple box to reset its position.|r"] = "|cffaaaaaa도움말: 캐릭터 창을 연 상태에서 잠금 해제 모드(‘잠금 해제’)를 켜면 사이드바를 드래그할 수 있습니다. 보라색 상자를 오른쪽 클릭하면 위치가 초기화됩니다.|r",
    ["New Set"] = "새 세트",
    ["Left-click: select"] = "왼쪽 클릭: 선택",
    ["Double-click / Right-click menu: equip"] = "두 번 클릭 / 오른쪽 클릭 메뉴: 착용",
    ["Change icon..."] = "아이콘 변경...",
    ["Icon for: %s"] = "아이콘 대상: %s",
    ["Bind to %s"] = "%s에 연결",
    ["'%s' bound to %s."] = "‘%s’을(를) %s에 연결했습니다.",
    ["'%s' unbound from spec."] = "‘%s’의 특성 연결을 해제했습니다.",
    ["Replace: %s"] = "교체: %s",
    ["Remove from set"] = "세트에서 제거",
    ["Loadout '%s': slot updated."] = "장비 세트 ‘%s’: 칸을 갱신했습니다.",
    ["SlotPicker module is required for editing item slots."] = "아이템 칸을 편집하려면 SlotPicker 모듈이 필요합니다.",
    ["Empty: %s"] = "비어 있음: %s",
    ["in the bank"] = "은행에 있음",
    ["in bags, equip failed"] = "가방에 있으나 착용 실패",
    ["not found"] = "찾을 수 없음",
    ["missing"] = "없음",
    ["Part of set: %s"] = "세트에 포함: %s",
    ["Add a slot"] = "칸 추가",
    ["Re-adds an ignored slot to this set."] = "무시했던 칸을 이 세트에 다시 추가합니다.",
    ["Right-click: remove this slot from the set."] = "오른쪽 클릭: 이 칸을 세트에서 제거합니다.",
    ["Left-click to pick an item from your bags"] = "왼쪽 클릭하여 가방에서 아이템 고르기",
    ["(equipped)"] = "(착용 중)",
    ["Slot Picker"] = "칸 선택기",
    ["Enable slot picker"] = "칸 선택기 사용",
    ["|cffaaaaaaRight-click an equipment slot in the character window to see all compatible items from your bags and click one to equip it.|r"] = "|cffaaaaaa캐릭터 창에서 장비 칸을 오른쪽 클릭하면 가방 속 호환 아이템이 모두 표시되고, 하나를 누르면 착용합니다.|r",
    ["Hover an equipment slot in the Character frame for a compact flyout of compatible bag items, or modifier-click for a larger pinnable picker. Click an item to equip it (out-of-combat)."] = "캐릭터 프레임의 장비 칸에 마우스를 올리면 호환되는 가방 아이템이 간단한 띠로 펼쳐지고, 조합키와 함께 클릭하면 고정할 수 있는 더 큰 선택기가 열립니다. 아이템을 누르면 착용합니다(전투 중 제외).",
    ["Flyout on hover"] = "마우스를 올리면 펼치기",
    ["Hovering an equipment slot pops out a compact strip of items you can swap in — the paperdoll flyout look. Turn off to use only the modifier-click picker."] = "장비 칸에 마우스를 올리면 교체할 수 있는 아이템이 좁은 띠로 펼쳐집니다. 기본 장비 창의 펼침 메뉴와 같은 모양입니다. 끄면 조합키 클릭 선택기만 사용합니다.",
    ["Activation modifier"] = "실행 조합키",
    ["Choose which key combination opens the item picker when you click an equipment slot."] = "장비 칸을 클릭할 때 어떤 조합키로 아이템 선택기를 열지 고릅니다.",
    ["Shift + Right-click"] = "Shift + 오른쪽 클릭",
    ["Alt + Right-click"] = "Alt + 오른쪽 클릭",
    ["Ctrl + Right-click"] = "Ctrl + 오른쪽 클릭",
    ["Right-click only"] = "오른쪽 클릭만",
    ["Grid columns"] = "격자 열 수",
    ["How many item icons per row in the picker popup."] = "선택기 창에서 한 줄에 표시할 아이템 아이콘 개수입니다.",
    ["Items for: %s"] = "아이템 대상: %s",
    ["Close automatically on mouse-out"] = "마우스가 벗어나면 자동으로 닫기",
    ["The picker closes itself shortly after the mouse leaves it. Drag it once to pin it open until you close it manually."] = "마우스가 벗어나면 선택기가 잠시 뒤 스스로 닫힙니다. 한 번 드래그하면 직접 닫을 때까지 고정됩니다.",
    ["No matching items in your bags."] = "가방에 맞는 아이템이 없습니다.",
    ["Item scanning API not available on this client."] = "이 클라이언트에서는 아이템 검색 API를 사용할 수 없습니다.",
