    ["Auto (client language)"] = "자동(클라이언트 언어)",
    ["Choose the language for the VuloClassicUI interface. 'Auto' uses your WoW client's language (German clients see German, all others see English).\n\n|cffaaaaaaRequires /reload to apply.|r"] = "VuloClassicUI 인터페이스의 언어를 선택합니다. ‘자동’은 WoW 클라이언트의 언어를 따릅니다(독일어 클라이언트는 독일어, 그 외에는 영어).\\n\\n|cffaaaaaa적용하려면 /reload 가 필요합니다.|r",
