    ["Hides ready icons; they reappear when on cooldown."] = "준비된 아이콘을 숨기고, 재사용 대기 중이 되면 다시 나타납니다.",
    ["Show countdown text"] = "카운트다운 글자 표시",
    ["Show stacks"] = "중첩 수 표시",
    ["  |cffaa5555(other class)|r"] = "  |cffaa5555(다른 직업)|r",
    ["Edit mode — move the cooldown bars"] = "이동 모드 — 재사용 대기시간 바 옮기기",
    ["Stop editing — lock the cooldown bars"] = "편집 종료 — 재사용 대기시간 바 잠그기",
