    ["Hide cooldowns under (sec)"] = "숨길 재사용 대기시간 기준 (초)",
    ["Cooldowns at or below this are ignored. 1.5 hides the global cooldown; raise it to also hide short cooldowns; 0 shows everything."] = "이 값 이하의 재사용 대기시간은 무시합니다. 1.5로 두면 공용 재사용 대기시간이 숨겨지고, 값을 올리면 짧은 재사용 대기시간도 숨겨집니다. 0이면 모두 표시합니다.",
