    ["Top left"] = "왼쪽 위",
    ["Show reagent counts"] = "재료 개수 표시",
    ["Shows each spell's OWN reagent count — Soul Shards on Soul Fire, Infernal Stone on Inferno, etc. Spells without a reagent show nothing. Needs 'Show stacks' on."] = "각 주문에 필요한 재료의 개수를 표시합니다 — 영혼의 불꽃에는 영혼의 조각, 지옥 소환에는 지옥의 돌 등. 재료가 필요 없는 주문에는 아무것도 표시되지 않습니다. '중첩 수 표시'가 켜져 있어야 합니다.",
    ["Anchor"] = "고정",
    ["Anchor to"] = "고정 대상",
    ["Pin this bar to a unit frame, the minimap, or another group's bar — it then moves with it. Drag the bar to detach."] = "이 바를 유닛 프레임, 미니맵 또는 다른 그룹의 바에 고정하면 함께 움직입니다. 바를 끌면 고정이 풀립니다.",
