    ["How much is cut off each edge of the icon. 0 shows the whole icon including the border baked into its artwork."] = "아이콘의 각 가장자리에서 잘라낼 양입니다. 0이면 그림에 포함된 테두리까지 아이콘 전체를 표시합니다.",
