    ["Flash when ready"] = "준비되면 번쩍임",
    ["Saves named snapshots of your action bars, macros and keybindings, and restores them with one click."] = "행동 단축바, 매크로, 단축키 설정을 이름을 붙여 저장하고 한 번의 클릭으로 되돌립니다.",
    ["|cffaaaaaaSaves your complete bar setup (all action slots, macros, keybindings) as a named profile and restores it with one click — e.g. PvP and Raid layouts, or to copy a setup to a twink (account-wide storage).|r"] = "|cffaaaaaa전체 단축바 구성(모든 행동 슬롯, 매크로, 단축키)을 이름 붙인 프로필로 저장하고 한 번의 클릭으로 되돌립니다 — 예를 들어 PvP용과 공격대용 배치, 또는 부캐로 구성을 복사할 때 (계정 공용 저장).|r",
    ["Load"] = "불러오기",
    ["Save current setup"] = "현재 구성 저장",
    ["Please enter a profile name first."] = "먼저 프로필 이름을 입력하십시오.",
    ["|cff888888No profiles saved yet.|r"] = "|cff888888저장된 프로필이 없습니다.|r",
    ["Also restore macros"] = "매크로도 복원",
    ["Rewrites saved macros by name (existing ones are updated, missing ones created)."] = "저장된 매크로를 이름 기준으로 다시 씁니다 (기존 매크로는 갱신되고, 없는 매크로는 새로 만듭니다).",
    ["Also restore keybindings"] = "단축키도 복원",
    ["Load profile"] = "프로필 불러오기",
    ["Overwrite with current setup"] = "현재 구성으로 덮어쓰기",
    ["Replaces the selected profile with your current bars/macros/bindings."] = "선택한 프로필을 현재 단축바/매크로/단축키로 대체합니다.",
    ["Note: profile '%s' was saved on another class (%s)."] = "참고: 프로필 '%s'은(는) 다른 직업(%s)에서 저장되었습니다.",
    ["Flight Timer"] = "비행 시간 표시기",
    ["|cffff8800Flight route database not loaded.|r Fully restart WoW (a /reload is not enough after an update) so the flight times work."] = "|cffff8800비행 경로 데이터베이스를 불러오지 못했습니다.|r 비행 시간이 제대로 작동하도록 WoW를 완전히 재시작하십시오 (업데이트 후에는 /reload만으로는 부족합니다).",
    ["Show flight time bar"] = "비행 시간 바 표시",
    ["Shows destination and remaining time while on a taxi. The first flight of a route is learned, then you get a draining countdown."] = "비행 중에 목적지와 남은 시간을 표시합니다. 각 경로의 첫 비행에서 시간을 익히고, 그다음부터는 줄어드는 카운트다운을 보여줍니다.",
    ["Flight: %s (%s)"] = "비행: %s (%s)",
    ["Print flight time to chat"] = "비행 시간 대화창에 출력",
    ["After landing, prints the measured flight time."] = "착륙 후 측정된 비행 시간을 출력합니다.",
    ["Reset learned times"] = "익힌 시간 초기화",
    ["Deletes all saved route durations."] = "저장된 모든 경로 시간을 삭제합니다.",
    ["Learned flight times reset."] = "익힌 비행 시간이 초기화되었습니다.",
    ["|cffffffffFLIGHT TIME|r"] = "|cffffffff비행 시간|r",
    ["Flight timer: x=%.0f, y=%.0f"] = "비행 시간 표시기: x=%.0f, y=%.0f",
    ["Flight timer mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "비행 시간 표시기 이동 모드가 켜졌습니다. |cff9b6cff끌기|r 또는 |cff9b6cff방향키|r로 옮기십시오 (SHIFT = 5픽셀).",
    ["Flight timer mover disabled."] = "비행 시간 표시기 이동 모드가 꺼졌습니다.",
    ["Flight debug on — take a flight, the resolution appears in the chat."] = "비행 디버그 켬 — 비행하면 확인 결과가 채팅창에 표시됩니다.",
