    ["|cffaaaaaaOpen manually with /lazyvulo or /lv.|r"] = "|cffaaaaaa/lazyvulo 또는 /lv 명령으로 직접 열 수 있습니다.|r",
    ["Auto-show at the Apexis Relic"] = "에펙시스 유물에서 자동 표시",
    ["Opens the window automatically when you start the relic minigame."] = "유물 미니게임을 시작하면 창을 자동으로 엽니다.",
    ["Enable hotkeys while the window is shown"] = "창이 열려 있는 동안 단축키 사용",
