    ["|cffaaaaaaOne key per color (e.g. G, Y, B, R or NUMPAD1). Empty = no hotkey.|r"] = "|cffaaaaaa색상마다 키를 하나씩 지정합니다 (예: G, Y, B, R 또는 NUMPAD1). 비워 두면 단축키를 사용하지 않습니다.|r",
