    ["Not possible in combat."] = "전투 중에는 할 수 없습니다.",
    ["DB reset. UI reloading."] = "DB가 초기화되었습니다. UI를 다시 불러옵니다.",
    ["Debug = %s"] = "디버그 = %s",
