    ["Maximum camera distance (CVar cameraDistanceMaxZoomFactor)."] = "최대 카메라 거리 (CVar cameraDistanceMaxZoomFactor).",
    ["Show Minimap Button"] = "미니맵 버튼 표시",
    ["Toggle the VuloClassicUI button on the minimap."] = "미니맵의 VuloClassicUI 버튼을 켜거나 끕니다.",
    ["Show CPU Usage in Header"] = "헤더에 CPU 사용량 표시",
    ["Shows total CPU usage of all active addons (plus VuloClassicUI's own share) at the top of the config header.\n\n|cffaaaaaaRequires /reload after toggling.\n\nNote: Enables WoW's scriptProfile CVar, which costs ~3-5% performance — that's the price for WoW collecting this data at all.|r"] = "활성화된 모든 애드온의 총 CPU 사용량(VuloClassicUI 자체 사용량 포함)을 설정 헤더 상단에 표시합니다.\\n\\n|cffaaaaaa전환 후 /reload 가 필요합니다.\\n\\n참고: WoW의 scriptProfile CVar를 활성화하며, 약 3~5%의 성능을 소모합니다. WoW가 이 자료를 수집하기 위해 치르는 대가입니다.|r",
    ["Script profiling changed. /reload required for the CPU display to update."] = "스크립트 프로파일링이 변경되었습니다. CPU 표시를 갱신하려면 /reload 가 필요합니다.",
    ["Reload now"] = "지금 다시 불러오기",
    ["Later"] = "나중에",
    ["Shows a button on the minimap to quickly open VuloClassicUI. Shift+drag moves the button."] = "미니맵에 VuloClassicUI를 빠르게 여는 버튼을 표시합니다. Shift+드래그로 버튼을 옮길 수 있습니다.",
    ["UI is not loaded yet."] = "UI가 아직 준비되지 않았습니다.",
    ["|cffffffffLeft click:|r Open options"] = "|cffffffff왼쪽 클릭:|r 설정 열기",
    ["|cffffffffRight click:|r Quick module selection"] = "|cffffffff오른쪽 클릭:|r 모듈 빠른 선택",
    ["|cffffffffShift+drag:|r Move button"] = "|cffffffffShift+드래그:|r 버튼 이동",
    ["Open Options"] = "설정 열기",
    ["Show button on minimap"] = "미니맵에 버튼 표시",
    ["If off, the button is completely hidden."] = "끄면 버튼이 완전히 숨겨집니다.",
    ["Distance from center"] = "중심에서의 거리",
    ["Angle (degrees)"] = "각도 (도)",
    ["Tip: You can also move the button directly on the minimap — hold Shift and drag it to the desired position."] = "팁: 미니맵에서 버튼을 직접 옮길 수도 있습니다. Shift를 누른 채 원하는 위치로 드래그하세요.",
    ["Font Bars"] = "바 글꼴",
    ["Smaller font sizes for Player/Target/Pet Health & Mana bars, optionally hide TargetFrameBackground."] = "플레이어/대상/소환수 생명력 및 마나 바의 글꼴 크기를 줄이고, 선택적으로 TargetFrameBackground를 숨깁니다.",
    ["Health Bar Text"] = "생명력 바 글자",
    ["Font size on health bars (Player/Target/Pet)."] = "생명력 바의 글꼴 크기입니다 (플레이어/대상/소환수).",
    ["Power Bar Text"] = "자원 바 글자",
    ["Font size on mana/power bars."] = "마나/자원 바의 글꼴 크기입니다.",
    ["Pet Combat Feedback Text"] = "소환수 전투 정보 글자",
    ["Font size for 'Damage', 'Dodge', 'Miss' on the pet."] = "소환수에 표시되는 ‘피해’, ‘회피’, ‘빗나감’의 글꼴 크기입니다.",
    ["Only affect Player/Target/Pet bars"] = "플레이어/대상/소환수 바에만 적용",
    ["If off: all TextStatusBars in the UI are overridden with the sizes above (may interfere with other addons)."] = "끄면 UI의 모든 TextStatusBar가 위 크기로 덮어쓰기됩니다 (다른 애드온과 충돌할 수 있습니다).",
    ["Hide TargetFrame background"] = "TargetFrame 배경 숨기기",
    ["Permanently hides the dark background element of the TargetFrame."] = "TargetFrame의 어두운 배경 요소를 영구적으로 숨깁니다.",
    ["Target Frame"] = "대상 프레임",
    ["|cffaaaaaaAdds the modern Target/Focus frame extras the default Anniversary UI is missing - all cosmetic, no taint.|r"] = "|cffaaaaaa기본 Anniversary UI에 없는 최신 대상/주시 대상 프레임 기능을 추가합니다. 모두 외형 요소이며 보호된 코드를 오염시키지 않습니다.|r",
    ["Numeric threat %"] = "숫자 위협 수준(%)",
    ["Shows your threat percentage on the target (and focus) above the frame, coloured by threat status."] = "대상(및 주시 대상)에 대한 위협 수준 비율을 프레임 위에 표시하고 위협 상태에 따라 색을 입힙니다.",
    ["Threat glow"] = "위협 발광 효과",
    ["Glows the target (and focus) frame in yellow/orange/red as your threat rises."] = "위협 수준이 오르면 대상(및 주시 대상) 프레임을 노랑/주황/빨강으로 빛나게 합니다.",
    ["Rare-Elite border"] = "희귀 정예 테두리",
    ["Shows the winged silver-dragon Rare-Elite border on rare-elite mobs."] = "희귀 정예 몹에 은빛 용 날개 모양의 희귀 정예 테두리를 표시합니다.",
    ["Class icon on player targets"] = "플레이어 대상에 직업 아이콘 표시",
    ["Shows the target's class crest on the frame when you target a player."] = "플레이어를 대상으로 지정하면 프레임에 대상의 직업 문장을 표시합니다.",
    ["Also apply to the Focus frame"] = "주시 대상 프레임에도 적용",
    ["Health"] = "생명력",
    ["Show real NPC health"] = "NPC 실제 생명력 표시",
    ["Shows the true health value on NPCs instead of the obfuscated percentage (enemy players stay %)."] = "NPC에게 가려진 비율 대신 실제 생명력 수치를 표시합니다 (적 플레이어는 비율로 유지).",
    ["Player Castbar"] = "플레이어 시전 바",
    ["Player castbar with two modes: Original (Blizzard bar extended) or Custom castbar (VUI style)."] = "두 가지 방식의 플레이어 시전 바: 기본형(Blizzard 바 확장) 또는 사용자 지정 시전 바(VUI 스타일).",
    ["|cffffffffCASTBAR|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffff시전 바|r\\n|cffaaaaaa드래그 또는 방향키|r",
    ["Castbar position: x=%.0f, y=%.0f"] = "시전 바 위치: x=%.0f, y=%.0f",
    ["|cff9b6cffMind Flay|r"] = "|cff9b6cff정신 채찍|r",
    ["Castbar mover active. |cff9b6cffDrag purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "시전 바 이동 모드 활성화. |cff9b6cff보라색 상자를 드래그|r하거나 |cff9b6cff방향키|r를 사용하세요 (SHIFT = 5픽셀). 마치려면 ‘잠금 해제 / 시험’을 다시 클릭하세요.",
    ["Castbar mover disabled."] = "시전 바 이동 모드 해제.",
    ["Castbar Variant"] = "시전 바 종류",
    ["Switch between Original (Blizzard bar extended) and Custom castbar (VUI style with icon, spell name below bar)."] = "기본형(Blizzard 바 확장)과 사용자 지정 시전 바(아이콘과 바 아래 주문 이름이 있는 VUI 스타일) 사이를 전환합니다.",
    ["Original (Blizzard bar extended)"] = "기본형 (Blizzard 바 확장)",
    ["Custom Castbar (VUI style)"] = "사용자 지정 시전 바 (VUI 스타일)",
    ["Castbar mode switched to |cff9b6cffOriginal|r. |cffffff00/reload|r recommended so the default bar works normally again."] = "시전 바 방식이 |cff9b6cff기본형|r으로 전환되었습니다. 기본 바가 다시 정상 작동하도록 |cffffff00/reload|r 를 권장합니다.",
    ["Castbar mode switched to |cff9b6cffVUI Style|r."] = "시전 바 방식이 |cff9b6cffVUI 스타일|r로 전환되었습니다.",
    ["|cffaaaaaaMode switch: A /reload may be required after switching so the default bar works normally again.|r"] = "|cffaaaaaa방식 전환: 전환 후 기본 바가 다시 정상 작동하려면 /reload 가 필요할 수 있습니다.|r",
    ["Show spell name"] = "주문 이름 표시",
    ["Show cast timer"] = "시전 시간 표시",
    ["Show channel ticks"] = "지속 시전 틱 표시",
    ["Shows vertical lines at tick points (Mind Flay, Drain Soul, Hellfire, etc.)"] = "지속 시전의 틱 지점에 세로선을 표시합니다 (정신 채찍, 영혼 흡수, 지옥불 등).",
    ["Show clip window"] = "지연 구간 표시",
    ["Shades your latency at the end of the bar: on channels the moment to recast without losing the last tick, on casts the spell-queue window where the next cast can already be pressed."] = "바 끝에 지연 시간을 어둡게 표시합니다. 지속 시전에서는 마지막 틱을 잃지 않고 다시 시전할 시점을, 일반 시전에서는 다음 시전을 미리 누를 수 있는 주문 대기열 구간을 나타냅니다.",
    ["Timer format"] = "시간 표시 형식",
    ["Remaining / total (1.5 / 2.0)"] = "남은 시간 / 전체 (1.5 / 2.0)",
    ["Remaining only (1.5)"] = "남은 시간만 (1.5)",
    ["Whole seconds (2)"] = "초 단위 정수 (2)",
    ["Show pushback"] = "시전 지연 표시",
    ["Briefly shows the time lost to spell pushback in red above the bar."] = "주문 시전 지연으로 잃은 시간을 바 위에 빨간색으로 잠깐 표시합니다.",
    ["Merge crafting casts"] = "제작 시전 합치기",
    ["When crafting several items in a row the bar shows a counter like 3/20 instead of single casts."] = "여러 개를 연속으로 제작할 때 개별 시전 대신 3/20 같은 진행 횟수를 바에 표시합니다.",
    ["Fill color"] = "채움 색상",
    ["Bar textures = the classic yellow/green art. Accent or class color tint a neutral bar instead."] = "바 텍스처 = 고전적인 노랑/초록 이미지입니다. 강조 색상이나 직업 색상은 무채색 바에 색을 입힙니다.",
    ["Bar textures (yellow/green)"] = "바 텍스처 (노랑/초록)",
    ["Accent color"] = "강조 색상",
    ["VUI Style: Position & Size"] = "VUI 스타일: 위치 및 크기",
    ["Unlock / Test"] = "잠금 해제 / 시험",
    ["Center Position"] = "중앙 위치",
    ["|cffaaaaaaTip: Hold |cffffffffSHIFT|r and drag the castbar with the left mouse button during a cast to move it. Or use 'Unlock / Test' for a permanent test bar for positioning.|r"] = "|cffaaaaaa팁: 시전 중에 |cffffffffSHIFT|r를 누른 채 왼쪽 마우스 버튼으로 시전 바를 드래그하면 옮길 수 있습니다. 또는 ‘잠금 해제 / 시험’으로 고정된 시험용 바를 띄워 위치를 맞추세요.|r",
    ["Show icon"] = "아이콘 표시",
    ["Icon Size"] = "아이콘 크기",
    ["Icon X Offset"] = "아이콘 X 오프셋",
    ["Icon Y Offset"] = "아이콘 Y 오프셋",
    ["Moves the icon horizontally. Negative = left, positive = right."] = "아이콘을 좌우로 옮깁니다. 음수 = 왼쪽, 양수 = 오른쪽.",
    ["Moves the icon vertically. Positive = up, negative = down."] = "아이콘을 위아래로 옮깁니다. 양수 = 위쪽, 음수 = 아래쪽.",
    ["Test only available in 'Custom Castbar' mode."] = "시험은 ‘사용자 지정 시전 바’ 방식에서만 사용할 수 있습니다.",
    ["Cooldown Pulse"] = "재사용 대기시간 펄스",
    ["Shows the icon of an expired cooldown as a brief pulsing animation in the screen center."] = "재사용 대기시간이 끝난 주문의 아이콘을 화면 중앙에 잠깐 확대되는 애니메이션으로 표시합니다.",
    ["Test Spell"] = "시험용 주문",
    ["Cooldown Pulse position reset."] = "재사용 대기시간 펄스 위치가 초기화되었습니다.",
    ["Test Pulse"] = "시험 펄스",
    ["Plays a test animation."] = "시험 애니메이션을 재생합니다.",
    ["Reset Position"] = "위치 초기화",
    ["Max Opacity"] = "최대 불투명도",
    ["Animation Scale"] = "애니메이션 배율",
    ["Fade-In Time (s)"] = "나타나는 시간 (초)",
    ["Hold Time (s)"] = "유지 시간 (초)",
    ["Fade-Out Time (s)"] = "사라지는 시간 (초)",
    ["Show Before Available (s)"] = "사용 가능 전 표시 (초)",
    ["Triggers the animation X seconds BEFORE the cooldown expires. 0 = exactly at cooldown end."] = "재사용 대기시간이 끝나기 X초 전에 애니메이션을 시작합니다. 0 = 대기시간이 끝나는 시점.",
    ["Spell Filter"] = "주문 필터",
    ["Show spell names"] = "주문 이름 표시",
    ["Shows the name of the spell under the icon."] = "아이콘 아래에 주문 이름을 표시합니다.",
    ["Invert filter (whitelist instead of blacklist)"] = "필터 반전 (차단 목록 대신 허용 목록)",
    ["Off: List = ignored spells. On: List = show ONLY these spells."] = "끔: 목록 = 무시할 주문. 켬: 목록 = 이 주문만 표시.",
    ["Spell List (comma-separated)"] = "주문 목록 (쉼표로 구분)",
    ["Spell names exactly as in-game, comma-separated. Spell IDs also work."] = "게임에 표시되는 그대로의 주문 이름을 쉼표로 구분해 입력하세요. 주문 ID도 사용할 수 있습니다.",
    ["Arena Frames"] = "투기장 프레임",
    ["Enhances the Arena enemy frames: move/scale, class colors, class icons, PvP trinket CD, DR tracking, castbar, drag&drop layout."] = "투기장 적 프레임을 개선합니다: 이동/배율, 직업 색상, 직업 아이콘, PvP 장신구 재사용 대기시간, 효과 감소(DR) 추적, 시전 바, 드래그 앤 드롭 배치.",
    ["|cffff5555ArenaFrames submodule error:|r %s"] = "|cffff5555ArenaFrames 하위 모듈 오류:|r %s",
    ["|cffff5555Arena submodule OnEnable error:|r %s"] = "|cffff5555투기장 하위 모듈 OnEnable 오류:|r %s",
    ["Layout"] = "배치",
    ["Class Color"] = "직업 색상",
    ["PvP Trinket"] = "PvP 장신구",
    ["DR Tracker"] = "효과 감소(DR) 추적기",
    ["Castbar"] = "시전 바",
    ["ArenaPlayer"] = "ArenaPlayer",
    ["Reset position"] = "위치 초기화",
    ["Position reset."] = "위치가 초기화되었습니다.",
    ["In unlock mode a purple overlay appears above the frames. Click + drag to move, mouse wheel to scale."] = "잠금 해제 상태에서는 프레임 위에 보라색 오버레이가 나타납니다. 클릭 + 드래그로 옮기고 마우스 휠로 배율을 조절하세요.",
    ["Layout (Order)"] = "배치 (순서)",
    ["Order of the arena frames. Use up/down to move slots 1-5."] = "투기장 프레임의 순서입니다. 위/아래로 1~5번 자리를 옮기세요.",
    ["|cff9b6cff%d.|r  Arena Slot %d"] = "|cff9b6cff%d.|r  투기장 자리 %d",
    ["Move up"] = "위로 이동",
    ["Move down"] = "아래로 이동",
