    ["Show sidebar"] = "사이드바 표시",
    ["A collapsible left panel for view modes and category filtering."] = "보기 방식과 분류 필터를 담은 접을 수 있는 왼쪽 패널입니다.",
    ["Collapse sidebar"] = "사이드바 접기",
    ["Expand sidebar"] = "사이드바 펼치기",
