    ["Show category: %s"] = "분류 표시: %s",
    ["Reset category order"] = "분류 순서 초기화",
    ["|cffaaaaaaTip: drag an item onto a category in the sidebar to keep it there; right-click a category to rename, move or delete it.|r"] = "|cffaaaaaa도움말: 사이드바의 분류로 아이템을 끌어다 놓으면 그 분류에 유지됩니다. 분류를 오른쪽 클릭하면 이름 변경, 이동, 삭제할 수 있습니다.|r",
    ["Pinned Items"] = "고정한 아이템",
    ["Recent Items"] = "최근 아이템",
    ["Show Recent Items"] = "최근 아이템 표시",
    ["Show a 'Recent Items' section for new item types you gain; it clears when you close the bag."] = "새로 얻은 아이템 종류를 모은 ‘최근 아이템’ 구역을 표시합니다. 가방을 닫으면 비워집니다.",
    ["Recent items kept"] = "보관할 최근 아이템 수",
