    ["Clear recent"] = "최근 목록 지우기",
    ["Unpin all items"] = "모든 아이템 고정 해제",
    ["|cffaaaaaaTip: middle-click an item to pin it to the top; middle-click again to unpin.|r"] = "|cffaaaaaa도움말: 아이템을 가운데 클릭하면 맨 위에 고정되고, 다시 가운데 클릭하면 고정이 해제됩니다.|r",
    ["New group..."] = "새 그룹...",
