    ["|cff9b6cffButton border / icon style lives in the Dark Skin module (Action Bars > Bar style): square, accent edge, shadow and more.|r"] = "|cff9b6cff버튼 테두리 / 아이콘 스타일은 다크 스킨 모듈에 있습니다 (행동 단축바 > 바 스타일): 사각형, 강조 테두리, 그림자 등.|r",
    ["Game Menu"] = "게임 메뉴",
    ["Game menu: VuloUI look"] = "게임 메뉴: VuloUI 스타일",
    ["Restyles the Escape menu to match the addon look: dark panel, flat buttons, accent title. Changing this needs a /reload."] = "Esc 메뉴를 애드온 스타일에 맞게 바꿉니다: 어두운 패널, 평면 버튼, 강조 제목. 이 설정을 바꾸려면 /reload 가 필요합니다.",
    ["Game menu: VuloClassicUI button"] = "게임 메뉴: VuloClassicUI 버튼",
    ["Adds a VuloClassicUI button to the Escape menu that opens the options window. Turning this off needs a /reload."] = "Esc 메뉴에 옵션 창을 여는 VuloClassicUI 버튼을 추가합니다. 이 설정을 끄려면 /reload 가 필요합니다.",
