    ["Timer decimals below 10 seconds"] = "10초 미만일 때 소수점 표시",
    ["Interrupted by %s"] = "%s에게 시전 방해됨",
    ["Value + percent"] = "수치 + 백분율",
    ["Value + percent layout"] = "수치 + 백분율 배치",
    ["Short values (12.3k)"] = "짧은 수치 (12.3k)",
    ["Show percent sign"] = "백분율 기호 표시",
    ["Smooth health changes"] = "부드러운 생명력 변화",
    ["The bar glides to the new value; a bright trail marks health draining away."] = "바가 새 값으로 부드럽게 움직이고, 밝은 잔상이 빠져나가는 생명력을 보여줍니다.",
    ["Tint background with bar colour"] = "배경을 바 색으로 물들이기",
    ["The empty part of the bar shows a darkened shade of the bar colour instead of plain dark grey."] = "바의 빈 부분이 단순한 진회색 대신 바 색을 어둡게 한 색으로 표시됩니다.",
    ["Glow at the bar edge"] = "바 끝 광채",
    ["A soft glow rides the end of the fill, tinted in the bar's own colour. Also applies to the cast bar."] = "채워진 부분의 끝을 따라 바 자체 색으로 물든 부드러운 광채가 움직입니다. 시전 바에도 적용됩니다.",
    ["Edge glow width"] = "끝 광채 너비",
    ["Rounded bar corners"] = "둥근 바 모서리",
    ["Clips the fill and background to a rounded shape. The line border stays square, so a thin border may show slightly at the corners."] = "채우기와 배경을 둥근 모양으로 잘라냅니다. 선 테두리는 각진 상태로 남으므로 모서리에 얇은 테두리가 살짝 보일 수 있습니다.",
    ["Overall plate scale (%)"] = "전체 이름표 크기 비율 (%)",
    ["Scales every plate at once, on top of each individual size."] = "각 이름표의 개별 크기 위에 모든 이름표의 크기를 한 번에 조절합니다.",
    ["Vertical offset"] = "세로 오프셋",
    ["Moves every plate up or down relative to its unit."] = "모든 이름표를 해당 대상 기준으로 위아래로 이동합니다.",
    ["Font outline"] = "글꼴 외곽선",
    ["How plate text is lifted off the background."] = "이름표 글자를 배경에서 얼마나 도드라지게 할지 정합니다.",
    ["Thick outline"] = "굵은 외곽선",
    ["Show level"] = "레벨 표시",
    ["Shows the unit level to the left of the name; ?? means the level is far above yours."] = "이름 왼쪽에 대상의 레벨을 표시합니다. ??는 자신보다 훨씬 높은 레벨을 뜻합니다.",
    ["Mark rare and elite"] = "희귀 및 정예 표시",
    ["Appends a rank to the level and turns it gold: + elite, R rare, R+ rare elite, B world boss."] = "레벨 뒤에 등급을 붙이고 금색으로 표시합니다: + 정예, R 희귀, R+ 희귀 정예, B 월드 보스.",
    ["Level size"] = "레벨 크기",
    ["0 = uses the name size."] = "0 = 이름 크기 사용.",
    ["Emphasise casting units"] = "시전 중인 대상 강조",
    ["While a unit casts, its plate grows a little and stays readable even when something else is targeted."] = "대상이 주문을 시전하는 동안 이름표가 조금 커지고, 다른 대상을 지정해도 잘 보이도록 유지됩니다.",
    ["Casting scale (%)"] = "시전 중 크기 비율 (%)",
    ["Casting opacity (%)"] = "시전 중 불투명도 (%)",
    ["Colour border by school"] = "계열별 테두리 색",
    ["Aura borders take the colour of their school: magic blue, curse purple, disease orange, poison green."] = "오라 테두리가 해당 계열의 색을 따릅니다: 마법 파랑, 저주 보라, 질병 주황, 독 초록.",
    ["Flash before running out"] = "지속시간이 끝나기 전 깜빡임",
    ["The icon pulses over the last part of its duration, so you can see when to refresh."] = "지속시간의 마지막 구간에서 아이콘이 고동쳐, 다시 걸어야 할 때를 알 수 있습니다.",
    ["Flash below (%)"] = "깜빡임 시작 지점 (%)",
    ["Your Own Debuffs"] = "자신이 건 약화 효과",
    ["|cffaaaaaaA separate row for the harmful auras you cast yourself - your damage-over-time timers, kept away from everything else on the target.|r"] = "|cffaaaaaa자신이 시전한 해로운 오라만 따로 표시하는 줄입니다 - 대상에 걸린 다른 효과와 떨어진 곳에서 자신의 지속 피해 시간을 확인할 수 있습니다.|r",
    ["Show your own debuffs (separate row)"] = "자신의 약화 효과 표시 (별도 줄)",
    ["Max icons"] = "최대 아이콘 수",
    ["Icons per line"] = "줄당 아이콘 수",
    ["0 = one line. Otherwise the row wraps after this many icons."] = "0 = 한 줄. 그 외에는 이 개수마다 줄이 바뀝니다.",
    ["Reminders"] = "알림",
    ["|cffaaaaaaShows a short row of icons for what you are missing right now. Out of combat a click casts or uses the fix; hovering explains what it wants. The row holds still during combat.|r"] = "|cffaaaaaa지금 빠져 있는 것을 짧은 아이콘 줄로 보여줍니다. 전투 중이 아닐 때 클릭하면 해당 주문을 시전하거나 아이템을 사용하고, 마우스를 올리면 무엇이 필요한지 설명합니다. 전투 중에는 줄이 움직이지 않습니다.|r",
    ["Also warn about empty equipment slots"] = "빈 장비 칸도 경고",
    ["Off by default: a ring, trinket or cloak is often legitimately empty while levelling."] = "기본값은 꺼짐: 육성 중에는 반지, 장신구, 망토 칸이 비어 있는 것이 정상인 경우가 많습니다.",
    ["Shows what you are missing - class buffs, weapon enchants, food, stance, pet, ammo, durability, empty gear slots and unspent talent points."] = "빠져 있는 것을 보여줍니다 - 직업 강화 효과, 무기 마법부여, 음식, 태세, 소환수, 탄약, 내구도, 빈 장비 칸, 사용하지 않은 특성 점수.",
    ["What to watch"] = "감시할 항목",
    ["Class buffs"] = "직업 강화 효과",
    ["Weapon enchants"] = "무기 마법부여",
    ["Stance and aura"] = "태세 및 오라",
    ["Food and flask"] = "음식 및 플라스크",
    ["Ammo, durability, gear, talents"] = "탄약, 내구도, 장비, 특성",
    ["Most icons at once"] = "한 번에 표시할 최대 아이콘 수",
    ["Anything past this is bundled into a single counter instead of adding another icon."] = "이 개수를 넘는 항목은 아이콘을 더 만들지 않고 하나의 숫자로 묶입니다.",
    ["Show labels"] = "설명 글자 표시",
    ["Settle time (seconds)"] = "확인 지연 시간 (초)",
    ["How long something must stay missing before an icon appears. Stops it flickering between casts."] = "아이콘이 나타나기까지 항목이 빠져 있어야 하는 시간입니다. 시전 사이에 깜빡이는 것을 막아 줍니다.",
    ["Warn when under (seconds)"] = "남은 시간이 이보다 적으면 경고 (초)",
    ["Also warn while a buff or weapon enchant is about to run out. 0 = only warn when it is gone."] = "강화 효과나 무기 마법부여가 곧 끝날 때도 경고합니다. 0 = 완전히 사라졌을 때만 경고.",
    ["Durability below (%)"] = "내구도가 이보다 낮을 때 (%)",
    ["Ammo below"] = "탄약이 이보다 적을 때",
    ["Quiet while resting"] = "휴식 지역에서는 알리지 않음",
    ["No reminders in a city or inn."] = "도시나 여관에서는 알림을 표시하지 않습니다.",
    ["Quiet while eating or drinking"] = "먹거나 마시는 중에는 알리지 않음",
    ["Click to cast."] = "클릭하면 시전합니다.",
    ["Missing: %s"] = "빠짐: %s",
    ["Main hand"] = "주장비",
    ["Off hand"] = "보조장비",
    ["No weapon enchant: %s"] = "무기 마법부여 없음: %s",
    ["Weapon enchant running out: %s"] = "무기 마법부여 종료 임박: %s",
    ["Stance"] = "태세",
    ["No stance active"] = "활성화된 태세 없음",
    ["Aura"] = "오라",
    ["No aura active"] = "활성화된 오라 없음",
    ["Pet"] = "소환수",
    ["No pet out"] = "소환수 없음",
    ["Passive"] = "소극적",
    ["Pet is set to passive"] = "소환수가 소극적으로 설정됨",
    ["Food"] = "음식",
    ["Not well fed"] = "잘 먹은 상태 아님",
    ["Flask"] = "플라스크",
    ["No flask or elixir"] = "플라스크나 비약 없음",
    ["Low ammo: %d left"] = "탄약 부족: %d개 남음",
    ["Equipment damaged: %d%% left"] = "장비 손상: 내구도 %d%% 남음",
    ["Empty equipment slots: %d"] = "빈 장비 칸: %d개",
    ["Unspent talent points: %d"] = "사용하지 않은 특성 점수: %d",
    ["Racials"] = "종족 특성",
    ["Racial Cooldowns"] = "종족 특성 재사용 대기시간",
    ["Shows the opponent's racial ability and its cooldown once they use it. These are this expansion's cooldowns, and no racial shares one with the PvP trinket yet."] = "상대가 종족 특성을 사용하면 해당 능력과 재사용 대기시간을 표시합니다. 이 확장팩 기준 대기시간이며, 아직 PvP 장신구와 대기시간을 공유하는 종족 특성은 없습니다.",
    ["Show racial cooldown"] = "종족 특성 대기시간 표시",
    ["Shadow Sight"] = "어둠의 시야",
    ["Shadow Sight up"] = "어둠의 시야 등장",
    ["Shadow Sight up - next in %d s"] = "어둠의 시야 등장 - 다음까지 %d초",
    ["Shadow Sight in %d s"] = "어둠의 시야까지 %d초",
    ["Counts down the arena orbs: the first pair appears 95 seconds after the gates open, and each one returns 122 seconds after it is taken."] = "투기장 구슬을 초읽기합니다: 첫 한 쌍은 문이 열린 뒤 95초에 나타나고, 이후 각 구슬은 획득된 뒤 122초 만에 다시 나타납니다.",
    ["Show Shadow Sight timer"] = "어둠의 시야 시간 표시",
    ["Aura on the class icon"] = "직업 아이콘 위 오라",
    ["Puts the single most relevant aura on the opponent's class icon: an immunity outranks crowd control, which outranks a defensive, which outranks an offensive cooldown."] = "상대의 직업 아이콘에 가장 중요한 오라 하나를 표시합니다: 무적 효과가 군중 제어보다, 군중 제어가 방어 기술보다, 방어 기술이 공격 기술 대기시간보다 우선합니다.",
    ["Show aura on the class icon"] = "직업 아이콘에 오라 표시",
    ["Crowd control only"] = "군중 제어만",
    ["Dispels"] = "해제",
    ["Dispel Cooldowns"] = "해제 재사용 대기시간",
    ["|cffaaaaaaMost dispels have no cooldown in this expansion, so only Mass Dispel and the felhunter's Devour Magic can ever show up here.|r"] = "|cffaaaaaa이 확장팩에서는 대부분의 해제 주문에 재사용 대기시간이 없어서, 여기에는 집단 무효화와 지옥사냥개의 마법 삼키기만 표시될 수 있습니다.|r",
    ["Show dispel cooldown"] = "해제 대기시간 표시",
    ["Range"] = "거리",
    ["Fades the frame while the opponent is out of reach, measured with a spell your class knows rather than a fixed distance."] = "상대가 사정거리 밖에 있는 동안 프레임을 흐리게 합니다. 고정된 거리 대신 자신의 직업이 아는 주문으로 측정합니다.",
    ["Fade out-of-range opponents"] = "사정거리 밖 상대 흐리게",
    ["Discard changes and revert every window to the last save point, or to how it was when Edit Mode opened."] = "변경 사항을 버리고 모든 창을 마지막 저장 시점 또는 편집 모드를 열었을 때의 상태로 되돌립니다.",
    ["Discard all changes made since the last save?"] = "마지막 저장 이후의 모든 변경 사항을 버릴까요?",
    ["Grey out when you walk out of range"] = "사정거리를 벗어나면 회색으로 표시",
    ["Drains the colour while you are outside a totem's radius, and restores it when you step back in. Recognised from the buff the totem puts on you, so totems that grant no buff (Searing, Magma, Tremor, ...) always stay lit."] = "토템의 반경 밖에 있는 동안 색을 빼고, 다시 들어가면 되돌립니다. 토템이 거는 강화 효과로 인식하므로, 강화 효과를 주지 않는 토템(불태우기, 마그마, 진동 등)은 항상 밝게 유지됩니다.",
    ["Limit to"] = "표시 대상",
    ["Everything"] = "전체",
    ["Only mine"] = "내 것만",
    ["Only removable"] = "해제 가능한 것만",
    ["Narrows this row to auras you cast yourself, or to ones that can be removed."] = "이 줄을 자신이 시전한 오라 또는 해제할 수 있는 오라로 좁힙니다.",
    ["Nudges every aura row at once, on top of each row's own offset."] = "각 줄의 개별 오프셋 위에 모든 오라 줄을 한 번에 이동합니다.",
    ["Share of the remaining duration at which the pulse starts."] = "고동침이 시작되는 남은 지속시간의 비율입니다.",
    ["Own colour while your interrupt is ready"] = "시전 방해 준비 시 별도 색",
    ["Interruptible casts paint in this colour while your interrupt is off cooldown — kick at will."] = "자신의 시전 방해 기술이 대기시간이 아닐 때 방해 가능한 시전이 이 색으로 표시됩니다 — 언제든 끊을 수 있습니다.",
    ["Interrupt-ready colour"] = "방해 준비 색",
    ["Own colour while channelling"] = "정신 집중 중 별도 색",
    ["Channel colour"] = "정신 집중 색",
    ["Own colour when the cast targets YOU"] = "시전 대상이 자신일 때 별도 색",
    ["The bar turns this colour while the caster's target is you."] = "시전자의 대상이 자신일 때 바가 이 색으로 바뀝니다.",
    ["Targets-you colour"] = "자신 대상 색",
    ["Show who interrupted"] = "방해한 대상 표시",
    ["The interrupt flash shows the name of whoever landed the interrupt."] = "시전 방해 섬광에 방해에 성공한 대상의 이름이 표시됩니다.",
    ["On: 9.9, 3.4 … Off: whole seconds (9, 3)."] = "켬: 9.9, 3.4 … 끔: 정수 초 (9, 3).",
    ["Modern puts the real bag buttons on a flat dark strip in the VuloUI look — opening, swapping and tooltips stay identical."] = "모던은 실제 가방 버튼을 VuloUI 스타일의 평면 어두운 띠에 배치합니다 — 열기, 교체, 툴팁은 그대로입니다.",
    ["Modern replaces Blizzard's buttons with a flat dark icon strip in the VuloUI look. Clicks and tooltips stay identical."] = "모던은 Blizzard 버튼을 VuloUI 스타일의 평면 어두운 아이콘 띠로 대체합니다. 클릭과 툴팁은 그대로입니다.",
    ["Classic (Blizzard buttons)"] = "클래식 (Blizzard 버튼)",
    ["Modern (flat icon strip)"] = "모던 (평면 아이콘 띠)",
    ["Hides the row of menu buttons (character, spellbook, …)."] = "메뉴 버튼 줄(캐릭터 정보, 주문서 등)을 숨깁니다.",
    ["Hide the bag bar"] = "가방 바 숨기기",
    ["Hides the backpack and bag slots."] = "배낭과 가방 칸을 숨깁니다.",
    ["|cff9b6cffThe micro menu, bag bar, FPS/latency bar and the XP bar below are movable in Edit Mode (/vedit) like the action bars.|r"] = "|cff9b6cff마이크로 메뉴, 가방 바, FPS/지연 시간 바, 아래의 경험치 바는 행동 단축바처럼 편집 모드(/vedit)에서 옮길 수 있습니다.|r",
    ["Micro menu"] = "마이크로 메뉴",
    ["Bag bar"] = "가방 바",
    ["FPS / latency bar"] = "FPS / 지연 시간 바",
    ["XP bar"] = "경험치 바",
    ["Show a custom XP bar"] = "사용자 지정 경험치 바 표시",
    ["Colour"] = "색",
    ["Bar opacity"] = "바 불투명도",
    ["Show empty buttons"] = "빈 버튼 표시",
    ["Off hides empty slots; they reappear automatically while you drag an ability."] = "끄면 빈 칸이 숨겨지며, 능력을 끌어다 놓는 동안에는 자동으로 다시 나타납니다.",
    ["Click through"] = "클릭 통과",
    ["The bar ignores the mouse entirely — clicks go through it. Keybinds still work."] = "바가 마우스를 완전히 무시하여 클릭이 그대로 통과합니다. 단축키는 계속 작동합니다.",
    ["Keybind text size"] = "단축키 글자 크기",
    ["Macro text size"] = "매크로 글자 크기",
    ["Count text size"] = "개수 글자 크기",
    ["Cooldown text size"] = "대기시간 글자 크기",
    ["0 = default size."] = "0 = 기본 크기.",
    ["0 = default size. Requires cooldown numbers to be enabled in the game options."] = "0 = 기본 크기. 게임 옵션에서 재사용 대기시간 숫자 표시가 켜져 있어야 합니다.",
    ["Cooldown & look"] = "재사용 대기시간 및 모양",
    ["|cffff5555Quick keybind mode is not available on this client.|r"] = "|cffff5555빠른 단축키 지정 모드는 이 클라이언트에서 사용할 수 없습니다.|r",
    ["Modifier paging"] = "조합키 페이지 전환",
    ["Click: open these settings"] = "클릭: 이 설정 열기",
    ["Crowd Control"] = "군중 제어",
    ["Addon font (default)"] = "애드온 글꼴 (기본값)",
    ["The typeface for every text on the plates (name, health, cast, auras)."] = "이름표의 모든 글자(이름, 생명력, 시전, 오라)에 사용할 글꼴입니다.",
    ["Health text size"] = "생명력 글자 크기",
    ["0 = uses the general text size."] = "0 = 일반 글자 크기 사용.",
    ["Cast text size"] = "시전 글자 크기",
    ["Cast background colour"] = "시전 배경색",
    ["Cast background opacity"] = "시전 배경 불투명도",
    ["0 = uses the global background opacity."] = "0 = 전체 배경 불투명도 사용.",
    ["Icon scale"] = "아이콘 크기 비율",
    ["Icon on the right"] = "아이콘 오른쪽 배치",
    ["Icon offset X"] = "아이콘 X 오프셋",
    ["Icon offset Y"] = "아이콘 Y 오프셋",
    ["Shield on uninterruptible casts"] = "방해 불가 시전에 방패 표시",
    ["Tick where your interrupt becomes ready"] = "시전 방해 준비 지점 눈금",
    ["Marks the spot on the enemy cast bar where YOUR interrupt comes off cooldown — everything after the tick is kickable."] = "적 시전 바에서 자신의 시전 방해 기술이 대기시간을 마치는 지점을 표시합니다 — 눈금 이후는 모두 끊을 수 있습니다.",
    ["Tick colour"] = "눈금 색",
