    ["Flash colour"] = "섬광 색",
    ["Cast text colour"] = "시전 글자 색",
    ["Timer side"] = "시간 표시 위치",
    ["Timer colour"] = "시간 표시 색",
    ["Hide name while casting"] = "시전 중 이름 숨기기",
    ["Cast timer size"] = "시전 시간 글자 크기",
    ["NPC title size"] = "NPC 직함 크기",
    ["0 = slightly smaller than the name."] = "0 = 이름보다 조금 작게.",
    ["CC icon width"] = "군중 제어 아이콘 너비",
    ["CC icon height"] = "군중 제어 아이콘 높이",
    ["0 = square (uses the icon size)."] = "0 = 정사각형 (아이콘 크기 사용).",
    ["Cast bar width"] = "시전 바 너비",
    ["0 = match the health bar width."] = "0 = 생명력 바 너비에 맞춤.",
    ["Name offset X"] = "이름 X 오프셋",
    ["Name offset Y"] = "이름 Y 오프셋",
    ["Health text offset X"] = "생명력 글자 X 오프셋",
    ["Health text offset Y"] = "생명력 글자 Y 오프셋",
    ["Aura offset X"] = "오라 X 오프셋",
