    ["Target plate scale"] = "대상 이름표 크기 비율",
    ["Your target's plate is drawn this much larger (100 = off)."] = "현재 대상의 이름표를 이만큼 크게 표시합니다 (100 = 끔).",
    ["Behaviour"] = "동작",
    ["|cffaaaaaaThese are the game's own nameplate settings, changed live (not part of the profile). Not changeable in combat.|r"] = "|cffaaaaaa게임 자체의 이름표 설정이며 즉시 적용됩니다 (프로필에 저장되지 않음). 전투 중에는 변경할 수 없습니다.|r",
    ["Plate motion"] = "이름표 배치 방식",
