    ["Line-of-sight opacity"] = "시야 밖 불투명도",
    ["Opacity of plates whose unit is out of your line of sight."] = "자신의 시야에서 벗어난 대상의 이름표 불투명도입니다.",
    ["Plate view distance"] = "이름표 표시 거리",
    ["|cffaaaaaaWhile the key is held (or your target matches), the main bar shows the chosen bar's abilities instead. Fully secure — works in combat.|r"] = "|cffaaaaaa키를 누르고 있는 동안(또는 대상이 조건에 맞을 때) 주 단축바에 선택한 단축바의 능력이 대신 표시됩니다. 완전히 안전하며 전투 중에도 작동합니다.|r",
    ["Shift held"] = "Shift 누름",
