    ["No contacts yet"] = "아직 연락처가 없습니다",
    ["No groups forming right now."] = "지금은 그룹을 모집하는 사람이 없습니다.",
    ["One-key reel (soft-target interact)"] = "한 키로 끌어올리기 (소프트 타겟 상호작용)",
    ["Open All"] = "모두 열기",
    ["Press the key for fishing  (ESC to cancel)"] = "낚시에 사용할 키를 누르세요  (ESC는 취소)",
    ["Print a looted summary"] = "획득 요약 출력",
