    ["Scan guild chat"] = "길드 대화 검색",
    ["Scan say / yell"] = "말하기와 외치기 검색",
    ["Scan world / trade / LFG channels"] = "지역, 거래, 파티 찾기 채널 검색",
    ["Set fishing key"] = "낚시 키 설정",
    ["Slot %d"] = "칸 %d",
    ["Speed (seconds between actions)"] = "속도(동작 사이 초)",
    ["Take item attachments"] = "첨부된 아이템 받기",
    ["Take money"] = "돈 받기",
    ["While the bobber is out, maxes effect + master volume and dims music/ambience so the splash is easy to hear. Restored when you reel in."] = "찌기가 물에 있는 동안 효과음과 전체 음량을 최대로 올리고 음악과 환경음을 낮춰 물소리를 잘 들리게 합니다. 끌어올리면 복원됩니다.",
    ["While the bobber is out, the same key interacts with it to reel in. Needs soft-target interaction, which is enabled only while fishing and restored afterwards."] = "찌기가 물에 있는 동안에는 같은 키로 끌어올립니다. 소프트 타겟 상호작용이 필요하며, 낚시 중에만 켜지고 끝나면 복원됩니다.",
    ["Whisper"] = "귀속말",
    ["Who"] = "누구",
    ["Your characters"] = "내 캐릭터",
    ["now"] = "방금",
    ["|cffaaaaaaAdds an 'Open All' button to the mailbox. It takes every attachment and coin, skipping CoD and GM mail. Shift-click the button to ignore the filters and take everything.|r"] = "|cffaaaaaa우편함에 모두 열기 단추를 추가합니다. 착불 우편과 GM 우편을 건너뛰고 모든 첨부물과 돈을 받습니다. 단추를 Shift+클릭하면 필터를 무시하고 전부 받습니다.|r",
    ["|cffaaaaaaItems or macros also used by the key while fishing — only when ready (off cooldown, buff missing, conditions met), then it goes back to casting. Type an item name or ID, shift-click an item into the box, or paste a /macro.|r"] = "|cffaaaaaa낚시 중에 키가 함께 사용하는 아이템이나 매크로입니다 — 준비된 경우에만(재사용 대기 없음, 효과 없음, 조건 충족), 그 뒤에는 다시 던집니다. 아이템 이름이나 ID를 입력하거나, Shift+클릭으로 아이템을 넣거나, /매크로를 붙여넣으세요.|r",
    ["|cffaaaaaaOne key does it all: cast, reel in, and apply a lure — then auto-loots. Set a key below, face some water, and press it.|r"] = "|cffaaaaaa키 하나로 모두 해결합니다: 던지기, 끌어올리기, 미띄 바르기 — 그리고 자동으로 획득합니다. 아래에서 키를 정하고 물을 바라본 뒤 누르세요.|r",
    ["|cffff5555Arena submodule OnDisable error:|r %s"] = "|cffff5555투기장 하위 모듈 OnDisable 오류:|r %s",
    -- Patch notes, module descriptions, anchors, embedded engine (sweep 2026-07)
    ["Languages"] = "언어",
    ["Reminders (new module)"] = "알림 (새 모듈)",
    ["Arena"] = "투기장",
    ["Totems"] = "토템",
    ["Fixes"] = "수정 사항",
    ["Resource Bar"] = "자원 바",
    ["Settings Window"] = "설정 창",
    ["Character Window"] = "캐릭터 창",
    ["Nameplates (German: Namensplaketten)"] = "이름표 (독일어: Namensplaketten)",
    ["German client"] = "독일어 클라이언트",
    ["Performance"] = "성능",
    ["Equipment Sets"] = "장비 세트",
    ["Spanish, French, Italian, Portuguese, Russian and Korean. All six are complete — every one of the 2244 texts is translated, nothing falls back to English. Spanish also serves Latin American clients. Choose your language under General, or leave it on Auto."] = "스페인어, 프랑스어, 이탈리아어, 포르투갈어, 러시아어, 한국어. 여섯 언어 모두 완성되어 2244개의 텍스트가 전부 번역되었으며, 영어로 대체되는 부분이 없습니다. 스페인어는 중남미 클라이언트에도 적용됩니다. 일반 설정에서 언어를 선택하거나 ‘자동’으로 두십시오.",
    ["Shows what you are missing before a pull: weapon oils and stones, blessings, food and flask buffs, the aura or stance you forgot to set. Click a reminder to cast or use it. Off by default, found under Quality of Life."] = "전투 전에 빠진 것을 보여줍니다: 무기 연마제와 숫돌, 축복, 음식과 영약 강화 효과, 잊어버린 오라나 태세까지. 알림을 클릭하면 바로 시전하거나 사용합니다. 기본적으로 꺼져 있으며 편의 기능에서 찾을 수 있습니다.",
    ["A spark at the bar's fill point, rounded corners, aura rows you can assign freely, and your own damage-over-time effects on a row of their own."] = "바가 채워지는 지점의 불꽃, 둥근 모서리, 자유롭게 배정할 수 있는 오라 줄, 그리고 자신의 지속 피해 효과를 위한 별도의 줄.",
    ["Aura borders take the colour of their spell school, and an aura flashes shortly before it runs out."] = "오라 테두리가 해당 주문 계열의 색을 따르며, 오라가 끝나기 직전에 깜빡입니다.",
    ["Level and elite text, plus overall scale and vertical offset per plate."] = "레벨과 정예 문자, 그리고 이름표별 전체 배율과 세로 오프셋.",
    ["A window can take its width or height from another window and keep it."] = "창이 다른 창의 너비나 높이를 가져와 유지할 수 있습니다.",
    ["Save button. While dragging, hold Shift to lock one axis."] = "저장 버튼. 드래그하는 동안 Shift를 누르고 있으면 한 축이 고정됩니다.",
    ["Trinket and racial cooldowns, Shadow Sight timer, a ring on the class icon for the most important aura, and range checking."] = "장신구와 종족 기술 재사용 대기시간, 그림자 시야 타이머, 직업 아이콘에 가장 중요한 오라를 표시하는 고리, 사거리 확인.",
    ["Totem icons grey out once you leave the totem's range and regain their colour when you come back."] = "토템 아이콘이 토템의 범위를 벗어나면 회색으로 바뀌고 돌아오면 다시 색을 되찾습니다.",
    ["The character sheet and spellbook open in combat again. The action bars no longer set a protected field from our own code, which was the real cause."] = "캐릭터 정보창과 주문서가 전투 중에도 다시 열립니다. 행동 단축바가 더 이상 자체 코드에서 보호된 필드를 설정하지 않으며, 이것이 진짜 원인이었습니다.",
    ["The melee swing timer is off by default and only loads for melee classes and specialisations."] = "근접 공격 타이머는 기본적으로 꺼져 있으며 근접 직업과 전문화에서만 불러와집니다.",
    ["Sliders got a proper look: soft edges, an inner shadow and a smoother hover."] = "슬라이더가 제대로 된 모양을 갖췄습니다: 부드러운 가장자리, 안쪽 그림자, 더 매끄러운 마우스 오버.",
    ["Own icons for the three collection pages, and class icons on the class tabs."] = "세 수집 페이지의 자체 아이콘과 직업 탭의 직업 아이콘.",
    ["Anchor a window to another one's edge (left/right/top/bottom) — the gap is kept edge-to-edge, so it survives either window being resized."] = "창을 다른 창의 가장자리(왼쪽/오른쪽/위/아래)에 고정합니다 — 간격이 가장자리 기준으로 유지되므로 어느 창의 크기가 바뀌어도 그대로 남습니다.",
    ["Click-to-anchor: press \"Anchor to window...\" in a window's panel, then click the target window. Loop and self-anchor are blocked."] = "클릭 고정: 창 패널에서 ‘창에 고정...’을 누른 다음 대상 창을 클릭하십시오. 순환 고정과 자기 자신에 대한 고정은 차단됩니다.",
    ["While dragging, alignment lines now also show the pixel distance to the window you line up with."] = "드래그하는 동안 정렬선이 이제 기준으로 맞추는 창까지의 픽셀 거리도 표시합니다.",
    ["Discard button — snapshots the layout when you open Edit Mode and restores it (positions, scale, anchors and links) if you discard."] = "되돌리기 버튼 — 편집 모드를 열 때 배치를 기록해 두었다가 되돌리면 위치, 배율, 고정, 연결을 복원합니다.",
    ["The drag area now covers the whole dark chat panel down to the edit box, not just the narrow message strip."] = "드래그 영역이 이제 좁은 메시지 띠만이 아니라 입력창까지 어두운 대화 패널 전체를 덮습니다.",
    ["Fixed right-click on the chat window not opening its settings panel in Edit Mode."] = "편집 모드에서 대화창을 오른쪽 클릭해도 설정 패널이 열리지 않던 문제를 수정했습니다.",
    ["Interrupt help on the cast bar: own colours while your interrupt is on cooldown or ready, a tick marking where it comes back mid-cast, a shield on uninterruptible casts and an interrupt flash that can show who landed the kick."] = "시전 바의 시전 방해 도우미: 시전 방해 기술이 재사용 대기 중이거나 준비되었을 때의 자체 색상, 시전 도중 언제 다시 준비되는지 표시하는 눈금, 방해할 수 없는 시전의 방패 표시, 그리고 누가 끊었는지 보여줄 수 있는 시전 방해 섬광.",
    ["Cast bar suite: icon side and scale, remaining time, own background, channel colour, a warning colour when the cast aims at YOU — and on your target the cast bar lines up flush with the health bar including its border."] = "시전 바 종합 기능: 아이콘 위치와 배율, 남은 시간, 자체 배경, 지속 시전 색상, 시전 대상이 바로 나일 때의 경고 색상 — 그리고 대상의 시전 바는 테두리를 포함해 생명력 바와 정확히 맞춰 정렬됩니다.",
    ["Execute line, target and mouseover effects, crowd control section, combo point shapes and placement, per-element position, size and text-size controls plus a font picker."] = "마무리 일격 기준선, 대상 및 마우스 오버 효과, 군중 제어 구역, 연계 점수 모양과 배치, 요소별 위치·크기·글자 크기 조절과 글꼴 선택.",
    ["The options page carries a clickable live preview that stays pinned while you scroll — click any element to jump to its settings."] = "설정 페이지에 스크롤해도 고정된 채 남는 클릭 가능한 실시간 미리보기가 있습니다 — 아무 요소나 클릭하면 해당 설정으로 이동합니다.",
    ["Smooth health movement with a damage trail, value plus percent text layouts with short numbers, and a decimal toggle for aura timers."] = "피해 잔상이 있는 부드러운 생명력 변화, 짧은 숫자 표기의 수치와 백분율 문자 배치, 오라 타이머의 소수점 표시 전환.",
    ["Per-bar visibility conditions (instances, mounted, target, group), modifier paging, quick keybind mode (/vkb), a sixth bar, growth directions, button text styling and cooldown look options."] = "단축바별 표시 조건(인스턴스, 탈것, 대상, 파티), 조합키 페이지 전환, 빠른 단축키 지정 모드(/vkb), 여섯 번째 단축바, 배치 방향, 버튼 문자 꾸미기, 재사용 대기시간 모양 설정.",
    ["Micro menu and bag bar modern style: flat dark strips with an own monochrome icon set, plus world map, friends list, group finder, shop and key ring buttons."] = "마이크로 메뉴와 가방 바의 모던 스타일: 자체 단색 아이콘 세트를 갖춘 평평한 어두운 띠, 그리고 세계 지도, 친구 목록, 파티 찾기, 상점, 열쇠 꾸러미 버튼.",
    ["The experience bar width now adjusts in single steps."] = "경험치 바 너비를 이제 1단위로 조절할 수 있습니다.",
    ["Visibility conditions, colour modes with gradient, background and border colours, smooth value changes, hash marks and threshold colouring."] = "표시 조건, 그라데이션이 있는 색상 방식, 배경 및 테두리 색상, 부드러운 수치 변화, 눈금 표시, 기준값 색상.",
    ["Character sheet stats panel no longer bleeds into other tabs; loadout sidebar aligns with the modern character sheet."] = "캐릭터 정보창의 능력치 패널이 더 이상 다른 탭으로 번지지 않으며, 장비 세트 사이드바가 모던 캐릭터 정보창에 맞춰 정렬됩니다.",
    ["Arena points calculator panel and button wear the addon look and dock beside the character sheet."] = "투기장 점수 계산기 패널과 버튼이 애드온 스타일을 입고 캐릭터 정보창 옆에 붙습니다.",
    ["The Escape menu now wears the dark addon look — flat buttons, accent title — and gains a VuloClassicUI button that opens the options window. Both have their own toggles under General."] = "Esc 메뉴가 이제 어두운 애드온 스타일을 입습니다 — 평면 버튼과 강조 제목 — 그리고 설정 창을 여는 VuloClassicUI 버튼이 추가됩니다. 두 가지 모두 일반 설정에 자체 스위치가 있습니다.",
    ["The add friend dialog is skinned to match: dark panel, accent headline, dark input field and flat buttons."] = "친구 추가 창이 같은 스타일로 꾸며집니다: 어두운 패널, 강조 제목, 어두운 입력창, 평면 버튼.",
    ["Guild roster column header hover and click no longer stick out past the flat header row."] = "길드 명단의 열 제목이 마우스 오버나 클릭 시 더 이상 평평한 머리글 줄 밖으로 튀어나오지 않습니다.",
    ["The combat log filter bar now shares the exact width and height of the chat tab row, flush with the panel edge."] = "전투 기록 필터 바가 이제 대화 탭 줄과 정확히 같은 너비와 높이로 패널 가장자리에 딱 맞습니다.",
    ["After an update, a pulsing dot on the \"Patch Notes\" entry points at the new notes until you open them once — account wide, per version."] = "업데이트 후에는 ‘패치 노트’ 항목의 맥동하는 점이 새 노트를 한 번 열어 볼 때까지 안내합니다 — 계정 전체에, 버전별로 적용됩니다.",
    ["With the Modern style, the equipment set sidebar now docks to the right of the stats panel at exactly the window's height, instead of overlapping it. Switching styles with the window open moves it immediately."] = "모던 스타일에서 장비 세트 사이드바가 이제 능력치 패널을 겹치는 대신 그 오른쪽에 창과 정확히 같은 높이로 붙습니다. 창이 열린 상태에서 스타일을 바꾸면 즉시 이동합니다.",
    ["Micro menu buttons that the game hides situationally are shown again, so the row no longer has a gap."] = "게임이 상황에 따라 숨기는 마이크로 메뉴 버튼을 다시 표시해 줄에 빈틈이 생기지 않습니다.",
    ["The default nameplate no longer shows through as a faint transparent bar under the custom plate — it is now hidden outright and kept hidden while the custom plate is active."] = "기본 이름표가 더 이상 사용자 지정 이름표 아래로 흐릿한 반투명 막대로 비치지 않습니다 — 이제 완전히 숨겨지고 사용자 지정 이름표가 활성화된 동안 숨겨진 상태로 유지됩니다.",
    ["All micro menu buttons open their windows again — the emptied default micro menu shell was invisibly swallowing clicks on the relocated buttons."] = "모든 마이크로 메뉴 버튼이 다시 해당 창을 엽니다 — 비워진 기본 마이크로 메뉴 틀이 옮겨진 버튼에 대한 클릭을 보이지 않게 삼키고 있었습니다.",
    ["Fixed a blocked-action error when the stance bar updated during combat; stance button visibility now only changes out of combat, while icon tint, cooldown and the active marker keep updating live."] = "전투 중 태세 단축바가 갱신될 때 발생하던 차단된 동작 오류를 수정했습니다. 태세 버튼의 표시 여부는 이제 전투 중이 아닐 때만 바뀌며, 아이콘 색조, 재사용 대기시간, 활성 표시는 계속 실시간으로 갱신됩니다.",
    ["An Action Bars module puts every action bar on its own movable frame — action bars 1 to 5, the stance bar and the pet bar — each placed and scaled in Edit Mode and configured on its own."] = "행동 단축바 모듈이 모든 행동 단축바를 각각 이동 가능한 프레임에 올립니다 — 행동 단축바 1~5, 태세 단축바, 소환수 단축바 — 각각 편집 모드에서 배치하고 배율을 조절하며 따로 설정합니다.",
    ["The main bar pages correctly with druid, rogue, warrior and priest forms, and your keybinds keep working on every bar, with the key shown on the buttons."] = "주 단축바가 드루이드, 도적, 전사, 사제의 형태에 따라 올바르게 페이지를 전환하고, 모든 단축바에서 단축키가 계속 작동하며 버튼에 해당 키가 표시됩니다.",
    ["Per bar: visibility (always, mouseover, in or out of combat), opacity, icon size, buttons per row, spacing, vertical layout, reverse order, and hiding the keybind or macro text — with adjustable text sizes for keybind, macro, count and cooldown numbers."] = "단축바별: 표시 여부(항상, 마우스 오버, 전투 중 또는 비전투), 투명도, 아이콘 크기, 줄당 버튼 수, 간격, 세로 배치, 역순, 단축키·매크로 문자 숨기기 — 단축키, 매크로, 개수, 재사용 대기시간 숫자의 글자 크기도 조절할 수 있습니다.",
    ["Empty slots can be hidden and reappear automatically while you drag an ability onto the bar, and a bar can be made click-through."] = "빈 칸을 숨길 수 있으며, 기술을 단축바로 끌어오는 동안 자동으로 다시 나타납니다. 단축바를 클릭이 통과되도록 만들 수도 있습니다.",
    ["Cooldown and look settings for all bars: cooldown sweep darkness, desaturating icons on cooldown, colouring icons while the target is out of range, and hiding button tooltips always or only in combat."] = "모든 단축바의 재사용 대기시간 및 모양 설정: 재사용 대기시간 그림자의 어두운 정도, 대기시간 중 아이콘 채도 낮추기, 대상이 사거리 밖일 때 아이콘 색 입히기, 버튼 툴팁을 항상 또는 전투 중에만 숨기기.",
    ["An own experience bar with adjustable width, height and colour, rested overlay and progress text — it replaces the default bar while enabled and hides at the level cap."] = "너비, 높이, 색상을 조절할 수 있는 자체 경험치 바로, 휴식 경험치 표시와 진행 문자가 있습니다 — 켜져 있는 동안 기본 바를 대체하고 최고 레벨에서는 숨겨집니다.",
    ["The micro menu, the bag bar and the performance bar sit on movable holders, and each of them can be hidden — as can the default experience bar."] = "마이크로 메뉴, 가방 바, 성능 바가 이동 가능한 받침대 위에 놓이며, 각각 숨길 수 있습니다 — 기본 경험치 바도 마찬가지입니다.",
    ["Off by default: the standard bars stay untouched until you enable the module, and disabling hands everything back (a reload fully restores the default bars)."] = "기본적으로 꺼져 있습니다: 모듈을 켜기 전까지 기본 단축바는 그대로 유지되며, 끄면 모든 것이 되돌아갑니다(/reload 하면 기본 단축바가 완전히 복원됩니다).",
    ["The dark button skin now also covers the new action-bar buttons."] = "어두운 버튼 스킨이 이제 새 행동 단축바 버튼에도 적용됩니다.",
    ["A custom Nameplates module draws its own health bar, cast bar, name and health text over enemy and NPC nameplates — fully configurable, with a live preview that updates as you change each option."] = "사용자 지정 이름표 모듈이 적과 NPC 이름표 위에 자체 생명력 막대, 시전 막대, 이름, 생명력 문자를 그립니다 — 모든 것을 설정할 수 있으며, 설정을 바꿀 때마다 실시간 미리보기가 갱신됩니다.",
    ["Health bar with your choice of texture, width, height, background, and a border drawn as thin lines or a texture, all in your own colours."] = "원하는 텍스처, 너비, 높이, 배경을 고를 수 있는 생명력 막대와 얇은 선 또는 텍스처로 그려지는 테두리, 모두 자신의 색상으로 지정할 수 있습니다.",
    ["Colouring by reaction (hostile, neutral, friendly, tapped) and by class for players, plus role-based threat colouring for tanks and damage dealers."] = "반응(적대, 중립, 우호, 선점)에 따른 색상과 플레이어의 직업별 색상, 그리고 탱커와 딜러를 위한 역할 기반 위협 수준 색상.",
    ["Target and focus highlight rings, and an optional fade for plates that are not your target."] = "대상 및 주시 대상 강조 고리와 대상이 아닌 이름표를 흐리게 하는 선택 기능.",
    ["Cast bar with spell icon, spell name, and a separate colour for casts that cannot be interrupted."] = "주문 아이콘과 주문 이름이 있는 시전 막대, 그리고 방해할 수 없는 시전을 위한 별도 색상.",
    ["Aura rows: your debuffs (or all of them), enemy buffs, and a separate prominent row for crowd control such as Polymorph, Fear and Sap. A glow marks enemy buffs you can steal or dispel."] = "오라 줄: 내 약화 효과(또는 전부), 적의 강화 효과, 그리고 변이·공포·기절시키기 같은 군중 제어를 위한 별도의 눈에 띄는 줄. 훔치거나 무효화할 수 있는 적의 강화 효과에는 광채가 표시됩니다.",
    ["Combo point pips on your target for Rogues and Druids in cat form."] = "도적과 표범 변신 드루이드를 위한 대상 이름표의 연계 점수 표시.",
    ["Raid target markers (skull, cross, and the rest) with adjustable size and position."] = "크기와 위치를 조절할 수 있는 공격대 대상 지정 표시(해골, 십자가 등).",
    ["Friendly plates can show name only, the full plate, or nothing — set separately for players and NPCs — and can show a friendly NPC's subtitle under its name."] = "우호적인 이름표는 이름만, 전체 이름표, 또는 아무것도 표시하지 않도록 플레이어와 NPC 각각 따로 설정할 수 있으며, 우호적인 NPC의 칭호를 이름 아래에 표시할 수 있습니다.",
    ["A single \"Dark Skin\" module now covers the dark action-button and WeakAuras skin plus the optional Dark Mode that darkens Blizzard's default frames — those used to be two separate modules. Your existing settings carry over."] = "이제 하나의 ‘다크 스킨’ 모듈이 어두운 행동 단축바 버튼과 WeakAuras 스킨, 그리고 Blizzard 기본 프레임을 어둡게 하는 선택형 어두운 모드를 모두 담당합니다 — 예전에는 두 개의 별도 모듈이었습니다. 기존 설정은 그대로 이어집니다.",
    ["The reskin modules (skins, character panel, chat, friends list, minimap) are now one tabbed entry, matching how the other groups are already organised."] = "리스킨 모듈(스킨, 캐릭터 패널, 대화, 친구 목록, 미니맵)이 이제 다른 그룹들처럼 탭이 있는 하나의 항목으로 묶였습니다.",
    ["Consolidated groups now list their modules as a vertical, icon-labelled column instead of a wrapping row of tabs — easier to scan when there are many."] = "통합된 그룹이 이제 모듈을 줄바꿈되는 탭 줄 대신 아이콘이 붙은 세로 목록으로 표시합니다 — 모듈이 많을 때 훑어보기 쉽습니다.",
    ["A \"Patch Notes\" page under Overview shows every version's changes right in the game."] = "개요 아래의 ‘패치 노트’ 페이지가 모든 버전의 변경 사항을 게임 안에서 바로 보여줍니다.",
    ["Cleaner tab names for a few tools: Training, Leisten-Profile, Apexis-Minispiel, Gruppensuche."] = "몇몇 도구의 탭 이름이 깔끔해졌습니다: Training, Leisten-Profile, Apexis-Minispiel, Gruppensuche.",
    ["The target-frame extras and the elite player-frame border are now a single module called \"Player & Target Frame\". Your existing settings and per-character on and off state carry over automatically."] = "대상 프레임 확장 기능과 정예 플레이어 프레임 테두리가 이제 ‘플레이어 및 대상 프레임’이라는 하나의 모듈이 되었습니다. 기존 설정과 캐릭터별 켜짐/꺼짐 상태는 자동으로 이어집니다.",
    ["Settings now default to a separate profile per class, so what you set on one class no longer changes another. Your current settings are copied into each class profile, and you can still share or pin profiles as before."] = "설정이 이제 기본적으로 직업별 프로필로 나뉘어, 한 직업에서 바꾼 설정이 다른 직업에 영향을 주지 않습니다. 현재 설정은 각 직업 프로필로 복사되며, 이전처럼 프로필을 공유하거나 고정할 수 있습니다.",
    ["Scrolling messages that fire at the same moment now stack with a gap instead of overlapping."] = "같은 순간에 발생한 스크롤 메시지가 이제 겹치는 대신 간격을 두고 쌓입니다.",
    ["Fixed an error that could appear when combat started while your line was cast. The sound and interact settings now restore after combat ends instead."] = "낚싯줄을 드리운 동안 전투가 시작되면 나타날 수 있던 오류를 수정했습니다. 소리 및 상호작용 설정은 이제 전투가 끝난 뒤에 복원됩니다.",
    ["Lighter cast bar time text, cooldown bars that batch their refreshes during busy moments, a cheaper combat-log check for the cooldown pulse, and a lighter minimap hover check."] = "더 가벼운 시전 바 시간 문자, 바쁜 순간에 갱신을 모아서 처리하는 재사용 대기시간 바, 더 가벼워진 재사용 대기시간 알림의 전투 기록 확인, 더 가벼운 미니맵 마우스 오버 확인.",
    ["The spell stats are ordered spell power, healing, spell crit, then spell hit."] = "주문 능력치가 주문력, 치유량, 주문 치명타, 주문 적중 순으로 정렬됩니다.",
    ["The Fishing and Mail tabs now read \"Angeln\" and \"Post\"."] = "낚시와 우편 탭이 이제 ‘Angeln’과 ‘Post’로 표시됩니다.",
    ["A style dropdown at the top of the module options. Classic+ keeps the current look; Modern is a new dark, single-window style."] = "모듈 설정 맨 위의 스타일 드롭다운. Classic+ 는 현재 모양을 유지하고, Modern은 새로운 어두운 단일 창 스타일입니다.",
    ["Modern reskins the whole character window dark with an accent border and a stats panel on the right: a big equipped item level, then collapsible categories — attributes, melee, spell, defense and resistances — with per-stat hover breakdowns and mouse-wheel scrolling."] = "Modern은 캐릭터 창 전체를 강조 테두리가 있는 어두운 스타일로 바꾸고 오른쪽에 능력치 패널을 둡니다: 큰 착용 아이템 레벨, 그 아래 접을 수 있는 분류 — 능력치, 근접, 주문, 방어, 저항력 — 와 능력치별 마우스 오버 세부 정보, 마우스 휠 스크롤.",
    ["Under Modern the built-in stats, resistance icons and the model rotate arrows are hidden, and the reputation, skills and player-versus-player sub-tabs plus the bottom tabs are skinned to match. Everything switches back to Classic+ live, and adapts per client (rating stats only where they exist)."] = "Modern에서는 내장 능력치, 저항 아이콘, 모델 회전 화살표가 숨겨지고, 평판·기술·플레이어 대 플레이어 하위 탭과 아래쪽 탭이 같은 스타일로 꾸며집니다. 모든 것이 실시간으로 Classic+ 로 되돌아가며, 클라이언트에 맞춰 조정됩니다(평점 능력치는 존재하는 곳에서만).",
    ["Dark skin for a world-map options window, with its own on and off switch in the Addon Skins options."] = "세계 지도 설정 창의 어두운 스킨으로, 애드온 스킨 설정에 자체 스위치가 있습니다.",
    ["The clock now sits on the same line as the date and zone instead of floating higher."] = "시계가 이제 더 높이 떠 있는 대신 날짜 및 지역과 같은 줄에 놓입니다.",
    ["Dark skin for a loot-distribution addon — its award and roll windows, its settings and overview windows, and the two always-visible roll and bid bars get the house panel, accent border and flat close button."] = "전리품 분배 애드온의 어두운 스킨 — 수여 및 주사위 창, 설정 및 개요 창, 항상 표시되는 주사위·입찰 바 두 개가 애드온 고유의 패널과 강조 테두리, 평면 닫기 버튼을 갖춥니다.",
    ["Dark skin for an attunement tracker — the main window and its buttons match the dark look; the colored status rows stay as they are so the state colors remain readable."] = "입장 조건 추적기의 어두운 스킨 — 메인 창과 버튼이 어두운 스타일에 맞춰지며, 색이 있는 상태 줄은 상태 색상을 읽을 수 있도록 그대로 둡니다.",
    ["Both are separate on and off switches in the Addon Skins options, next to the others."] = "둘 다 애드온 스킨 설정에서 다른 스킨들과 나란히 별도의 스위치로 켜고 끌 수 있습니다.",
    ["NEW:"] = "신규:",
    ["A single unified inventory window: all bags in one grid, with quality borders, counts, cooldowns, money and free slots. Movable and scalable."] = "하나로 통합된 소지품 창: 모든 가방을 한 격자에 담고, 등급 테두리, 개수, 재사용 대기시간, 소지금, 빈 칸을 표시합니다. 이동과 크기 조절이 가능합니다.",
    ["Fixes stuck inspect bugs (no player inspect possible after a faulty close/timeout). Auto-reset after a timeout, auto-retry when the window stays empty, cleanup when InspectFrame closes + /inspectreset slash command."] = "멈춘 살펴보기 버그를 수정합니다(잘못된 닫힘/시간 초과 후 플레이어 살펴보기 불가). 시간 초과 후 자동 초기화, 창이 비어 있으면 자동 재시도, InspectFrame이 닫힐 때 정리 + /inspectreset 명령어를 제공합니다.",
    ["A modern minimap: round with a clean dark ring and accent line, zone text and clock in a slim panel, mouse-wheel zoom, movable and scalable. Optionally hides other addons' buttons until mouseover."] = "모던 미니맵: 깔끔한 어두운 고리와 강조 선이 있는 원형, 얇은 패널의 지역 문자와 시계, 마우스 휠 확대/축소, 이동 및 크기 조절 가능. 다른 애드온의 버튼을 마우스를 올릴 때까지 숨길 수도 있습니다.",
    ["Custom enemy & NPC nameplates with a live preview: health bar, cast bar, name and health text, reaction / class colours, target highlight and threat colouring."] = "적과 NPC 이름표를 실시간 미리보기와 함께 원하는 대로 설정합니다: 생명력 막대, 시전 막대, 이름과 생명력 문자, 반응/직업 색상, 대상 강조, 위협 수준 색상.",
    ["Hover an equipment slot for a compact flyout of compatible bag items, or modifier-click for a larger picker. Click an item to equip it."] = "장비 칸에 마우스를 올리면 호환되는 가방 아이템이 간단한 띠로 펼쳐지고, 조합키와 함께 클릭하면 더 큰 선택기가 열립니다. 아이템을 누르면 착용합니다.",
    ["Move every VuloUI window and Blizzard's default frames in one editor."] = "모든 VuloUI 창과 Blizzard 기본 프레임을 하나의 편집기에서 옮깁니다.",
    ["One-key fishing: one key casts, reels and applies a lure, and auto-loots your catch."] = "원버튼 낚시: 키 하나로 던지고, 감고, 미끼를 바르고, 잡은 것을 자동으로 획득합니다.",
    ["Adds an 'Open All' button to your mailbox that collects every attachment and coin in one click."] = "우편함에 첨부물과 동전을 한 번의 클릭으로 모두 수령하는 ‘모두 열기’ 버튼을 추가합니다.",
    ["Top"] = "위쪽",
    ["Bottom"] = "아래쪽",
    ["Top-Left"] = "왼쪽 위",
    ["Top-Right"] = "오른쪽 위",
    ["Bottom-Left"] = "왼쪽 아래",
    ["Bottom-Right"] = "오른쪽 아래",
    ["Trinkets: Cleared all ignored/hidden trinkets."] = "Trinkets: 무시/숨김 처리된 장신구를 모두 지웠습니다.",
    ["Trinkets usage:"] = "Trinkets 사용법:",
    ["/trinket or /Trinkets : toggle the window"] = "/trinket or /Trinkets : 창 표시 전환",
    ["/trinket reset : reset all settings"] = "/trinket reset : 모든 설정 초기화",
    ["/trinket clear : clear all ignored/hidden trinkets"] = "/trinket clear : 무시/숨김 처리된 장신구 모두 지우기",
    ["/trinket opt : summon options window"] = "/trinket opt : 설정 창 열기",
    ["/trinket lock|unlock : toggles window lock"] = "/trinket lock|unlock : 창 잠금 전환",
    ["/trinket scale main|menu (number) : sets an exact scale"] = "/trinket scale main|menu (number) : 정확한 배율 지정",
    ["/trinket load top|bottom profilename : loads a profile to top or bottom trinket"] = "/trinket load top|bottom profilename : 프로필을 위쪽 또는 아래쪽 장신구에 불러오기",
    ["Are you sure you want to reset Trinkets to default state and reload the UI?"] = "Trinkets를 기본 상태로 초기화하고 UI를 다시 불러오시겠습니까?",
    ["Queued: %s"] = "대기열: %s",
    ["Priority"] = "우선순위",
    ["Pause Queue"] = "대기열 일시 정지",
    ["Parameter must be 0 for top trinket or 1 for bottom."] = "매개변수는 위쪽 장신구는 0, 아래쪽 장신구는 1이어야 합니다.",
    ["No profiles saved yet."] = "아직 저장된 프로필이 없습니다.",
    -- Patch notes 1.37.1
    ["Visuals"] = "외형",
    ["The language option under General now actually applies. It silently never took effect — the addon read the client language before your saved choice was loaded. After a /reload every label, dropdown and popup follows your choice."] = "일반 설정의 언어 선택이 이제 실제로 적용됩니다. 저장된 선택이 불러와지기 전에 애드온이 클라이언트 언어를 읽어 버려서 그동안 조용히 무시되고 있었습니다. /reload 후 모든 라벨, 드롭다운, 팝업이 선택한 언어를 따릅니다.",
    ["The Patch Notes page is translated into all languages, including every past version."] = "패치 노트 페이지가 모든 언어로 번역되었으며, 지난 모든 버전도 포함됩니다.",
    ["The trinket panel, its queue window and the /trinket help are translated too."] = "장신구 패널과 대기열 창, /trinket 도움말도 번역되었습니다.",
    ["German: sixteen duplicated translations cleaned up, five of which contradicted each other."] = "독일어: 중복된 번역 열여섯 개를 정리했고, 그중 다섯 개는 서로 모순이었습니다.",
    ["Third pass over the busiest code paths: nameplate auras scan once instead of four times, combat-log and aura events skip a safety wrapper, timer texts only redraw when the shown number changes, and several background listeners now sleep while their feature is off or hidden. Less stutter in raids and arenas."] = "가장 바쁜 코드 경로에 대한 세 번째 정리: 이름표 오라를 네 번 대신 한 번만 검사하고, 전투 기록과 오라 이벤트는 안전 래퍼를 생략하며, 타이머 텍스트는 표시되는 숫자가 바뀔 때만 다시 그려지고, 여러 백그라운드 리스너는 해당 기능이 꺼져 있거나 숨겨져 있는 동안 잠듭니다. 공격대와 투기장에서 끊김이 줄어듭니다.",
    ["The frames can be turned off again without leftovers."] = "창을 다시 잔여물 없이 끌 수 있습니다.",
    ["An interrupted enemy cast now shows INTERRUPTED briefly — it used to vanish the same instant."] = "차단된 적의 주문이 이제 잠시 차단됨으로 표시됩니다. 이전에는 그 즉시 사라졌습니다.",
    ["Diminishing-returns icons clean up correctly after toggling the tracker mid-arena."] = "점감 아이콘이 투기장 도중 추적기를 껐다 켜도 올바르게 정리됩니다.",
    ["Seven working settings that were invisible in the options are shown again, and several switches that did nothing are wired up."] = "옵션에서 보이지 않던 일곱 개의 작동하는 설정이 다시 표시되고, 아무 동작도 하지 않던 여러 스위치가 연결되었습니다.",
    ["Modules tidy up after themselves when disabled: totem range dimming, the inspect window, queue timer, quest log and font bars no longer leave stale pieces behind."] = "모듈이 꺼질 때 스스로 정리합니다: 토템 사거리 어둡게 표시, 살펴보기 창, 대기열 타이머, 퀘스트 기록, 글꼴 막대가 더 이상 잔여물을 남기지 않습니다.",
    ["Three modules got their own sidebar icons instead of the placeholder, and Reminders got a nicer bell."] = "세 모듈이 자리 표시자 대신 자체 사이드바 아이콘을 받았고, 알림은 더 예쁜 종을 받았습니다.",
    -- Bags: quest starter marker
    ["Quest starter marker (!)"] = "퀘스트 시작 표시 (!)",
    ["Overlays a yellow exclamation mark on items that start a quest you have not accepted yet."] = "아직 수락하지 않은 퀘스트를 시작하는 아이템 위에 노란 느낌표를 표시합니다.",
    -- Options page build failure
    ["|cffff5555Options page '%s' failed to build:|r %s"] = "|cffff5555'%s' 설정 페이지를 구성하지 못했습니다:|r %s",
    ["|cffff5555This page could not be built. /reload, and report it if it persists.|r"] = "|cffff5555이 페이지를 구성하지 못했습니다. /reload 후에도 계속되면 알려 주세요.|r",
    ["|cff888888%.2f ms/frame |cff666666(%.1f%% of ours, peak %.1f ms)|r|r"] = "|cff888888%.2f ms/프레임 |cff666666(우리 %.1f%%, 최고 %.1f ms)|r|r",
    ["|cffaaaaaaThe header shows how much frame time VuloClassicUI costs. Your client measures this on its own, all the time — no setting and no reload needed.|r"] = "|cffaaaaaa헤더에 VuloClassicUI가 프레임 시간을 얼마나 쓰는지 표시됩니다. 클라이언트가 스스로 항상 측정하므로 설정도 다시 불러오기도 필요 없습니다.|r",
    -- Patch notes 1.37.2
    ["Classic Era, Hardcore and Season of Discovery"] = "클래식 에라, 하드코어, 발견의 계절",
    ["Under the hood"] = "내부 변경",
    ["The addon loads again without ticking \"Load out of date AddOns\". Blizzard's July interface update moved these realms to a new version number."] = "'철 지난 애드온 불러오기'를 체크하지 않아도 애드온이 다시 불러와집니다. 7월 블리자드 인터페이스 업데이트로 해당 서버들의 버전 번호가 바뀌었습니다.",
    ["Fixed a crash that switched the whole Class Trainer page off on Season of Discovery: one ability the realm does not know took the entire module down with it."] = "발견의 계절에서 직업 교관 페이지 전체를 꺼뜨리던 오류를 고쳤습니다. 서버가 모르는 주문 하나가 모듈 전체를 끌어내렸습니다.",
    ["The elite border on your player frame sits correctly again. It was placed against the old frame layout, which that same update replaced."] = "플레이어 창의 정예 테두리가 다시 제자리에 놓입니다. 같은 업데이트가 교체한 예전 창 배치에 맞춰져 있었습니다.",
    ["Fixed a rare error storm at the end of a fight. Cleanup work in nineteen files could be skipped and the chat filled with error lines."] = "전투가 끝날 때 드물게 쏟아지던 오류를 고쳤습니다. 열아홉 개 파일의 정리 작업이 건너뛰어지고 대화창이 오류 줄로 가득 찰 수 있었습니다.",
    ["Combat log features (swing timer, cooldown pulse, combat text, arena tracker, nameplates, mana display) no longer depend on a setting a player can switch off."] = "전투 기록 기반 기능(공격 타이머, 재사용 대기 표시, 전투 문자, 투기장 추적, 이름표, 마나 표시)이 더 이상 끌 수 있는 설정에 의존하지 않습니다.",
    ["An interrupted enemy cast now really shows INTERRUPTED for a moment."] = "차단된 적의 주문이 이제 실제로 잠시 차단 표시를 보여 줍니다.",
    ["Items that start a quest you have not accepted yet are marked with a yellow exclamation mark, in bags, bank and keyring."] = "아직 수락하지 않은 퀘스트를 시작하는 아이템에 노란 느낌표가 표시됩니다. 가방, 은행, 열쇠 꾸러미에서 모두 적용됩니다.",
    ["Seven of the eight shipped translations no longer build their lookup table at all. Only the language you actually read is assembled, which frees about a megabyte on every login."] = "함께 제공되는 여덟 개 번역 중 일곱 개는 이제 조회 표를 아예 만들지 않습니다. 실제로 읽는 언어만 구성되어 접속할 때마다 약 1메가바이트를 아낍니다.",
    ["Edit Mode: three background drivers no longer run permanently, dragging a window allocates far less, and finding a window is a direct lookup instead of a search."] = "편집 모드: 세 개의 배경 구동기가 더 이상 상시 실행되지 않고, 창을 끌 때 생기는 찌꺼기가 크게 줄었으며, 창 찾기가 검색 대신 직접 조회가 되었습니다.",
    ["Disabling a module now detaches it completely — several used to leave listeners running for the rest of the session."] = "모듈을 끄면 이제 완전히 분리됩니다. 일부는 남은 세션 내내 수신기를 계속 돌리고 있었습니다.",
    ["The performance readout in the header uses your client's own always-on measurement, so it needs no setting and no reload."] = "헤더의 성능 표시는 클라이언트가 항상 수행하는 측정을 사용하므로 설정도 다시 불러오기도 필요 없습니다.",
    -- Patch notes 1.37.2
    -- Built-in profiler
    ["Nothing measured yet. Play for a bit, then read it again."] = "아직 측정된 것이 없습니다. 잠시 플레이한 뒤 다시 확인하세요.",
    ["Measured over %.1f s -- %.1f ms total, %.2f%% of it ours:"] = "%.1f초 동안 측정: 전체 %.1f ms, 그중 %.2f%%가 우리 몫입니다:",
    ["Measurement off."] = "측정을 껐습니다.",
    ["Measurement reset."] = "측정을 초기화했습니다.",
    ["Measurement on. Play, then type /vcuiprof again to read it."] = "측정을 켰습니다. 잠시 플레이한 뒤 /vcuiprof 를 다시 입력하세요.",
    -- Patch notes 1.37.3
    ["Class Trainer page"] = "직업 교관 페이지",
    ["Fixed the page being thrown away again a moment after you opened it, dropping you back on a class tab. The spell book resets its own page whenever your spells change, and our page sits past the last real tab, so it was always the one discarded. Most noticeable on Season of Discovery, where engraving changes spells constantly."] = "페이지를 연 직후 다시 버려져 직업 탭으로 되돌아가던 문제를 고쳤습니다. 주문책은 주문이 바뀔 때마다 자기 페이지를 초기화하는데, 우리 페이지는 마지막 실제 탭보다 뒤에 있어서 항상 버려지는 쪽이었습니다. 각인으로 주문이 계속 바뀌는 발견의 계절에서 가장 두드러졌습니다.",
    ["`/vcuiprof` measures how much frame time each part of the addon costs, then prints a list. It ships switched off and costs nothing while it is — the measuring code is only put in place when you turn it on. Type it once to start, once more to read."] = "`/vcuiprof` 는 애드온의 각 부분이 프레임 시간을 얼마나 쓰는지 측정해 목록으로 보여 줍니다. 꺼진 상태로 제공되며 그동안에는 아무 비용도 들지 않습니다. 측정 코드는 켤 때 비로소 자리에 놓입니다. 한 번 입력하면 시작하고, 한 번 더 입력하면 결과를 봅니다.",
    -- Patch notes 1.37.4
    ["Clicking a trinket button while that trinket slot is empty no longer throws an error. The game's own shortcut for \"use the item in slot N\" stopped tolerating an empty slot with July's interface update, so the button now takes a different route to the same action."] = "장신구 칸이 비어 있을 때 장신구 버튼을 눌러도 더 이상 오류가 나지 않습니다. 「N번 칸의 아이템 사용」이라는 게임 자체의 단축 방식이 7월 인터페이스 업데이트 이후 빈 칸을 허용하지 않게 되어, 버튼이 같은 동작에 다른 경로로 접근합니다.",
    ["Fixed a stutter of almost two frames every time you entered or left combat, if you use WeakAuras and have the WeakAuras skin switched on. Every combat change repainted every aura you have ever saved — including the ones not on screen — with a look that had not changed. Auras are now only repainted when the settings or their size actually changed. Measured: 28 ms down to under 2 ms. The skin itself is unchanged."] = "WeakAuras를 사용하고 저희 WeakAuras 외형이 켜져 있을 때 전투를 시작하거나 끝낼 때마다 거의 두 프레임씩 끊기던 문제를 고쳤습니다. 전투가 바뀔 때마다 저장된 모든 오라를 — 화면에 없는 것까지 — 바뀌지도 않은 외형으로 다시 칠했습니다. 이제 설정이나 크기가 실제로 바뀐 경우에만 다시 칠합니다. 측정 결과 28 ms에서 2 ms 미만으로 줄었습니다. 외형 자체는 그대로입니다.",
    -- Patch notes 1.39.0
    ["Download"] = "다운로드",
    ["Diminishing Returns Position – Put the DR row on either side of the frame, with its own X and Y offset"] = "감소 효과 위치 – 줄을 창의 좌우 어느 쪽에든 두고, 자체 X·Y 간격을 지정합니다",
    ["The DR row no longer lands on top of the trinket or racial icon. It used to hang at a fixed distance on the right edge, exactly where the side icon sits, so switching it on stacked the two. The new default clears it, and on the left edge the row grows outward instead of across the frame."] = "감소 효과 줄이 더 이상 장신구나 종족 특성 아이콘 위에 겹치지 않습니다. 예전에는 오른쪽 가장자리에서 고정된 거리에 붙어 있었는데, 그곳이 바로 옆 아이콘 자리여서 켜면 둘이 겹쳤습니다. 새 기본값은 그 자리를 비켜 가고, 왼쪽 가장자리에서는 줄이 창을 가로지르지 않고 바깥쪽으로 늘어납니다.",
    ["The trinket and racial icons sit further out from the enemy frame and are a little smaller, so the health and mana bars read as the middle of the frame instead of competing with an icon at each shoulder. Both are sliders, so your own values are kept."] = "장신구와 종족 특성 아이콘이 적 창에서 더 바깥으로 물러나고 조금 작아져서, 생명력과 마나 막대가 양쪽 어깨의 아이콘과 결루는 대신 창의 중심으로 읽힙니다. 둘 다 슬라이더이므로 직접 설정한 값은 그대로 유지됩니다.",
    ["The addon folder no longer ships build tools and source files that no player needs. The licence files stay where they are."] = "애드온 폴더에 더 이상 어느 플레이어에게도 필요 없는 빌드 도구와 원본 파일이 들어가지 않습니다. 라이선스 파일은 그대로 남습니다.",
    ["The release notes on the distribution pages are written in English now."] = "배포 페이지의 버전 정보는 이제 영어로 작성됩니다.",
    ["Six languages were missing seven texts that existed in German only. All nine are complete again."] = "여섯 개 언어에 독일어에만 있던 일곱 개의 문구가 빠져 있었습니다. 이제 아홉 언어 모두 다시 완전해졌습니다.",
    ["The keyword help for the item search was misleading in Chinese: it gave an English type name as the example, which a Chinese client would never have matched. The example is written in the reader's own language now."] = "아이템 검색의 키워드 도움말이 중국어에서 오해를 불렀습니다. 예시로 영어 종류 이름을 보여 주었는데, 중국어 클라이언트에서는 절대 찾을 수 없는 값이었습니다. 이제 예시는 읽는 사람의 언어로 표시됩니다.",
    ["Seal Twist Helper – A swing bar with the twist window marked, plus the next sensible action"] = "인장 전환 도우미 – 전환 구간이 표시된 공격 막대와 다음에 할 만한 행동",
    ["The bar counts down to your next auto attack with two marks: green is the last moment the second seal can still land, purple is how long a Judgement still fits in front of it. The next action is worked out live from your swing timer, the global cooldown and the seals actually on you — not from a fixed rotation. Crusader Strike is only suggested while there is room for it and the holding seal afterwards. Judgement deliberately gets none: it consumes the seal, and a wrong hint costs more there than no hint. Off by default."] = "막대는 다음 자동 공격까지 시간을 세며 두 개의 표시가 있습니다. 초록색은 두 번째 인장이 아직 적용될 수 있는 마지막 순간이고, 보라색은 그 앞에 심판이 아직 들어갈 수 있는 시간입니다. 다음 행동은 당신의 공격 주기와 공용 재사용 대기시간, 실제로 걸려 있는 인장에서 실시간으로 계산됩니다 — 고정된 순환에서 가져오는 것이 아닙니다. 성전사의 일격은 그것과 유지용 인장이 뒤에 들어갈 자리가 남아 있을 때만 제안됩니다. 심판은 의도적으로 제외되었습니다. 인장을 소모하기 때문에 잘못된 안내가 아무 안내도 없는 것보다 더 비쌀니다. 기본값은 꺼짐입니다.",
    -- Sidebar groups (QoL split, 1.40.0)
    ["Bags & Items"] = "가방 및 아이템",
    ["Chat & Social"] = "대화 및 사교",
    ["Extras"] = "기타",
    ["Tools"] = "도구",
    -- Overview page
    ["peak %.1f ms"] = "최고 %.1f ms",
    ["%.2f ms"] = "%.2f ms",
    ["%.1f MB"] = "%.1f MB",
    ["%d KB"] = "%d KB",
    ["%d of %d"] = "%d / %d",
    ["moved"] = "이동됨",
    ["Modules"] = "모듈",
    ["Frame time"] = "프레임 시간",
    ["Memory"] = "메모리",
    ["Windows"] = "창",
    ["%d modules are switched off."] = "%d개의 모듈이 꺼져 있습니다.",
    ["The edit mode grid is switched on."] = "편집 모드 격자가 켜져 있습니다.",
    ["There are patch notes you have not read yet."] = "아직 읽지 않은 패치 노트가 있습니다.",
    ["What would you like to change?"] = "무엇을 설정하시겠습니까?",
    ["Worth knowing"] = "알아두기",
    ["Recently visited"] = "최근 방문",
    -- Talent overrides
    ["active"] = "활성",
    ["Talent Overrides"] = "특성 그룹별 설정",
    ["Talent group %d"] = "특성 그룹 %d",
    ["%d settings overridden"] = "%d개 설정이 재정의됨",
    ["Forget all overrides for this talent group"] = "이 특성 그룹의 모든 재정의 지우기",
    ["Overrides apply on their own when you switch talent groups. This client has no specialisations, so the dual talent system is the axis."] = "재정의는 특성 그룹을 바꿀 때 저절로 적용됩니다. 이 클라이언트에는 전문화가 없어 이중 특성이 기준입니다.",
    -- Override groups
    ["Talent group %d (%s)"] = "특성 그룹 %d (%s)",
    ["Name for the new group"] = "새 그룹 이름",
    ["Editing as"] = "편집 대상",
    ["Yourself"] = "나 자신",
    ["Manage groups..."] = "그룹 관리...",
    ["Owns the current talent group"] = "현재 특성 그룹에 적용",
    ["Delete this group"] = "이 그룹 삭제",
    ["No groups yet."] = "아직 그룹이 없습니다.",
    -- Anchor points
    ["Centre"] = "가운데",
    ["Thin outline"] = "얇은 외곽선",
    ["Bar Setups"] = "바 구성",
    -- Patch notes 1.40.0
    ["Moved out of the sidebar into Global Settings, as its own tab beside Profiles. Your saved setups were kept."] = "사이드바에서 전역 설정으로 옮겨져 프로필 옆의 독립 탭이 되었습니다. 저장한 구성은 그대로 유지됩니다.",
    ["They were stored once per class profile — seven copies of one macro library. Stored once now, which cut the settings file by a third. Identical copies are merged, ones that differ are kept side by side."] = "직업 프로필마다 하나씩 저장되어 같은 매크로 라이브러리가 일곱 벌 있었습니다. 이제는 한 번만 저장되어 설정 파일이 3분의 1 줄었습니다. 내용이 같은 사본은 합쳐지고, 다른 사본은 나란히 보존됩니다.",
    ["The chat window no longer jumps back the moment you open the edit mode. Switching layouts re-anchors every window the game knows about, including ones we place ourselves."] = "편집 모드를 열자마자 대화창이 원래 자리로 튀어 돌아가지 않습니다. 배치를 전환하면 게임이 아는 모든 창이 다시 고정되는데, 여기에는 애드온이 직접 배치한 창도 포함됩니다.",
    ["A dropdown with a long entry no longer wraps into the row below it."] = "항목이 긴 드롭다운 메뉴가 더 이상 아래 줄로 넘어가지 않습니다.",
    ["The first page is a picture of your interface instead of a second sidebar: modules running, frame time and memory, windows you moved, pages you last visited."] = "첫 페이지가 두 번째 사이드바 대신 인터페이스 상태를 보여줍니다: 실행 중인 모듈, 프레임 시간과 메모리, 옮긴 창, 마지막으로 열어본 페이지.",
    ["Talent Overrides – Named groups hold their own value for individual settings and apply when you switch talent specs"] = "특성 재정의 – 이름을 붙인 그룹이 개별 설정의 값을 따로 갖고 특성 선택을 전환할 때 적용됩니다",
    ["A group can also name a situation — raid, dungeon, arena, battleground, in a group, alone. Anything you change while a group is active is recorded into it, and every overridden row is marked."] = "그룹은 상황도 지정할 수 있습니다: 공격대, 던전, 투기장, 전장, 파티 중, 혼자. 그룹이 활성인 동안 바꾼 값은 모두 그 그룹에 기록되고, 재정의된 줄에는 표시가 붙습니다.",
    ["Sliders are one row like every other setting, their number can be typed into, and labels line up in a measured column across the page. A long translation no longer pushes a value box into the next column or a button off its card."] = "슬라이더가 다른 설정과 같은 한 줄이 되었고 숫자를 직접 입력할 수 있으며, 이름표가 페이지 전체에서 측정된 열에 맞춰 정렬됩니다. 번역이 길어도 값 상자가 옆 칸으로 밀리거나 단추가 카드 밖으로 나가지 않습니다.",
    ["Every section starts closed, so a long page opens as a list of headings."] = "모든 구획이 접힌 상태로 시작하므로 긴 페이지가 제목 목록처럼 열립니다.",
    ["The automatic swap queue has controls again — order, delay and the stop marker, on the trinket page. They only ever existed in a window this addon hides."] = "자동 교체 대기열에 다시 조작 수단이 생겼습니다: 순서, 지연 시간, 정지 표식이 장신구 페이지에 있습니다. 지금까지는 이 애드온이 숨기는 창에만 있었습니다.",
    ["Trinket icons show up again: on the buttons, on the queue marker, and on your worn trinkets right after login instead of only once you click them."] = "장신구 아이콘이 다시 보입니다: 단추 위, 대기열 표식 위, 그리고 접속 직후의 착용 장신구에도 표시되며, 클릭해야 나타나던 문제가 없어졌습니다.",
    -- Befehlsregistratur
    ["%s has no handler yet — this is a bug, please report it."] = "%s에 아직 처리기가 없습니다 — 버그이니 신고해 주세요.",
    ["%s belongs to %s, which is switched off."] = "%s은(는) %s에 속하며, 해당 모듈은 꺼져 있습니다.",
    ["|cff9b6cffCommands|r — %d in total. Grey ones belong to a module that is switched off."] = "|cff9b6cff명령어|r — 모두 %d개. 회색은 꺼져 있는 모듈의 것입니다.",
    ["%s is also claimed by another addon (%s) — one of the two wins."] = "%s을(를) 다른 애드온(%s)도 사용합니다 — 둘 중 하나만 적용됩니다.",
    -- v1.40.0 nachgezogen
    ["|cffff5555Bar setups module not loaded.|r"] = "|cffff5555바 구성 모듈이 불러와지지 않았습니다.|r",
    ["Bar setup '%s' saved."] = "바 구성 '%s'을(를) 저장했습니다.",
    ["Bar setup '%s' deleted."] = "바 구성 '%s'을(를) 삭제했습니다.",
    ["Not in combat — bars can't be changed while fighting."] = "전투 중이 아닙니다 — 전투 중에는 바를 바꿀 수 없습니다.",
    ["Bar setup '%s' loaded: %d slots set, %d cleared, |cffff8800%d skipped|r (unknown spell / missing item or macro)."] = "바 구성 '%s' 불러옴: %d칸 설정, %d칸 비움, |cffff8800%d칸 건너뜀|r (알 수 없는 주문 / 없는 아이템이나 매크로).",
    ["Bar setup '%s' loaded: %d slots set, %d cleared."] = "바 구성 '%s' 불러옴: %d칸 설정, %d칸 비움.",
    ["on"] = "켜짐",
    ["Overridden settings: %s"] = "재정의된 설정: %s",
    ["Situation"] = "상황",
    ["Everywhere"] = "어디서나",
    ["Raid instance"] = "공격대 던전",
    ["5-player instance"] = "5인 던전",
    ["Battleground"] = "전장",
    ["In a group"] = "파티 중",
    ["Alone"] = "혼자",
    ["Applies only in this situation. Combined with a talent group, both have to be true - and that group then overrides one that names only the talent group."] = "이 상황에서만 적용됩니다. 특성 선택과 함께 쓰면 둘 다 참이어야 하며 — 그때 이 그룹이 특성 선택만 지정한 그룹보다 우선합니다.",
    ["Icon"] = "아이콘",
    ["No icon"] = "아이콘 없음",
    ["Shown in front of the group name in the menu and on the header button."] = "메뉴의 그룹 이름 앞과 머리글 단추에 표시됩니다.",
    ["Switch off to drop this one override. The setting then follows the profile again."] = "끄면 이 재정의 하나만 사라집니다. 해당 설정은 다시 프로필을 따릅니다.",
    ["Bar setups are now stored once for the whole account: %d kept, %d duplicates merged."] = "바 구성은 이제 계정 전체에 한 번만 저장됩니다: %d개 유지, %d개 중복 병합.",
    ["Trinket window settings now live in this addon's own database."] = "장신구 창 설정이 이제 이 애드온의 자체 데이터베이스에 있습니다.",
    ["Auto queue: top slot"] = "자동 대기열: 위쪽 칸",
    ["Auto queue: bottom slot"] = "자동 대기열: 아래쪽 칸",
    ["Auto queue for this slot"] = "이 칸의 자동 대기열",
    ["Same switch as alt-clicking the slot. While on, the queue swaps this trinket in combat, following the order below."] = "칸을 Alt+클릭하는 것과 같은 스위치입니다. 켜면 대기열이 아래 순서에 따라 전투 중 이 장신구를 교체합니다.",
    ["Order"] = "순서",
    ["The queue works through this list from the top. Pick an entry to move it or to change its settings."] = "대기열은 이 목록을 위에서부터 처리합니다. 항목을 골라 위치를 옮기거나 설정을 바꾸세요.",
    ["- empty -"] = "- 비어 있음 -",
    ["— queue stops here —"] = "— 여기서 교체를 멈춤 —",
    ["Add from bags"] = "가방에서 추가",
    ["Adds a trinket you are carrying to the end of this list."] = "지니고 있는 장신구를 이 목록 끝에 추가합니다.",
    ["Swap delay"] = "교체 지연",
    ["Seconds this trinket stays equipped before the queue swaps it out again. 0 = no wait."] = "대기열이 다시 교체하기 전까지 이 장신구를 착용한 채로 두는 시간(초). 0 = 대기 없음.",
    ["This trinket is swapped in ahead of the ones above it once it is ready."] = "이 장신구는 준비되는 즉시 위쪽 항목들보다 먼저 착용됩니다.",
    ["Pause while equipped"] = "착용 중에는 멈춤",
    ["While this trinket is worn the queue holds still - for a trinket whose effect you do not want cut short."] = "이 장신구를 착용한 동안 대기열이 멈춥니다 — 효과가 끊기면 안 되는 장신구용입니다.",
    ["|cffaaaaaaTip: left click a slot to use the trinket, right click for the list. Alt-click arms the auto queue for that slot.|r"] = "|cffaaaaaa도움말: 칸을 왼쪽 클릭하면 장신구를 사용하고, 오른쪽 클릭하면 목록이 열립니다. Alt+클릭은 그 칸의 자동 대기열을 켭니다.|r",
    ["%d snapshot(s) had the same name but different contents and were kept under a new name."] = "이름은 같지만 내용이 다른 스냅숏 %d개를 새 이름으로 보존했습니다.",
    ["GAP"] = "간격",
    ["Distance from that edge, in pixels. 0 is flush."] = "해당 가장자리로부터의 거리(픽셀). 0이면 딱 붙습니다.",
    ["Docks this window to that side of the target and centres it there. 'Centered' does not move it - it only travels along. The gap is kept edge-to-edge, so it survives either window being resized."] = "이 창을 대상 창의 해당 면에 붙이고 그 면에서 가운데로 맞춥니다. '가운데'는 창을 옮기지 않고 따라다니기만 합니다. 간격은 가장자리 대 가장자리로 유지되므로 두 창 중 어느 쪽 크기가 바뀌어도 그대로입니다.",
    ["waiting for a swing"] = "공격을 기다리는 중",
    ["  -  lag %.0fms"] = "  -  지연 %.0fms",
    ["|cffff8800No seal to twist out of. Only Seal of Command and Seal of Righteousness carry over to a swing after being replaced, so one of the two has to be learned.|r"] = "|cffff8800교체해 나올 인장이 없습니다. 교체된 뒤에도 그 공격에 적용되는 인장은 지휘의 인장과 정의의 인장뿐이므로 둘 중 하나를 배워야 합니다.|r",
    ["|cffff8800Only one seal learned. A second one is needed to twist into.|r"] = "|cffff8800인장을 하나만 배웠습니다. 교체해 들어갈 두 번째 인장이 필요합니다.|r",
    ["|cffff8800The seal you hold cannot be twisted out of. Only Seal of Command and Seal of Righteousness carry over to the swing that replaces them.|r"] = "|cffff8800유지 중인 인장에서는 교체할 수 없습니다. 자신을 대체하는 공격에까지 적용되는 인장은 지휘의 인장과 정의의 인장뿐입니다.|r",
    ["Only Seal of Command and Seal of Righteousness work here: they are the two whose effect still lands on the swing that replaces them."] = "여기에는 지휘의 인장과 정의의 인장만 쓸 수 있습니다. 자신을 대체하는 공격에까지 효과가 적용되는 인장은 이 둘뿐입니다.",
    -- Namensplaketten-Vorlage
    ["Nameplate settings replaced. Switch profile to get the old ones back."] = "이름표 설정을 교체했습니다. 프로필을 바꾸면 이전 설정으로 돌아갑니다.",
    ["Overwrites this profile's nameplate settings with a wide, flat, dark look. Other profiles are untouched."] = "이 프로필의 이름표 설정을 넓고 평평한 어두운 모습으로 덮어씁니다. 다른 프로필은 그대로입니다.",
    ["|cffaaaaaaOverwrites this profile's nameplate settings with a wide, flat, dark look. Other profiles are untouched.|r"] = "|cffaaaaaa이 프로필의 이름표 설정을 넓고 평평한 어두운 모습으로 덮어씁니다. 다른 프로필은 그대로입니다.|r",
    ["Apply the wide, flat look"] = "넓고 평평한 모습 적용",
    -- Plaetze der Namensplaketten
    ["Main positions"] = "주요 위치",
    ["|cffaaaaaaOne thing per slot. Giving a slot something takes it away from the slot that had it.|r"] = "|cffaaaaaa한 자리에 하나씩. 어떤 자리에 무언가를 넣으면 그것을 가지고 있던 자리에서 빠집니다.|r",
    ["Debuffs"] = "해로운 효과",
    ["Buffs"] = "이로운 효과",
    ["Crowd control"] = "군중 제어",
    ["Your own debuffs"] = "내가 건 해로운 효과",
    -- Leuchten bei wenig Leben, Entzauber-Leuchten
    ["Glow when low on health"] = "생명력이 낮으면 빛나기",
    ["A coloured ring around the bar once the unit drops below the mark."] = "대상이 기준 아래로 떨어지면 생명력 막대 둘레에 색 테두리가 생깁니다.",
    ["Glow below (%)"] = "빛나기 기준 (%)",
    ["Low health colour"] = "낮은 생명력 색",
    ["Glow in the aura's own school colour"] = "효과의 계열 색으로 빛나기",
    ["Magic blue, curse purple, disease orange, poison green — instead of one colour for everything."] = "마법은 파랑, 저주는 보라, 질병은 주황, 독은 초록 — 모두 한 색으로 칠하는 대신입니다.",
    -- Absorptionsstil
    ["Absorb style"] = "보호막 모양",
    ["Flat colour"] = "단색",
    -- Zauberziel
    ["Show who the cast is aimed at"] = "시전 대상 표시",
    ["The caster's current target, beside the cast bar. Your own name is coloured."] = "시전자가 현재 겨냥한 대상을 시전 막대 옆에 표시합니다. 자기 이름은 색으로 강조됩니다.",
    ["Cast target size"] = "시전 대상 글자 크기",
    -- Zielpfeile
    ["Arrows beside your target"] = "대상 옆 화살표",
    ["Two arrows pointing in at the target's bar, one on each side."] = "대상의 막대를 양쪽에서 가리키는 화살표 두 개.",
    ["Arrow size"] = "화살표 크기",
    ["Arrow distance"] = "화살표 간격",
    ["Arrow colour"] = "화살표 색",
    -- Fokus-Merkzeichen
    ["Mark on the focus plate"] = "주시 대상 이름표의 표식",
    ["A short text on your focus target's plate. A ring says this one is special; the mark says which."] = "주시 대상의 이름표에 표시되는 짧은 글자입니다. 테두리는 특별하다는 뜻이고, 표식은 무엇인지 알려줍니다.",
    ["Mark text"] = "표식 글자",
    ["Mark position"] = "표식 위치",
    ["Mark size"] = "표식 크기",
    -- Kleine Plaketten
    ["Back to the small plates"] = "작은 이름표로 되돌리기",
    ["Puts the same settings back to the small plates this addon ships with."] = "같은 설정을 이 애드온이 기본으로 제공하는 작은 이름표로 되돌립니다.",
    ["|cffaaaaaaHold Seal of Command, then cast the second seal in the last fraction of a second before your auto-attack: that swing carries both. Below level 64 the second seal is Righteousness; Blood and the Martyr replace it from there.|r"] = "|cffaaaaaa지휘의 인장을 유지하다가 자동 공격 직전 마지막 순간에 두 번째 인장을 시전하십시오. 그 공격이 둘 다 적용받습니다. 64레벨 미만에서는 두 번째 인장이 정의의 인장이고, 그 이후에는 피와 순교자의 인장이 대신합니다.|r",
    ["|cffaaaaaaThe bar counts down to the swing in zones: |cff5c8aebblue|r is free for a filler, |cffd93636red|r is the stretch where a cast would still be on the global cooldown when the window opens, and |cff33ff66green|r is the twist window. The last mark inside the green is the late twist, which leaves room for a judgement in front of the seal.|r"] = "|cffaaaaaa막대는 구간을 나누어 다음 공격까지 줄어듭니다. |cff5c8aeb파랑|r은 다른 주문을 넣어도 되는 구간, |cffd93636빨강|r은 지금 시전하면 구간이 열릴 때까지 공용 재사용 대기시간이 남는 구간, |cff33ff66초록|r은 교체 구간입니다. 초록 안의 마지막 표시는 늦은 교체로, 인장 앞에 심판을 넣을 여유가 남습니다.|r",
    ["Late twist window (seconds)"] = "늦은 교체 구간(초)",
    ["The tail of the twist window, marked separately. Twisting that late still leaves room for a judgement in front of the seal. Set it as long as the twist window to hide the mark."] = "교체 구간의 마지막 부분을 따로 표시합니다. 그만큼 늦게 교체하면 인장 앞에 심판을 넣을 여유가 남습니다. 교체 구간과 같은 값으로 두면 표시가 사라집니다.",
    ["Second cue for the late window"] = "늦은 구간용 두 번째 신호음",
    ["A different sound at the late twist mark, so the two ends of the window can be told apart without looking at the bar."] = "늦은 교체 표시에서 다른 소리를 냅니다. 막대를 보지 않고도 구간의 양끝을 구분할 수 있습니다.",
    ["Shade the zones"] = "구간 색칠",
    ["Tints the part of the swing still to come in the colour of the zone it runs into."] = "아직 남은 공격 구간을 그 구간의 색으로 물들입니다.",
    ["Show the marks"] = "표시선 보기",
    ["The three boundary lines: danger zone, twist window, late twist."] = "경계선 세 개: 위험 구간, 교체 구간, 늦은 교체.",
    ["Show seal indicators"] = "인장 표시 보기",
    ["The seals currently on you and how long they last, right of the bar. Both show while the twist is in -- that overlap is the pay-off."] = "지금 걸려 있는 인장과 남은 시간을 막대 오른쪽에 표시합니다. 교체가 성공하면 둘 다 보이며, 그 겹침이 바로 이득입니다.",
    ["Seal icon size"] = "인장 아이콘 크기",
    ["Head start for the prompt (ms)"] = "알림 미리 보기(밀리초)",
    ["Shows the twist prompt and plays its cue this far before the window actually opens, so there is time to see it and press. The colours on the bar stay exact."] = "구간이 실제로 열리기 이만큼 전에 교체 알림과 소리를 냅니다. 보고 누를 시간을 벌기 위해서입니다. 막대의 색은 정확한 시점 그대로입니다.",
    ["auto"] = "자동 공격",
    ["Twist only"] = "교체만",
    ["Rotation"] = "로테이션",
    ["Show the rotation helper"] = "로테이션 도우미 표시",
    ["A row of steps above the bar: which sequence fits your weapon and haste, and where in it you are. It steps forward on what you actually cast and on your swings."] = "막대 위에 단계를 한 줄로 보여줍니다. 무기 속도와 가속에 맞는 순서가 무엇이고, 지금 그 안 어디에 있는지 알려줍니다. 실제로 시전한 주문과 공격에 따라 다음 단계로 넘어갑니다.",
    ["Sequence"] = "순서",
    ["Automatic follows your attack speed and spell haste, which is what decides how many twists fit between two strikes. Pick one by hand to drill a single sequence."] = "자동은 공격 속도와 주문 가속을 따릅니다. 두 번의 타격 사이에 교체가 몇 번 들어가는지는 그 둘이 결정합니다. 하나만 연습하려면 직접 고르십시오.",
    ["Rotation icon size"] = "아이콘 크기",
    ["Sound when the twist lands"] = "교체가 성공하면 소리",
    ["Hit sound"] = "성공음",
    ["Listen"] = "들어보기",
    ["Chime"] = "종소리",
    ["Raid warning"] = "공격대 경고",
    ["Ready check"] = "준비 확인",
    ["Click"] = "클릭",
    -- Patch notes 1.41.0
    ["Moving a frame could throw a blocked-action error if you happened to be in combat while the frames were built. The keyboard is only taken over once a mover is on screen."] = "창을 옮길 때 창이 만들어지는 동안 전투 중이면 차단 오류가 날 수 있었습니다. 이제 이동 틀이 화면에 나온 뒤에만 키보드를 가져갑니다.",
    ["The trinket window's settings were being written to the saved file a second time under their old names. They are stored once now."] = "장신구 창의 설정이 예전 이름으로 저장 파일에 한 번 더 기록되고 있었습니다. 이제 한 번만 저장됩니다.",
    ["42 texts existed in German only, among them the whole talent override interface and the trinket queue. All nine languages are complete again."] = "42개 문구가 독일어에만 있었습니다. 특성 재정의 화면 전체와 장신구 대기열이 여기에 포함됩니다. 아홉 언어가 다시 완전해졌습니다.",
    ["Main positions – Six slots around the plate, each holding one thing: debuffs, buffs, crowd control or your own damage-over-time"] = "주요 위치 – 이름표 둘레의 여섯 자리, 각 자리에 하나씩: 해로운 효과, 이로운 효과, 군중 제어, 또는 내가 건 지속 피해",
    ["Glow when low on health – A coloured ring once the unit drops past your mark"] = "생명력이 낮으면 빛나기 – 대상이 기준 아래로 떨어지면 색 테두리가 생깁니다",
    ["Arrows beside your target – Two arrows pointing in at the bar"] = "대상 옆 화살표 – 양쪽에서 막대를 가리키는 화살표 두 개",
    ["Mark on the focus plate – A short text, so target and focus stay apart at a glance"] = "주시 대상 이름표의 표식 – 대상과 주시 대상을 한눈에 구분할 짧은 글자",
    ["Preset – One click for a wide, flat, dark look, and one to put the small plates back"] = "틀 – 넓고 평평한 어두운 모습으로 한 번에, 작은 이름표로 되돌리기도 한 번에",
    ["Two of the six slots sit beside the plate as a column, which was not possible before. And two rows can no longer land on top of each other: giving a slot something takes it away from the slot that had it."] = "여섯 자리 중 둘은 이름표 옆에 세로 줄로 놓입니다. 예전에는 불가능했습니다. 그리고 두 줄이 겹칠 수 없습니다: 어떤 자리에 무언가를 넣으면 그것을 가지고 있던 자리에서 빠집니다.",
    ["The cast bar can name who the cast is aimed at, your own name coloured."] = "시전 막대가 시전 대상을 표시할 수 있으며, 자기 이름은 색으로 강조됩니다.",
    ["Twist zones – The swing bar answers what you may press now instead of counting down"] = "전환 구간 – 시전 막대가 남은 시간을 세는 대신 지금 무엇을 눌러도 되는지 알려줍니다",
    ["Rotation helper – A short sequence rather than a single next step, worked out from your weapon and cast speed"] = "연계 도우미 – 다음 한 단계가 아니라 짧은 순서를, 무기 속도와 시전 속도로 계산해서 보여줍니다",
    ["The seal you twist into may be any other seal, not only the two that arrive at level 64."] = "전환해 들어갈 인장은 64레벨에 배우는 둘뿐 아니라 다른 어떤 인장이든 될 수 있습니다.",
    ["Sections no longer fold away. Long pages fold at the gear on a row instead, which says something a section expander never could: the rows behind it belong to the switch it sits on."] = "구획은 더 이상 접히지 않습니다. 긴 페이지는 대신 줄에 달린 톱니로 접힙니다. 톱니는 구획 접기가 결코 말하지 못한 것을 말합니다: 그 뒤의 줄은 톱니가 붙은 스위치의 것입니다.",
    ["Controls line up down a page now, and a switch sits in the middle of its row."] = "조작 요소가 페이지 아래로 줄을 맞추고, 스위치는 자기 줄의 한가운데에 놓입니다.",
    -- Vier Nachzuegler
    ["Darken enemies out of combat"] = "전투 중이 아닌 적 어둡게",
    ["Dims enemies that are not fighting anyone, so the ones that are stand out. Never your own target."] = "아무와도 싸우지 않는 적을 흐리게 하여 싸우는 적이 드러나게 합니다. 자기 대상은 제외됩니다.",
    ["Darken to (%)"] = "어둡게 (%)",
    ["Cast bars in front of other plates"] = "시전 막대를 다른 이름표 앞에",
    ["In a pull the plates overlap and a cast bar can end up behind the plate in front of it."] = "몰이를 할 때 이름표가 겹치면 시전 막대가 앞쪽 이름표 뒤로 숨을 수 있습니다.",
    ["Highlight strength"] = "강조 세기",
    ["Hitbox width (%)"] = "클릭 영역 너비 (%)",
    ["Clickable plate area. 100 leaves the game's own size untouched. Stored in the profile."] = "이름표의 클릭 영역입니다. 100이면 게임 기본 크기를 건드리지 않습니다. 프로필에 저장됩니다.",
    ["Hitbox height (%)"] = "클릭 영역 높이 (%)",
    -- Wechsel verloren
    -- Gewehrschuss
    ["Rifle"] = "소총 발사",
    -- Aktionszeile
    ["Action text size"] = "행동 문구 크기",
    ["The line that names what to press. 0 follows the general text size."] = "무엇을 누를지 알려주는 줄입니다. 0이면 일반 글자 크기를 따릅니다.",
    -- Tempo- und Siegel-Timer-Groesse
    ["Seal timer text size"] = "인장 타이머 글자 크기",
    ["The countdown on the seal icons. 0 scales it with the icon."] = "인장 아이콘 위의 남은 시간입니다. 0이면 아이콘 크기에 맞춥니다.",
    -- Warnzeile
    ["Warning text size"] = "경고 문구 크기",
    ["The red and yellow warnings on the bar. 0 follows the action text size."] = "막대 위의 빨강, 노랑 경고입니다. 0이면 행동 문구 크기를 따릅니다.",
    -- Bedingungen je Eintrag
    ["Narrows this icon to a number of stacks, or to the last seconds before it runs out."] = "이 아이콘을 중첩 수나, 사라지기 직전의 마지막 몇 초로 제한합니다.",
    ["Only from stacks"] = "이 중첩부터만",
    ["0 = any number of stacks."] = "0 = 중첩 수를 따지지 않음.",
    ["Only in the last seconds"] = "마지막 몇 초에만",
    ["0 = at any time. Otherwise the icon appears only this close to running out."] = "0 = 항상. 그 외에는 사라지기 이만큼 전부터만 나타납니다.",
    -- Einheit je Gruppe
    ["Watch this unit"] = "이 대상 관찰",
    ["Whose auras this group reads. The default is what the group type has always used."] = "이 그룹이 누구의 효과를 읽을지 정합니다. 기본값은 그룹 종류가 원래 쓰던 대상입니다.",
    ["You"] = "나",
    ["Target"] = "대상",
    ["Focus"] = "주시 대상",
    -- Nur eigene Auren
    ["Only what I cast myself"] = "내가 직접 건 것만",
    ["Off counts the aura no matter who put it there - for a raid debuff that anyone may apply."] = "끄면 누가 걸었는지 상관없이 셉니다 — 아무나 걸 수 있는 공격대 약화 효과를 위해서입니다.",
    -- Sortierung
    ["Fixed keeps the order you added them in. The other two reorder live by what is left."] = "고정은 추가한 순서를 그대로 둡니다. 나머지 둘은 남은 시간에 따라 실시간으로 재배치합니다.",
    ["As added"] = "추가한 순서대로",
    ["Least time left first"] = "남은 시간이 짧은 것부터",
    ["Most time left first"] = "남은 시간이 긴 것부터",
    ["Practice"] = "연습",
    ["|cffaaaaaaA swing clock that runs on its own, with no target and nothing spent. Press your bound keys against it and every swing is graded: the twist landed, it was too early, or nothing was attempted. The seal model is the real one -- a replaced seal keeps resolving for 0.4 seconds -- so the timing you learn here is the timing that works.|r"] = "|cffaaaaaa대상도 소모도 없이 스스로 돌아가는 평타 시계입니다. 지정한 키를 눌러 맞춰 보면 평타마다 채점이 붙습니다. twist 성공, 너무 이름, 아니면 시도 없음. 인장 처리 방식은 실제와 똑같아서 -- 교체된 인장도 0.4초 동안 계속 발동합니다 -- 여기서 익힌 타이밍이 실전에서 그대로 통합니다.|r",
    ["Start / stop practice"] = "연습 시작/중지",
    ["Stop practice"] = "연습 중지",
    ["Simulated weapon speed"] = "가상 무기 속도",
    ["0 uses whatever you have equipped. Any other value drills a speed you do not own yet, which is how you find out that the weapon you are saving for needs a different sequence."] = "0이면 지금 착용한 무기를 그대로 씁니다. 다른 값을 넣으면 아직 갖지 못한 속도로 연습하게 되며, 모으는 중인 무기가 다른 순서를 요구한다는 사실을 그렇게 미리 알게 됩니다.",
    ["Spell queue window (ms)"] = "주문 예약 시간 (ms)",
    ["A key pressed this far before the global cooldown ends is held and fires the moment it does, exactly as the client does it. Practising without it teaches a rhythm the game never asks for."] = "전역 재사용 대기시간이 끝나기 이만큼 전에 누른 키는 대기했다가 끝나는 순간 발동합니다. 클라이언트와 똑같은 방식입니다. 이 값 없이 연습하면 게임이 요구하지도 않는 박자를 익히게 됩니다.",
    ["Result text size"] = "결과 글자 크기",
    ["Result text duration (seconds)"] = "결과 표시 시간 (초)",
    ["Landed colour"] = "성공 색상",
    ["Missed colour"] = "실패 색상",
    ["Show the fight timeline"] = "전투 타임라인 표시",
    ["Every swing and every cast on one strip against a ruler. The ruler is the point: without it you can see that two swings were close together but not how close, which is the only number practice is about."] = "모든 평타와 모든 시전을 눈금자 위 하나의 띠에 올립니다. 핵심은 눈금자입니다. 눈금이 없으면 두 평타가 가까웠다는 것만 보이고 얼마나 가까웠는지는 알 수 없는데, 연습에서 중요한 숫자는 오직 그것뿐입니다.",
    ["Timeline width"] = "타임라인 너비",
    ["Timeline pixels per second"] = "타임라인 초당 픽셀",
    ["TWIST"] = "twist",
    ["MISS"] = "실패",
    ["TOO EARLY"] = "너무 이름",
    ["speed %.2fs  -  GCD %.2fs  -  %d of %d"] = "속도 %.2f초  -  전역 %.2f초  -  %d / %d",
    ["|cffffffffPRACTICE|r"] = "|cffffffff연습|r",
    ["|cffffffffRESULT|r"] = "|cffffffff결과|r",
    ["|cffffffffTIMELINE|r"] = "|cffffffff타임라인|r",
    ["|cffffcc33Twist practice|r"] = "|cffffcc33twist 연습|r",
    ["Practice needs two seals: pick them under Seals first."] = "연습에는 인장 두 개가 필요합니다. 먼저 인장 항목에서 골라 주세요.",
    ["Practice mode on. Press your bound keys; the swing runs on its own."] = "연습 모드 켜짐. 지정한 키를 누르세요. 평타는 알아서 돌아갑니다.",
    ["Practice mode off. %d of %d swings carried the twist."] = "연습 모드 꺼짐. 평타 %d/%d회가 twist를 실었습니다.",
    ["Bloodlust"] = "피의 욕망",
    ["Haste potion"] = "가속 물약",
    ["Abacus"] = "주판",
    ["Time warp"] = "시간 왜곡",
    ["Crusader Strike"] = "성전사의 일격",
    ["Judgement"] = "심판",
    ["Cast the held seal"] = "유지 인장 시전",
    ["Cast the twist seal"] = "twist 인장 시전",
    ["Filler"] = "빈틈 채우기",
    ["Start / stop attack"] = "공격 시작/중지",
    ["wait"] = "대기",
    ["Next action"] = "다음 행동",
    ["|cffffffffNEXT ACTION|r"] = "|cffffffff다음 행동|r",
    ["Next action mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "다음 행동 이동 모드가 켜졌습니다. |cff9b6cff보라색 상자를 끌거나|r |cff9b6cff방향키|r를 사용하세요 (SHIFT = 5px). 마치려면 '잠금 해제 / 테스트'를 다시 누르세요.",
    ["Next action mover disabled."] = "다음 행동 이동 모드가 꺼졌습니다.",
    ["|cffaaaaaaAn icon of the one thing to press, wherever you want it. It answers the same question as the line under the bar -- the three switches below feed both, so the word and the picture can never disagree.|r"] = "|cffaaaaaa지금 눌러야 할 단 하나를 아이콘으로, 원하는 자리에 보여 줍니다. 막대 아래 문구와 같은 질문에 답합니다 -- 아래 세 가지 설정이 둘 모두를 움직이므로, 글자와 그림이 서로 어긋날 일은 없습니다.|r",
    ["Show the next action guide"] = "다음 행동 안내 표시",
    ["When to show it"] = "표시 조건",
    ["Show a hold instead of nothing"] = "빈칸 대신 대기 표시",
    ["While the right move is to press nothing on purpose -- the twist is coming and anything else would cost it -- the guide keeps showing the seal, drained and outlined. An empty box says the same thing much less clearly."] = "일부러 아무것도 누르지 않는 것이 정답인 동안 -- twist가 코앞이라 다른 행동은 twist를 망칩니다 -- 안내는 해당 인장을 흐리게, 외곽선만 남긴 채 계속 보여 줍니다. 빈 칸도 같은 뜻이지만 훨씬 알아보기 어렵습니다.",
    ["Suggest Judgement"] = "심판 제안",
    ["Judging consumes the seal, so it is only ever offered with room to re-seal afterwards. Off by default: a mistimed judgement costs more than no suggestion at all."] = "심판은 인장을 소모하므로, 뒤이어 인장을 다시 올릴 여유가 있을 때만 제안합니다. 기본값은 꺼짐입니다. 타이밍을 놓친 심판은 아무 제안도 없는 것보다 손해가 큽니다.",
    ["Suggest a filler"] = "빈틈 채우기 제안",
    ["Consecration, or Exorcism where the target can take it, in the stretch of the swing that is free for it. Exorcism is offered by asking the client whether the spell can be aimed at your target, which is right in every language."] = "평타 중 여유가 있는 구간에 신성화를, 대상에게 통하는 경우에는 퇴마를 제안합니다. 퇴마는 그 주문을 지금 대상에게 겨눌 수 있는지 클라이언트에 직접 물어 판단하므로 어떤 언어에서도 정확합니다.",
    ["Consecration mana floor (%)"] = "신성화 최소 마나 (%)",
    ["Below this share of your mana the filler is not worth it."] = "마나가 이 비율 아래로 내려가면 빈틈 채우기는 손해입니다.",
    ["Exorcism mana floor (%)"] = "퇴마 최소 마나 (%)",
    ["Longest Crusader Strike delay (ms)"] = "성전사의 일격 최대 지연 (ms)",
    ["Once leaving the strike any longer than this would waste it, it stops being a suggestion and becomes the answer. Measured against the earliest moment you could actually cast it, not against now."] = "이보다 더 미루면 일격이 낭비되는 시점부터, 제안이 아니라 정답으로 바뀝니다. 기준은 지금이 아니라 실제로 시전할 수 있는 가장 이른 순간입니다.",
    ["Twist!"] = "twist!",
    ["|cffffffffTWIST TEXT|r"] = "|cfffffffftwist 문구|r",
    ["Twist text mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "twist 문구 이동 모드가 켜졌습니다. |cff9b6cff보라색 상자를 끌거나|r |cff9b6cff방향키|r를 사용하세요 (SHIFT = 5px). 마치려면 '잠금 해제 / 테스트'를 다시 누르세요.",
    ["Twist text mover disabled."] = "twist 문구 이동 모드가 꺼졌습니다.",
    ["Twist landed"] = "twist 성공",
    ["|cffaaaaaaAll three cues below wait for PROOF, not for a prediction. A swing has to land with both seals up, and the held seal's own damage has to follow it in the combat log. Nothing fires without that second line -- a confirmation that is right most of the time is one you cannot practise against.|r"] = "|cffaaaaaa아래 세 가지 신호는 모두 예측이 아니라 증거를 기다립니다. 두 인장이 모두 올라간 상태로 평타가 적중해야 하고, 유지 인장 자체의 피해가 전투 기록에 뒤따라야 합니다. 그 두 번째 줄 없이는 아무것도 울리지 않습니다 -- 대체로 맞는 정도의 확인 신호로는 연습이 되지 않습니다.|r",
    ["Sound channel"] = "소리 채널",
    ["Master"] = "마스터",
    ["Sound effects"] = "효과음",
    ["Master ignores the sound effects slider, which is what a confirmation wants: it is feedback about the fight rather than part of it."] = "마스터는 효과음 조절기를 무시하는데, 확인 신호에는 그편이 맞습니다. 전투의 일부가 아니라 전투에 대한 알림이기 때문입니다.",
    ["The sniper and rifle cracks are bundled; the rest are the client's own cues. Below them stand any sounds other addons have registered as shared media."] = "저격과 소총 소리는 함께 들어 있고, 나머지는 클라이언트 자체 알림음입니다. 그 아래에는 다른 애드온이 공유 미디어로 등록한 소리가 이어집니다.",
    ["Sniper"] = "저격",
    ["Level up"] = "레벨 상승",
    ["Quest complete"] = "퀘스트 완료",
    ["Bonus objective"] = "보너스 목표",
    ["Map ping"] = "지도 신호",
    ["Glow on the bar when the twist lands"] = "twist 성공 시 막대 발광",
    ["Glow style"] = "발광 방식",
    ["Pixel border"] = "픽셀 테두리",
    ["Autocast ring"] = "자동 시전 고리",
    ["Pixel border traces the bar's own outline at any width. Autocast pins the client's own ring to the four corners, so it stays a ring however wide the bar gets."] = "픽셀 테두리는 너비와 상관없이 막대의 윤곽을 그대로 따라갑니다. 자동 시전 고리는 클라이언트 기본 고리를 네 모서리에 고정하므로, 막대가 아무리 넓어져도 고리 모양을 유지합니다.",
    ["Glow colour"] = "발광 색상",
    ["Glow duration (seconds)"] = "발광 지속 시간 (초)",
    ["Text when the twist lands"] = "twist 성공 시 문구",
    ["A line somewhere on screen, with its own position. Useful where the bar is in the corner of the eye and the confirmation should be in the middle of it."] = "화면 어디든 원하는 자리에 놓을 수 있는 한 줄입니다. 막대는 시야 구석에 두고 확인 신호만 그 한가운데로 보내고 싶을 때 좋습니다.",
    ["Text font"] = "문구 글꼴",
    ["Text outline"] = "문구 외곽선",
    ["Text colour"] = "문구 색상",
    ["Text duration (seconds)"] = "문구 지속 시간 (초)",
    ["|cffffffffSEALS|r"] = "|cffffffff인장|r",
    ["Seal indicator mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "인장 표시기 이동 모드가 켜졌습니다. |cff9b6cff보라색 상자를 끌거나|r |cff9b6cff방향키|r를 사용하세요 (SHIFT = 5px). 마치려면 '잠금 해제 / 테스트'를 다시 누르세요.",
    ["Seal indicator mover disabled."] = "인장 표시기 이동 모드가 꺼졌습니다.",
    ["Match the bar height"] = "막대 높이에 맞추기",
    ["Sizes the icons to the bar instead of to their own setting, so the pair keeps lining up with it when the bar height changes."] = "아이콘 크기를 자체 설정 대신 막대에 맞춥니다. 막대 높이가 바뀌어도 두 아이콘이 계속 막대와 나란히 정렬됩니다.",
    ["Ignored while the icons match the bar height."] = "아이콘이 막대 높이에 맞춰져 있는 동안에는 무시됩니다.",
    ["Seal icon spacing"] = "인장 아이콘 간격",
    ["Centre the icons"] = "아이콘 가운데 정렬",
    ["Keeps the midpoint of the pair still when the second seal appears or falls off. Left-aligned keeps the first icon still instead, which is what an attached pair wants -- that edge is the bar."] = "두 번째 인장이 나타나거나 사라져도 두 아이콘의 중심이 움직이지 않습니다. 왼쪽 정렬은 대신 첫 아이콘을 고정하는데, 막대에 붙여 놓은 경우에는 그편이 맞습니다 -- 그 가장자리가 곧 막대이기 때문입니다.",
    ["Show the cooldown sweep"] = "재사용 대기 회전 표시",
    ["The client's own sweep across the icon. It says the same thing as the number under it, but it says it without being read."] = "아이콘 위를 도는 클라이언트 기본 회전 표시입니다. 아래 숫자와 같은 내용을 말하지만, 읽지 않아도 알 수 있게 말합니다.",
    ["Seal timer colour"] = "인장 시간 색상",
    ["Detach from the bar"] = "막대에서 분리",
    ["Gives the pair its own position anywhere on screen. They stay tied to the bar in every other way: when it is hidden, they are too."] = "두 아이콘에 화면 어디든 독자적인 자리를 줍니다. 그 밖의 모든 면에서는 막대에 묶여 있어서, 막대가 숨겨지면 아이콘도 함께 숨겨집니다.",
    ["Twist lost"] = "twist 실패",
    ["Swing ready -- restart your attack"] = "평타 준비됨 -- 공격을 다시 시작하세요",
    ["(none available)"] = "(사용 가능한 항목 없음)",
    ["Solid"] = "단색",
    ["Attack speed"] = "공격 속도",
    ["Swing timer"] = "평타 시간",
    ["Latency (ms)"] = "지연시간 (ms)",
    ["Global cooldown left"] = "남은 전역 재사용 대기시간",
    ["Nothing"] = "없음",
    ["Left readout"] = "왼쪽 표시값",
    ["What the left end of the bar shows. Attack speed turns into the warning colour below two global cooldowns per swing -- under that the twist and the seal going back up no longer both fit, so wait for the cooldown before twisting."] = "막대 왼쪽 끝에 무엇을 표시할지 정합니다. 공격 속도는 평타당 전역 재사용 대기시간 두 번이 안 되는 순간 경고 색으로 바뀝니다 -- 그 아래에서는 twist와 인장을 다시 올리는 일이 한 평타에 함께 들어가지 않으므로, twist 하기 전에 대기시간을 기다려야 합니다.",
    ["Right readout"] = "오른쪽 표시값",
    ["Readout text size"] = "표시값 글자 크기",
    ["The two numbers inside the bar. 0 follows the general text size."] = "막대 안의 두 숫자입니다. 0이면 일반 글자 크기를 따릅니다.",
    ["Global cooldown bar texture"] = "전역 재사용 대기시간 막대 텍스처",
    ["Border"] = "테두리",
    ["Solid draws four flat edges in the colour below. Texture takes an edge file from shared media, which is what a border from another interface pack looks like."] = "단색은 아래 색으로 네 변을 평평하게 그립니다. 텍스처는 공유 미디어의 테두리 파일을 쓰는데, 다른 인터페이스 묶음에서 온 테두리가 바로 이 방식입니다.",
    ["Only used while the border is set to texture."] = "테두리가 텍스처로 설정된 동안에만 사용됩니다.",
    ["Border width"] = "테두리 두께",
    ["Marker texture"] = "표식 텍스처",
    ["Marker width"] = "표식 두께",
    ["Font colour"] = "글꼴 색상",
    ["Frame strata"] = "프레임 층",
    ["Which layer of the interface the helper sits in. Raise it to lift the bar over another addon that draws in the same place."] = "이 도우미가 인터페이스의 어느 층에 놓일지 정합니다. 같은 자리에 그리는 다른 애드온 위로 막대를 올리려면 값을 높이세요.",
    ["Draw level"] = "그리기 단계",
    ["The order inside the chosen layer. Higher draws on top."] = "선택한 층 안에서의 순서입니다. 값이 높을수록 위에 그려집니다.",
    ["Colour the bar by"] = "막대 색상 기준",
    ["The zone the swing is in"] = "평타가 지나는 구간",
    ["The seal you are carrying"] = "지금 유지 중인 인장",
    ["Zones colour the fill by the stretch of the swing you are in, which is what this helper is built around. Seal colours it by what you are carrying, which is the faster read once the timing is in your fingers. Either way the special colours below outrank the choice."] = "구간은 지금 지나고 있는 평타의 구간에 따라 채움 색을 정하며, 이 도우미는 바로 그 기준 위에 만들어졌습니다. 인장은 지금 유지 중인 인장에 따라 색을 정하는데, 타이밍이 손에 익은 뒤에는 이쪽이 더 빨리 읽힙니다. 어느 쪽이든 아래의 특수 색상이 이 선택보다 우선합니다.",
    ["Seal of Command"] = "명령의 인장",
    ["Seal of Righteousness"] = "정의의 인장",
    ["Seal of Blood / the Martyr"] = "피의 인장 / 순교자의 인장",
    ["Seal of Vengeance"] = "복수의 인장",
    ["Seal of the Crusader"] = "성전사의 인장",
    ["Seal of Justice"] = "심판의 인장",
    ["Seal of Light"] = "빛의 인장",
    ["Seal of Wisdom"] = "지혜의 인장",
    ["No twist possible"] = "twist 불가",
    ["The fill while this swing's twist is already gone, and the tail of the swing a cast can no longer reach."] = "이번 평타의 twist가 이미 지나간 동안의 채움 색, 그리고 시전이 더는 닿지 못하는 평타의 끝자락 색입니다.",
    ["Warning"] = "경고",
    ["The warnings on the bar, and the attack speed once the weapon is too fast to twist with."] = "막대 위의 경고, 그리고 무기가 너무 빨라 twist 할 수 없을 때의 공격 속도 색입니다.",
    ["Twisting"] = "twist 중",
    ["The fill while both seals are up: the twist is in and this swing carries it."] = "두 인장이 모두 올라가 있는 동안의 채움 색입니다. twist가 성립했고 이번 평타가 그것을 싣습니다.",
    ["Default"] = "기본",
    ["The fill with no seal up and between swings."] = "인장이 올라가 있지 않을 때와 평타 사이의 채움 색입니다.",
    ["Global cooldown"] = "전역 재사용 대기시간",
    ["Deadzone"] = "데드존",
    ["Twist window padding"] = "twist 구간 여유",
    ["Pulls the twist window earlier so the cast still reaches the server inside it. Dynamic follows your calibrated latency; fixed is a number you choose yourself."] = "twist 구간을 앞으로 당겨서 시전이 그 안에서 서버까지 닿도록 합니다. 동적은 보정된 지연시간을 따르고, 고정은 직접 정한 값을 씁니다.",
    ["Fixed twist padding (ms)"] = "고정 twist 여유 (ms)",
    ["Only used while the padding mode is set to fixed."] = "여유 방식이 고정으로 설정된 동안에만 사용됩니다.",
    ["Dynamic (follows latency)"] = "동적 (지연시간을 따름)",
    ["Fixed"] = "고정",
    ["Latency"] = "지연시간",
    ["|cffaaaaaaThe round trip your client reports is not the delay a twist has to beat: the client adds a slice of its own, so the figure everything below works from is (world latency x multiplier) + offset. Raise the multiplier if you keep missing twists that looked in time.|r"] = "|cffaaaaaa클라이언트가 알려 주는 왕복 시간은 twist가 이겨야 할 지연이 아닙니다. 클라이언트가 자체적으로 얼마를 더 얹기 때문에, 아래 항목들이 기준으로 삼는 값은 (월드 지연시간 x 배율) + 보정값입니다. 제때 눌렀는데도 twist를 계속 놓친다면 배율을 높이세요.|r",
    ["Latency multiplier"] = "지연시간 배율",
    ["Latency offset (ms)"] = "지연시간 보정 (ms)",
    ["Shade the deadzone"] = "데드존 음영 표시",
    ["The tail of the swing a cast can no longer cross, shaded at the end of the bar. Its size follows your raw world latency rather than the calibrated figure, because this one is the wire and not a prediction. This switch only draws it -- the timing itself always accounts for it, so set the scale to 0 if you want no compensation at all."] = "시전이 더는 넘어설 수 없는 평타의 끝자락을 막대 끝에 음영으로 표시합니다. 크기는 보정된 값이 아니라 실제 월드 지연시간을 그대로 따르는데, 이 구간은 예측이 아니라 회선 그 자체이기 때문입니다. 이 설정은 표시만 담당합니다 -- 타이밍 계산에는 언제나 반영되므로, 보정을 완전히 없애려면 배율을 0으로 두세요.",
    ["Deadzone scale"] = "데드존 배율",
    ["Multiplies your world latency. Raise it if you cannot twist just outside the shaded stretch, lower it if you still can inside it. 0 switches the compensation off entirely."] = "월드 지연시간에 곱하는 값입니다. 음영 구간 바로 바깥에서도 twist가 되지 않으면 높이고, 음영 안에서도 twist가 되면 낮추세요. 0이면 보정이 완전히 꺼집니다.",
    ["Deadzone texture"] = "데드존 텍스처",
    ["Deadzone transparency"] = "데드존 투명도",
    ["Global cooldown padding"] = "전역 재사용 대기시간 여유",
    ["Pulls the global cooldown boundary earlier by part of your latency, so a cast started right at the mark still clears the cooldown in time."] = "전역 재사용 대기시간의 경계를 지연시간의 일부만큼 앞으로 당겨서, 경계에 딱 맞춰 시작한 시전도 제때 대기시간을 넘기도록 합니다.",
    ["Fixed global cooldown padding (ms)"] = "고정 전역 재사용 대기시간 여유 (ms)",
    ["Show the judgement mark"] = "심판 표식 표시",
    ["A fourth line where Judgement comes off cooldown during this swing, so a judgement can be put in front of the twist instead of on top of it. Only drawn while a seal is up."] = "이번 평타 도중 심판의 재사용 대기시간이 끝나는 지점을 네 번째 선으로 보여 줍니다. 덕분에 심판을 twist 에 겹치지 않고 그 앞에 넣을 수 있습니다. 인장이 올라가 있는 동안에만 그려집니다.",
    ["Show the global cooldown bar"] = "전역 재사용 대기시간 막대 표시",
    ["A strip along the bottom of the bar reaching to the moment the global cooldown frees up, so you can see how much of this swing is already spoken for."] = "막대 아래를 따라 전역 재사용 대기시간이 풀리는 순간까지 이어지는 띠입니다. 이번 평타에서 이미 묶여 있는 몫이 얼마나 되는지 볼 수 있습니다.",
    ["Global cooldown bar height"] = "전역 재사용 대기시간 막대 높이",
    ["When to show the bar"] = "막대 표시 조건",
    ["Always keeps it on screen, which is the easier way to practise the timing on a dummy. Seal active shows it whenever you are carrying a seal, in or out of a fight."] = "항상은 화면에 계속 띄워 두며, 허수아비에서 타이밍을 연습하기에는 이쪽이 편합니다. 인장 유지 중은 전투 안팎을 가리지 않고 인장을 지니고 있을 때마다 표시합니다.",
    ["Seal active"] = "인장 유지 중",
    ["In combat or seal active"] = "전투 중 또는 인장 유지 중",
    ["Only with Two-Handed Weapon Specialization"] = "양손 무기 전문화가 있을 때만",
    ["Hides the helper unless you have a point in the talent. Twisting works without it, but the slow swing it is built around is what makes the whole habit pay."] = "해당 특성에 점을 찍지 않았다면 도우미를 숨깁니다. 특성이 없어도 twist는 되지만, 이 습관이 값어치를 하는 것은 특성이 전제하는 느린 평타 덕분입니다.",
    ["Neck"] = "목",
    ["Shoulder"] = "어깨",
    ["Waist"] = "허리",
    ["Legs"] = "다리",
    ["Wrist"] = "손목",
    ["Hands"] = "손",
    ["Finger 2"] = "반지 2",
    ["Trinket 2"] = "장신구 2",
    ["Off Hand"] = "보조 장비",
    ["Ranged"] = "원거리",
    -- Patch notes 1.42.0
    ["Practice – A swing clock that runs on its own, with your own keys and a verdict on every swing"] = "연습 – 스스로 돌아가는 평타 시계, 직접 지정한 키와 매 평타 판정",
    ["Next action – An icon of the one thing to press, wherever you put it"] = "다음 행동 – 지금 눌러야 할 단 하나를 원하는 자리에 띄우는 아이콘",
    ["Latency – Calibrate the delay a twist has to beat, with its own multiplier and offset"] = "지연시간 – twist가 이겨야 할 지연을 자체 배수와 보정값으로 조정",
    ["Shade the deadzone – The tail of the swing a cast can no longer cross"] = "데드존 음영 표시 – 시전이 더는 넘을 수 없는 평타의 끝부분",
    ["Show the global cooldown bar – A strip reaching to the moment the cooldown frees up"] = "전역 재사용 대기시간 막대 표시 – 대기시간이 풀리는 순간까지 이어지는 띠",
    ["When to show the bar – Always, in combat, while a seal is up, or either"] = "막대 표시 조건 – 항상, 전투 중, 인장이 올라간 동안, 또는 둘 중 하나",
    ["Colour the bar by – The zone the swing is in, or the seal you are carrying"] = "막대 색상 기준 – 평타가 놓인 구간, 또는 지금 든 인장",
    ["Detach from the bar – The seal icons take their own position, with a cooldown sweep"] = "막대에서 분리 – 인장 아이콘이 자체 위치와 재사용 대기시간 표시를 가집니다",
    ["Suggest Judgement – Offered only with room to re-seal afterwards, and off until you ask"] = "심판 제안 – 다시 인장을 올릴 여유가 있을 때만, 그리고 켜기 전까지는 꺼져 있습니다",
    ["Textures, border, font, frame layer, marker width and the two readouts inside the bar are yours to set, and every seal has its own colour."] = "재질과 테두리, 글꼴, 프레임 층, 표식 두께, 막대 안의 두 표시가 모두 취향대로이며 인장마다 색을 따로 지정합니다.",
    -- Patch notes 1.42.0
    ["The twist is now called twist in every language, the word paladins use themselves. German called it Siegelwechsel; the helper and its window are named after the twist instead."] = "이 기술은 이제 모든 언어에서 twist라고 부릅니다. 성기사들이 실제로 쓰는 말입니다. 독일어에서는 Siegelwechsel이었고, 이제 도우미와 그 창이 twist를 따릅니다.",
    ["The cue for a landed twist no longer guesses. It used to fire the moment a seal went out inside the window, which is a prediction the server can disagree with. Now the combat log has to show a swing landing with both seals up and the held seal's own damage behind it. Without that, nothing sounds."] = "성공한 twist 알림은 더 이상 추측하지 않습니다. 예전에는 인장이 구간 안에서 나가는 순간 울렸지만, 그것은 서버가 부정할 수 있는 예측이었습니다. 이제는 전투 기록에 두 인장이 모두 올라간 평타가 적중한 것과 그 뒤를 따르는 유지 인장 자체의 피해가 있어야 합니다. 그것이 없으면 아무 소리도 나지 않습니다.",
    -- Patch notes 1.42.0
    ["Switching the module off used to leave the bag bar, the latency bar and Action Bar 1's twelve buttons behind until a /reload. All three come back on their own now."] = "모듈을 끄면 가방 막대와 지연시간 막대, 그리고 행동 단축바 1의 단추 열두 개가 /reload 전까지 그대로 남아 있었습니다. 이제 셋 다 저절로 돌아옵니다.",
    ["Rows that span the page now start their control where their neighbours do, instead of each sizing its own label."] = "한 줄을 다 쓰는 항목은 이제 이웃한 줄과 같은 자리에서 조작부가 시작됩니다. 예전에는 줄마다 이름표 너비를 따로 잡았습니다.",
    -- Patch notes 1.42.0
    ["Watch this unit – A group can follow your target, your focus or your pet instead of you"] = "이 대상 관찰 – 그룹이 나 대신 대상이나 주시 대상, 소환수를 따라갈 수 있습니다",
    ["Only what I cast myself – A group can require the aura to be your own, not anyone's"] = "내가 직접 건 것만 – 그룹이 아무 효과가 아니라 내가 건 효과만 인정하도록 요구할 수 있습니다",
    ["Order – Sort a group by the time left instead of the order you added things in"] = "순서 – 그룹을 채운 순서가 아니라 남은 시간으로 정렬합니다",
    ["Conditions belong to the individual entry now, not only to the kind of group it sits in. One entry can ask for a stack count or for the last few seconds while its neighbours ask for nothing."] = "조건이 이제 그룹 종류가 아니라 개별 항목에 붙습니다. 옆 항목은 아무 조건이 없는데 한 항목만 중첩 수나 마지막 몇 초를 요구할 수 있습니다.",
    ["Cast bars in front of other plates – So the cast you are watching is not hidden behind the plate beside it"] = "시전 막대를 다른 이름표 앞에 – 지켜보는 시전이 옆 이름표 뒤로 숨지 않도록",
    ["Darken enemies out of combat – With its own strength, so an idle mob reads as idle at a glance"] = "전투 중이 아닌 적 어둡게 – 세기를 따로 정해서, 가만히 있는 적이 한눈에 그렇게 보이도록",
    ["Highlight strength – How far the plate under your cursor lifts out of the row"] = "강조 세기 – 커서 아래의 이름표가 줄에서 얼마나 도드라지는지",
    ["The clickable area is measured from the plate now instead of assumed, so the width and height settings land where your cursor really is."] = "클릭 가능한 영역을 짐작하지 않고 이름표에서 직접 재기 때문에, 너비와 높이 설정이 커서가 실제로 있는 자리에 맞습니다.",
    ["A dropdown with more entries than fit on screen scrolls instead of running off the bottom, and a label that had grown too long fits its row again."] = "화면에 담기지 않을 만큼 항목이 많은 드롭다운은 이제 아래로 넘치지 않고 스크롤되며, 너무 길어졌던 이름표도 다시 한 줄에 들어갑니다.",
    -- Patch notes 1.43.0
    ["Compatibility"] = "호환성",
    ["The character window stayed empty on clients we had never named. The panel asked whether the client called itself one of two specific versions and refused every other one, including clients that have exactly the frames it needs. It now asks for the one thing it cannot work without. Enchants, sockets and item stats were missing for the same reason and return with it."] = "우리가 이름을 적어 두지 않은 클라이언트에서는 캐릭터 창이 비어 있었습니다. 이 패널은 클라이언트가 특정 두 버전 중 하나라고 말하는지만 물었고 나머지는 모두 거부했습니다. 필요한 프레임을 정확히 갖춘 클라이언트까지 말입니다. 이제는 없으면 동작할 수 없는 그 한 가지만 묻습니다. 인챈트와 홈, 아이템 능력치가 빠져 있던 것도 같은 이유였고 함께 돌아옵니다.",
    ["Hit rating, haste rating and spell hit rating appear on Wrath-based clients too. They were tied to a single version by name, although the game there has those stats."] = "적중 강화, 가속 강화, 주문 적중 강화가 Wrath 기반 클라이언트에서도 표시됩니다. 그곳에도 해당 능력치가 있는데 이름으로 단 하나의 버전에만 묶여 있었습니다.",
    ["The stat rows Wrath draws in pages with two dropdowns are hidden underneath our own panel now, instead of showing through it."] = "Wrath가 두 개의 드롭다운으로 페이지를 나눠 그리는 능력치 줄은 이제 우리 패널 아래에 가려집니다. 예전처럼 비쳐 보이지 않습니다.",
    ["Titan Reforged – The addon no longer reports itself out of date on the Chinese client, whose build is listed now"] = "Titan Reforged – 중국 클라이언트에서 애드온이 더 이상 구버전이라고 알리지 않습니다. 해당 빌드가 이제 목록에 있습니다",
    ["Version detection falls back to the build number whenever a client reports an identifier we have no name for. Such a client used to end up with every version flag false, which left it worse off than a client with no identifier at all, because that one at least fell back to something."] = "이름을 알지 못하는 식별자를 클라이언트가 알려 오면 버전 인식이 빌드 번호로 되돌아갑니다. 예전에는 그런 클라이언트에서 모든 버전 표시가 거짓이 되어, 식별자가 아예 없는 클라이언트보다 오히려 못한 상태였습니다. 후자는 적어도 무언가로 되돌아갔기 때문입니다.",
    ["242 texts that nothing in the interface looks up any more are gone from all nine language files, roughly eight percent of each. Renamed settings left them behind: the action bars were given clearer names a while ago and the old entries simply stayed. A check now asks the reverse question after every change, whether every translated text is still in use, so they cannot pile up again."] = "인터페이스에서 더 이상 아무도 찾지 않는 문구 242개가 아홉 개 언어 파일에서 모두 사라졌습니다. 각 파일의 약 8퍼센트입니다. 이름이 바뀐 설정이 남긴 것들로, 얼마 전 행동 단축바에 더 분명한 이름이 붙었는데 옛 항목이 그대로 남아 있었습니다. 이제 변경할 때마다 번역된 문구가 아직 쓰이는지 반대로 묻는 검사가 돌아가므로 다시 쌓이지 않습니다.",
    ["Call button – A fifth totem button for the spells that summon a whole saved totem set, shown only to characters who know one"] = "소환 버튼 – 저장해 둔 토템 세트를 통째로 소환하는 주문을 위한 다섯 번째 토템 버튼으로, 해당 주문을 아는 캐릭터에게만 보입니다",
    ["Icon Strip"] = "아이콘 줄",
    ["Distance from frame"] = "프레임과의 거리",
    ["Spacing between icons"] = "아이콘 간 간격",
    ["Racial, PvP trinket and the DR row sit on the same edge of the frame and are placed one after the other, in that order, outwards from the frame."] = "종족 특성, PvP 장신구, DR 줄은 프레임의 같은 쪽 가장자리에 자리하며 그 순서대로 바깥쪽으로 차례차례 배치됩니다.",
    ["Where it sits is set once for all three trackers under Layout, Icon Strip."] = "위치는 배치의 아이콘 줄에서 세 추적기에 대해 한 번만 설정합니다.",
    ["Gap below each frame. The opponent's pet bar hangs off the bottom of the frame, so a small gap lets it reach into the next one."] = "각 프레임 아래의 간격입니다. 상대의 소환수 바가 프레임 아래로 튀어나오므로 간격이 좁으면 다음 프레임까지 침범합니다.",
    ["Arena: racial, PvP trinket and the DR row now share one icon strip; your chosen side was kept."] = "투기장: 종족 특성, PvP 장신구, DR 줄이 이제 하나의 아이콘 줄을 공유합니다. 선택했던 방향은 그대로 유지됩니다.",
    ["|cffff5555Arena layout failed:|r %s"] = "|cffff5555투기장 배치 실패:|r %s",
    ["|cffff5555Arena icon strip error:|r %s"] = "|cffff5555투기장 아이콘 줄 오류:|r %s",
    ["Drag to reorder. Right-click removes it."] = "끌어서 순서를 바꿉니다. 오른쪽 클릭하면 제거됩니다.",
    ["That icon is added automatically — switch off auto-tracking to remove it."] = "이 아이콘은 자동으로 추가됩니다 — 제거하려면 자동 추적을 끄십시오.",
    ["Drag to reorder. Right-click an icon to remove it."] = "끌어서 순서를 바꿉니다. 아이콘을 오른쪽 클릭하면 제거됩니다.",
    ["Nothing in this bar yet. Add a spell or trinket below, or drag one onto the bar."] = "이 바에는 아직 아무것도 없습니다. 아래에서 주문이나 장신구를 추가하거나 바 위로 끌어다 놓으십시오.",
    ["+  New cooldown bar"] = "+  새 재사용 대기시간 바",
    ["+  New buff / proc bar"] = "+  새 강화 효과 / 발동 바",
    ["+  New target debuff bar"] = "+  새 대상 약화 효과 바",
    ["+  New missing-buff reminder"] = "+  새 강화 효과 누락 알림",
    ["Buffs & Procs"] = "강화 효과 및 발동",
    ["Target debuffs"] = "대상 약화 효과",
    ["Missing buffs"] = "누락된 강화 효과",
    ["New name for this bar"] = "이 바의 새 이름",
    ["Delete this bar and everything on it?"] = "이 바와 그 안의 모든 것을 삭제할까요?",
    ["That is the last bar — there has to be one."] = "마지막 바입니다 — 하나는 남아 있어야 합니다.",
    ["Drag to reorder bars"] = "끌어서 바 순서 바꾸기",
    ["Rename this bar"] = "이 바 이름 바꾸기",
    ["Delete this bar"] = "이 바 삭제",
    ["Duplicate bar"] = "바 복제",
    ["Copies the selected bar with all entries and layout settings."] = "선택한 바를 모든 항목과 배치 설정과 함께 복사합니다.",
    ["Bar layout"] = "바 배치",
    ["Icon appearance"] = "아이콘 모양",
    ["Icon display"] = "아이콘 표시",
    ["Movable cooldown bars grouped however you like — procs, defensives, offensives, each with its own look and position."] = "원하는 대로 묶을 수 있는 이동 가능한 재사용 대기시간 바입니다 — 발동 효과, 방어 기술, 공격 기술을 각각 고유한 모양과 위치로 배치할 수 있습니다.",
    ["Which IDs should be shown in tooltips? Some types do not exist on this game version and are ignored (e.g. TraitNodeID, SourceID)."] = "툴팁에 어떤 ID를 표시할지 선택합니다. 일부 종류는 이 게임 버전에 존재하지 않아 무시됩니다 (예: TraitNodeID, SourceID).",
    ["CDM Bars"] = "CDM 바",
    ["Bug Fixes"] = "버그 수정",
    ["Bar Glows"] = "바 발광",
    ["Click to edit this icon's glow."] = "클릭하면 이 아이콘의 발광을 편집합니다.",
    ["Click an icon to edit its glow."] = "아이콘을 클릭하면 발광을 편집합니다.",
    ["Nothing in this bar yet. Add a spell or trinket on the CDM Bars tab first."] = "이 바에는 아직 아무것도 없습니다. 먼저 CDM 바 탭에서 주문이나 장신구를 추가하십시오.",
    ["|cffaaaaaaEach icon can glow while a buff of yours is active — or missing. Click an icon in the preview above, then add one or more watchers; the first whose condition holds paints the icon.|r"] = "|cffaaaaaa각 아이콘은 자신의 강화 효과가 활성일 때 — 또는 없을 때 빛날 수 있습니다. 위 미리 보기에서 아이콘을 클릭한 뒤 감시자를 하나 이상 추가하십시오. 조건이 충족되는 첫 감시자가 아이콘을 칠합니다.|r",
    ["|cff888888No icon picked yet.|r"] = "|cff888888아직 선택한 아이콘이 없습니다.|r",
    ["Glows: %s"] = "발광: %s",
    ["Glow when"] = "발광 조건",
    ["Buff is active"] = "강화 효과가 활성일 때",
    ["Buff is missing"] = "강화 효과가 없을 때",
    ["Action button glow"] = "행동 단축바 발광",
    ["Pulsing fill"] = "맥동 채우기",
    ["Gold (default)"] = "금색 (기본)",
    ["Pick color..."] = "색상 선택...",
    ["Remove this glow"] = "이 발광 제거",
    ["Watches: %s"] = "감시 대상: %s",
    ["Add watcher (buff name / ID)"] = "감시자 추가 (주문 이름 / ID)",
    ["|cffaaaaaaNo watcher yet. Most spells put a buff of the same name on you when used — one click below makes this icon glow while that buff is on you. Or type any other buff into the field.|r"] = "|cffaaaaaa아직 감시자가 없습니다. 대부분의 주문은 사용 시 같은 이름의 강화 효과를 겁니다 — 아래를 한 번 클릭하면 그 강화 효과가 유지되는 동안 이 아이콘이 빛납니다. 다른 강화 효과를 입력란에 적어도 됩니다.|r",
    ["Glow while '%s' is on me"] = "'%s'가 걸려 있는 동안 발광",
    -- Patch notes 1.44.0
    ["Icon Strip – Racial, trinket and the diminishing-returns row share one edge of the frame in a fixed order, with one set of controls — they can no longer land on top of each other"] = "아이콘 줄 – 종족 특성, 장신구, 효과 감소 줄이 프레임의 한쪽 가장자리를 정해진 순서로 나눠 쓰고 설정도 한 벌입니다 — 더 이상 서로 겹치지 않습니다",
    ["The frame layout — order, spacing, grow direction — never actually applied: its hooks were installed before the arena interface had loaded. The frames now report their own moves and the layout follows; during a fight they are protected, so a move mid-round is corrected when it ends."] = "투기장 프레임의 배치 — 순서, 간격, 확장 방향 — 는 실제로 적용된 적이 없었습니다. 훅이 투기장 인터페이스가 로드되기 전에 설치됐기 때문입니다. 이제 프레임이 자신의 이동을 직접 알리고 배치가 뒤따릅니다. 전투 중에는 보호되므로, 라운드 중의 이동은 전투가 끝나면 바로잡힙니다.",
    ["The default gap between frames clears the opponent's pet bar, and the drag box in edit mode covers the whole stack instead of a fixed area."] = "프레임 사이의 기본 간격이 상대 소환수 바 자리를 비워 두고, 편집 모드의 드래그 상자는 고정 영역 대신 전체 묶음을 덮습니다.",
    ["Bar Glows – Any icon can glow while a buff of yours is active or missing: three styles, gold, class or custom color, and one click watches the spell's own buff"] = "바 발광 – 어떤 아이콘이든 자신의 강화 효과가 활성이거나 없는 동안 빛날 수 있습니다: 세 가지 스타일, 금색, 직업 색 또는 사용자 지정 색, 그리고 한 번의 클릭으로 주문 자신의 강화 효과를 감시합니다",
    ["The page is built around a preview that stays put while you scroll: the bar picker with rename, delete and drag-to-reorder on top, under it every icon of the bar at its real size and shape with the real cooldown sweep. Drag reorders, right-click removes."] = "이 페이지는 스크롤해도 제자리에 있는 미리 보기를 중심으로 만들어졌습니다. 위에는 이름 바꾸기, 삭제, 끌어서 재정렬이 되는 바 선택기가, 아래에는 바의 모든 아이콘이 실제 크기와 모양, 실제 재사용 대기시간 회전과 함께 놓입니다. 끌면 재정렬되고 오른쪽 클릭으로 제거합니다.",
    ["The page is split into tabs, and the resource bar moved in as one of them. Spells you add belong to the class that added them and no longer show up on your other characters."] = "페이지가 탭으로 나뉘었고, 자원 바가 그중 하나로 들어왔습니다. 추가한 주문은 추가한 직업의 것이 되어 다른 캐릭터에는 더 이상 나타나지 않습니다.",
    ["The third extra-item slot no longer stretches across the page with its box flung to the far edge."] = "세 번째 추가 아이템 칸이 입력란을 가장자리로 내던진 채 페이지 전체로 늘어나지 않습니다.",
    ["The interface no longer compares itself with the other game version anywhere; a check keeps such wording out for good."] = "인터페이스가 더 이상 어디에서도 다른 게임 버전과 자신을 비교하지 않으며, 검사가 그런 표현을 계속 막습니다.",
    ["Modules with several pages show them as a tab row along the top; when the tabs outgrow the row, two arrows page through it instead of wrapping into a second line."] = "여러 페이지가 있는 모듈은 이를 상단의 탭 줄로 보여 줍니다. 탭이 줄을 넘치면 둘째 줄로 꺾이는 대신 화살표 두 개로 넘겨 봅니다.",
    ["The sidebar got shorter: player and target frames, font bars, castbar and cooldown pulse are one entry now, and a new General entry under Reminders collects the former Extras, Character and Bug Fixes rows — the bug fixes as a single tab."] = "사이드바가 짧아졌습니다. 플레이어·대상 프레임, 글꼴 바, 시전 바, 재사용 대기시간 펄스가 이제 하나의 항목이고, 알림 아래의 새 일반 항목이 예전의 기타, 캐릭터, 버그 수정 줄을 모읍니다 — 버그 수정은 단 하나의 탭으로.",
    ["Typing into an add field and then clicking the button beside it silently did nothing; the typed text only counted after pressing Enter. Buttons now take the field's text with them."] = "추가 입력란에 입력한 뒤 옆의 버튼을 눌러도 아무 일도 없이 조용했습니다. 입력한 텍스트는 Enter를 눌러야만 인정됐습니다. 이제 버튼이 입력란의 텍스트를 함께 가져갑니다.",
    ["Developer"] = "개발자",
    ["Suppress Lua Errors"] = "Lua 오류 숨기기",
    ["Hides the game's own Lua error popup (CVar scriptErrors). Errors still happen and error-collecting addons still see them - they just stop interrupting you."] = "게임 자체의 Lua 오류 창을 숨깁니다(CVar scriptErrors). 오류는 계속 발생하고 오류 수집 애드온도 여전히 볼 수 있으며, 단지 더 이상 방해하지 않을 뿐입니다.",
    ["Show IDs in Tooltips"] = "툴팁에 ID 표시",
    ["Shows spell, item, NPC and other IDs in tooltips. Which ID types appear can be fine-tuned on the Tooltip IDs page in the Extras group."] = "주문, 아이템, NPC 등의 ID를 툴팁에 표시합니다. 표시할 ID 종류는 기타 그룹의 툴팁 ID 페이지에서 조정할 수 있습니다.",
    ["Reset All Settings"] = "모든 설정 초기화",
    ["Optimize My FPS and Graphics"] = "내 FPS와 그래픽 최적화",
    ["Applies a proven set of graphics settings that noticeably raises FPS while keeping the game looking good - shadows, liquids, ambient occlusion and view distance go down, textures and spell effects stay sharp. Your current values are saved first and the restore button brings them back. Only settings this client knows are touched."] = "검증된 그래픽 설정 모음을 적용해 보기 좋은 화면을 유지하면서 FPS를 크게 올립니다. 그림자, 액체, 주변광 차폐, 시야 거리는 낮아지고 텍스처와 주문 효과는 선명하게 유지됩니다. 현재 값은 먼저 저장되며 복원 버튼으로 언제든 되돌릴 수 있습니다. 이 클라이언트가 아는 설정만 변경합니다.",
    ["Restore My Graphics Settings"] = "내 그래픽 설정 복원",
    ["Returns every graphics setting the optimize button changed to its previous value and removes the backup."] = "최적화 버튼이 변경한 모든 그래픽 설정을 이전 값으로 되돌리고 백업을 제거합니다.",
    ["Graphics optimized: %d settings applied."] = "그래픽 최적화 완료: 설정 %d개 적용.",
    ["Graphics settings restored."] = "그래픽 설정을 복원했습니다.",
    ["Fonts & Colors"] = "글꼴 및 색상",
    ["Global Font"] = "전역 글꼴",
    ["The font for the whole VuloClassicUI interface. Fonts shared by other addons appear here too.\n\n|cffaaaaaaRequires /reload to apply everywhere.|r"] = "VuloClassicUI 인터페이스 전체의 글꼴입니다. 다른 애드온이 공유하는 글꼴도 여기에 표시됩니다.\n\n|cffaaaaaa어디에나 적용하려면 /reload 가 필요합니다.|r",
    ["Outline Mode"] = "외곽선 모드",
    ["Default outline for VuloClassicUI text. Elements with their own outline setting keep it.\n\n|cffaaaaaaRequires /reload to apply everywhere.|r"] = "VuloClassicUI 텍스트의 기본 외곽선입니다. 자체 외곽선 설정이 있는 요소는 그대로 유지됩니다.\n\n|cffaaaaaa어디에나 적용하려면 /reload 가 필요합니다.|r",
    ["Apply to All Game Texts"] = "모든 게임 텍스트에 적용",
    ["Replaces the font of the game's own texts (chat, tooltips, quest log and more) with the global font.\n\n|cffaaaaaaTurning it off requires /reload to restore the original fonts.|r"] = "게임 자체 텍스트(대화, 툴팁, 퀘스트 기록 등)의 글꼴을 전역 글꼴로 바꿉니다.\n\n|cffaaaaaa끌 때는 원래 글꼴을 되돌리기 위해 /reload 가 필요합니다.|r",
    ["Class Colors"] = "직업 색상",
    ["Resource Colors"] = "자원 색상",
    ["Font changed. /reload required to apply it everywhere."] = "글꼴이 변경되었습니다. 어디에나 적용하려면 /reload 가 필요합니다.",
    ["Reset to default"] = "기본값으로 초기화",
    ["Rename..."] = "이름 바꾸기...",
    ["Rename loadout '%s'. Enter new name:"] = "장비 세트 ‘%s’의 이름을 바꿉니다. 새 이름:",
    ["A loadout named '%s' already exists."] = "‘%s’(이)라는 장비 세트가 이미 있습니다.",
    ["Loadout '%s' renamed to '%s'."] = "장비 세트 ‘%s’의 이름을 ‘%s’(으)로 바꿨습니다.",
    -- Patch notes 1.45.0
    ["The item level on equipment links sits after the link now, not inside its brackets. Some clients re-check link text against their own data, and the changed text turned the link into the name of whatever quest carried that number."] = "장비 링크의 아이템 레벨이 이제 괄호 안이 아니라 링크 뒤에 붙습니다. 일부 클라이언트는 링크 텍스트를 자체 데이터와 다시 대조하는데, 바뀐 텍스트 때문에 링크가 그 번호의 퀘스트 이름으로 바뀌었습니다.",
    ["A spell no longer shows up on another class just because that class owns a different spell with the same name. Entries respect their class stamp on the bars, and old entries are adopted by spell ID instead of by name."] = "다른 직업이 같은 이름의 다른 주문을 가지고 있다는 이유만으로 주문이 그 직업에 나타나지 않습니다. 항목은 막대에서 직업 표시를 따르며, 오래된 항목은 이름 대신 주문 ID로 귀속됩니다.",
    ["The bundled media library silently dropped font registrations when no other addon shipped a newer copy of it; the addon font now registers on every install."] = "포함된 미디어 라이브러리가 다른 애드온이 더 새 복사본을 제공하지 않으면 글꼴 등록을 조용히 버렸습니다. 이제 애드온 글꼴은 모든 설치에서 등록됩니다.",
    ["Rename... – In the set's right-click menu and on the sets page; icon, contents and talent binding move along with the name"] = "이름 바꾸기... – 세트의 우클릭 메뉴와 세트 페이지에서; 아이콘, 구성, 전문화 연결이 이름과 함께 이동합니다",
    ["Optimize My FPS and Graphics – A proven set of graphics settings with a one-time backup; the restore button next to it brings your old values back"] = "내 FPS와 그래픽 최적화 – 검증된 그래픽 설정 모음을 한 번의 백업과 함께 적용; 옆의 복원 버튼이 이전 값을 되돌립니다",
    ["Fonts & Colors – A new tab: global font with outline mode, optionally for all game texts, plus class and resource colors with a reset on every row"] = "글꼴 및 색상 – 새 탭: 외곽선 모드를 갖춘 전역 글꼴(원하면 모든 게임 텍스트에), 그리고 줄마다 초기화가 있는 직업 및 자원 색상",
    ["Developer – Suppress Lua errors, switch tooltip IDs and reset all settings from a new section on the General tab"] = "개발자 – Lua 오류 숨기기, 툴팁 ID 전환, 모든 설정 초기화를 일반 탭의 새 구역에서",
    ["The General tab is organised in sections on a two-column grid like the rest of the window. The new tab ships a texture file: restart the client once after updating, a /reload alone will not show the reset arrows."] = "일반 탭이 창의 나머지처럼 두 열 격자 위 구역으로 정리되었습니다. 새 탭에는 텍스처 파일이 들어 있습니다. 업데이트 후 클라이언트를 한 번 재시작하세요. /reload 만으로는 초기화 화살표가 보이지 않습니다.",
    ["The enlargement stays off on Wrath-based clients (Titan Reforged): their quest log is already the wide two-pane frame, and enlarging it pushed the detail pane into the button row."] = "리치 왕 기반 클라이언트(Titan Reforged)에서는 확대가 꺼진 채로 유지됩니다. 그곳의 퀘스트 기록은 이미 넓은 두 패널 창이고, 확대하면 상세 패널이 버튼 줄로 밀려 들어갔습니다.",
    ["Long dropdown lists open upwards when there is no room below. They used to run off the bottom edge of the screen, where the last entries could never be scrolled into view."] = "긴 드롭다운 목록은 아래에 공간이 없으면 위로 열립니다. 지금까지는 화면 아래 가장자리를 넘어가, 마지막 항목을 끝내 볼 수 없었습니다.",
    ["On"] = "켜기",
    ["Select all"] = "모두 선택",
    ["Deselect all"] = "모두 선택 해제",
    ["Interface layout (window positions and links)"] = "인터페이스 배치(창 위치와 연결)",
    ["Fonts & colors (account-wide)"] = "글꼴 및 색상(계정 전체)",
    ["Also carries your account-wide font and color settings; they apply immediately when the string is imported."] = "계정 전체에 적용되는 글꼴·색상 설정도 함께 담습니다. 문자열을 가져오는 즉시 적용됩니다.",
    ["|cffaaaaaaThe export will include %d of %d modules.|r"] = "|cffaaaaaa내보내기에 모듈 %d/%d개가 포함됩니다.|r",
    ["Nothing selected to export."] = "내보낼 항목이 선택되지 않았습니다.",
    ["|cffaaaaaaUntick modules to share only a part - a partial string merges onto the importer's active profile.|r"] = "|cffaaaaaa모듈 선택을 해제하면 일부만 공유할 수 있습니다. 부분 문자열은 가져오는 쪽의 활성 프로필에 병합됩니다.|r",
    ["Standard Action Bars"] = "표준 행동 단축바",
    ["Modern"] = "모던",
    ["|cffaaaaaaThe game's own action bars stay in place. Frame style and Dark Mode below come from the Dark Skin module and style Blizzard's buttons directly.|r"] = "|cffaaaaaa게임 자체의 행동 단축바가 그대로 유지됩니다. 아래의 테두리 스타일과 다크 모드는 Dark Skin 모듈에서 오며 블리자드 버튼을 직접 꾸밉니다.|r",
    ["Apply layout to all bars"] = "배치를 모든 단축바에 적용",
    ["Copies this bar's layout - scale, icon size, buttons per row, spacing, direction - to every other bar."] = "이 단축바의 배치(크기, 아이콘 크기, 줄당 버튼 수, 간격, 방향)를 다른 모든 단축바에 복사합니다.",
    ["Layout applied to all bars."] = "배치를 모든 단축바에 적용했습니다.",
    ["Text sizes"] = "텍스트 크기",
    ["Bar Display"] = "단축바 표시",
    ["Menu, Bags & XP Bar"] = "메뉴·가방·경험치 바",
    ["|cffaaaaaaOnly active in Modern mode (Bar Display tab).|r"] = "|cffaaaaaa모던 모드에서만 작동합니다(단축바 표시 탭).|r",
    ["Click: layout settings. Right-click: text sizes."] = "클릭: 배치 설정. 우클릭: 텍스트 크기.",
    ["Bar Animations"] = "단축바 애니메이션",
    ["Tint the pressed state"] = "누름 상태 색칠",
    ["Colours the flash a button shows while it is pressed down."] = "버튼을 누르는 동안 나타나는 섬광에 색을 입힙니다.",
    ["Tint the hover highlight"] = "마우스 오버 강조 색칠",
    ["Colours the glow a button shows under the mouse."] = "마우스 아래에서 버튼이 보여주는 광채에 색을 입힙니다.",
    ["Use class colour"] = "직업 색상 사용",
    ["Enable bar background"] = "단축바 배경 켜기",
    ["A flat colour panel behind the bar, sized with it."] = "단축바 뒤의 단색 패널로, 크기가 함께 조절됩니다.",
    ["Padding"] = "여백",
    ["Flat (default)"] = "단색(기본)",
    ["Core"] = "기본",
    ["Opacity"] = "불투명도",
    ["Durability"] = "내구도",
    ["Talent points"] = "특성 점수",
    ["Pulse"] = "맥동",
    ["Steady"] = "지속",
    ["Background"] = "배경",
    ["Low"] = "낮음",
    ["Medium"] = "중간",
    ["High"] = "높음",
    ["Dialog"] = "대화 상자",
    ["Click an icon to jump to its settings."] = "아이콘을 클릭하면 해당 설정으로 이동합니다.",
    ["Middle-click: hide until the next loading screen."] = "가운데 클릭: 다음 로딩 화면까지 숨깁니다.",
    ["Nothing to preview: every reminder is switched off."] = "미리 볼 항목이 없습니다. 모든 알림이 꺼져 있습니다.",
    ["Show effects missing on others"] = "다른 사람에게 없는 효과 표시",
    ["Scans your party or raid for class buffs you could cast and reminds you when someone lacks one."] = "시전할 수 있는 직업 버프를 파티나 공격대에서 확인하고, 누군가에게 없으면 알려줍니다.",
    ["Missing on %s: %s"] = "%s에게 없음: %s",
    ["In raids (minutes)"] = "공격대에서(분)",
    ["In dungeons (minutes)"] = "던전에서(분)",
    ["0 uses the global warn threshold."] = "0은 전역 경고 기준을 사용합니다.",
    ["Preferred food"] = "선호 음식",
    ["Preferred flask or elixir"] = "선호 숙이나 비약",
    ["Preferred weapon enhancement"] = "선호 무기 강화",
    ["Automatic (best in bags)"] = "자동(가방 안 최상의 것)",
    ["Click to use."] = "클릭하면 사용합니다.",
    ["Attach reminders to the cursor"] = "알림을 커서에 부착",
    ["Shows small copies of the current reminders next to the mouse cursor."] = "현재 알림의 작은 복사본을 마우스 커서 옆에 표시합니다.",
    ["Helpers"] = "도우미",
    ["Queue countdown, buff minigame helper and class trainer book in one place."] = "대기열 카운트다운, 버프 미니게임 도우미, 훈련사 책을 한곳에 모았습니다.",
    ["Open group board"] = "파티 게시판 열기",
    ["Scans chat for people forming groups and lists them by Classic/TBC instance in a window (/vlfg or the button below)."] = "파티를 모집하는 사람들을 대화에서 찾아 Classic/TBC 인스턴스별로 창에 표시합니다(/vlfg 또는 아래 버튼).",
    ["Show minimap button"] = "미니맵 버튼 표시",
    ["PvP Settings"] = "PvP 설정",
    ["Fullscreen"] = "전체 화면",
    ["Fullscreen dialog"] = "전체 화면 대화 상자",
    ["Tooltip"] = "툴팁",
    ["Orientation"] = "방향",
    ["Horizontal"] = "가로",
    ["Vertical (up)"] = "세로(위로)",
    ["Vertical (down)"] = "세로(아래로)",
    ["Fill opacity"] = "채움 불투명도",
    ["Below 100 the world shows through the filled part of the bar."] = "100 미만이면 막대의 채워진 부분으로 게임 화면이 비칩니다.",
    ["The fill fades into a second colour towards its end."] = "채워진 부분이 끝으로 갈수록 두 번째 색상으로 서서히 바뀝니다.",
    ["Name inside the bar"] = "막대 안에 이름 표시",
    ["Anchors the name at the left edge inside the health bar instead of above it — the right edge stays free for the health text."] = "이름을 생명력 막대 위가 아니라 막대 안 왼쪽 가장자리에 고정합니다. 오른쪽은 생명력 텍스트를 위해 비워둡니다.",
    ["Show plates for enemy pets"] = "적 소환수 이름표 표시",
    ["Divider line on the target's bar"] = "대상 막대의 구분선",
    ["Draws a thin vertical line at the given percent of the health bar — an execute marker."] = "생명력 막대의 지정 퍼센트 위치에 가는 세로선을 그립니다 — 처형 기준선입니다.",
    ["Line position (%)"] = "선 위치(%)",
    ["Only on your target"] = "내 대상에만",
    ["Spell name"] = "주문 이름",
    ["Colour the last tick"] = "마지막 틱 색상 적용",
    ["Show latency text"] = "지연 시간 텍스트 표시",
    ["Vertical"] = "세로",
    ["Automatic stacks a side slot as a column and a top or bottom slot as a row."] = "자동은 측면 슬롯을 세로 열로, 위/아래 슬롯을 가로 줄로 쌓습니다.",
    ["Show older versions"] = "이전 버전 보기",
    ["%d broken numeric values were removed from the settings so they can be saved again."] = "손상된 숫자 값 %d개를 설정에서 제거하여 다시 저장할 수 있습니다.",
    ["Widen window"] = "창 넓히기",
    ["Extra width for the friends window so long names, notes and zones fit on one line. 0 keeps Blizzard's width."] = "친구 창의 추가 너비로, 긴 이름과 메모, 지역이 한 줄에 들어갑니다. 0이면 Blizzard 기본 너비를 유지합니다.",
    ["Classic+ keeps Blizzard's layout with extras. Modern adds the dark chrome and moves all stats into a panel on the right of the character window."] = "Classic+는 Blizzard 배치에 기능을 더합니다. Modern은 어두운 테두리를 입히고 모든 능력치를 캐릭터 창 오른쪽 패널로 옮깁니다.",
    ["Overrides the group switch for this entry alone - e.g. to track a buff someone else casts on you."] = "이 항목만 그룹 전환 설정을 무시합니다 - 예: 다른 사람이 나에게 시전한 버프를 추적할 때.",
    ["Group default"] = "그룹 기본값",
    ["Anyone's"] = "누구나",
    ["Use conditions"] = "조건 사용",
    ["Unticked parks this entry: it keeps its settings but never shows. The gear holds moving, removing and per-entry settings."] = "체크를 해제하면 이 항목이 보관됩니다: 설정은 유지되지만 표시되지 않습니다. 톱니바퀴에 이동, 제거, 항목별 설정이 있습니다.",
    ["Talent Window"] = "특성 창",
    ["Shows all three talent trees side by side in one window."] = "세 개의 특성 트리를 한 창에 나란히 표시합니다.",
    ["Points left: %d"] = "남은 점수: %d",
    ["TALENTS"] = "특성",
    ["Open Blizzard's talent window"] = "Blizzard 특성 창 열기",
    ["For glyphs and everything this window does not cover."] = "문양 등 이 창이 다루지 않는 모든 기능용입니다.",
    ["|cffaaaaaaAll three talent trees side by side, with live ranks and click-to-learn. Glyphs stay in Blizzard's window, one button away.|r"] = "|cffaaaaaa세 특성 트리를 나란히 보여 주며, 실시간 등급과 클릭해서 배우기를 지원합니다. 문양은 버튼 하나로 여는 Blizzard 창에 남습니다.|r",
    ["Replace Blizzard's talent window"] = "Blizzard 특성 창 대체",
    ["Opening talents shows this window instead. Turn it off to get Blizzard's one-tree window back."] = "특성을 열면 이 창이 대신 표시됩니다. 끄면 Blizzard의 단일 트리 창으로 돌아갑니다.",
    ["Open talent window"] = "특성 창 열기",
    ["See-through"] = "투명",
    ["Hide the box fill and labels while editing, so you can see the interface you are aligning. The thin borders stay."] = "편집 중 상자의 채우기와 이름표를 숨겨 정렬 중인 인터페이스가 보이게 합니다. 얇은 테두리는 유지됩니다.",
    -- Patch notes 1.46.0
    ["Options"] = "옵션",
    ["Talents"] = "특성",
    ["The page opens with two modes: Standard keeps Blizzard's bars with the skin rows, Modern runs the addon's own bars with a live preview, a per-bar background, button press and hover tints and an XP bar texture"] = "페이지가 두 가지 모드로 열립니다: 표준은 Blizzard 액션바와 스킨 행을 유지하고, 모던은 애드온 자체 액션바를 실시간 미리보기, 바별 배경, 버튼 누름·마우스오버 색조, 경험치 바 텍스처와 함께 사용합니다",
    ["Modern – Third player cast bar style: flat look with name and timer on the bar, plus bar texture, border, a coloured last tick and a latency readout"] = "모던 – 플레이어 시전 바의 세 번째 스타일: 이름과 시간이 바 위에 표시되는 평면 디자인, 바 텍스처, 테두리, 색이 지정된 마지막 틱과 지연 시간 표시",
    ["The options page carries a live preview; clicking its icon or bar jumps to the matching section"] = "옵션 페이지에 실시간 미리보기가 있습니다. 아이콘이나 바를 클릭하면 해당 설정 구역으로 이동합니다",
    ["Enchant and gem displays no longer displace each other on non-English clients, and Chinese enchant text is no longer cut mid-character"] = "영어가 아닌 클라이언트에서 마법부여와 보석 표시가 더 이상 서로를 밀어내지 않으며, 중국어 마법부여 텍스트가 글자 중간에서 잘리지 않습니다",
    ["Tracked entries sit two per row, each with a gear: park an entry without deleting it, move or remove it, set conditions, and override Only what I cast myself for that entry alone"] = "추적 항목이 한 줄에 두 개씩 표시되고 항목마다 톱니바퀴가 있습니다: 삭제하지 않고 보관하거나, 옮기거나 제거하고, 조건을 정하고, 내가 직접 건 것만을 그 항목에만 따로 지정할 수 있습니다",
    ["See-through – Hides the box fill and labels while editing, so you can see the interface you are aligning"] = "투명 – 편집 중 상자의 채우기와 이름표를 숨겨 정렬 중인 인터페이스가 보이게 합니다",
    ["Coordinates appear on the box while dragging or nudging, and the window being snapped to pulses white"] = "끌거나 미세 이동하는 동안 좌표가 상자에 표시되고, 스냅 대상 창이 흰색으로 깜박입니다",
    ["The loot window can be moved on Wrath clients"] = "리치 왕의 분노 클라이언트에서 전리품 창을 옮길 수 있습니다",
    ["Widen window – Extra width so long names, notes and zones fit on one line"] = "창 넓히기 – 추가 너비로 긴 이름, 메모, 지역이 한 줄에 들어갑니다",
    ["The close glyph of every window is larger now"] = "모든 창의 닫기 기호가 더 커졌습니다",
    ["Three tabs with a pinned live preview, a name-in-bar option and thousands separators on health numbers"] = "고정된 실시간 미리보기가 있는 세 개의 탭, 이름을 생명력 바 안에 넣는 옵션, 생명력 숫자의 천 단위 구분 기호",
    ["Gear rows open inside their own column, aura rows align per row, helper tools share one tab, and the pinned page header of the last visited tab is cleared on switching"] = "톱니바퀴 행이 자신의 열 안에서 펼쳐지고, 오라 행은 행 단위로 정렬되며, 도우미 도구는 한 탭을 공유하고, 마지막으로 방문한 탭의 고정 머리글은 전환 시 정리됩니다",
    ["Only the last five versions build at once; a button loads the older ones"] = "한 번에 최근 다섯 개 버전만 표시하고, 버튼으로 이전 버전을 불러옵니다",
    ["Orientation, fill opacity, frame strata and a live preview on the options page"] = "방향, 채우기 투명도, 프레임 층 설정과 옵션 페이지의 실시간 미리보기",
    ["A profile string can carry a selection: chosen modules, the window layout, talent overrides, and the account-wide fonts and colours"] = "프로필 문자열에 선택 항목만 담을 수 있습니다: 선택한 모듈, 창 배치, 특성별 재정의, 계정 전체의 글꼴과 색상",
    ["Per-rule switches with class-coloured names, a group scan for missing buffs, preferred food, flask and weapon oil, raid and dungeon thresholds, glow styles, scale and a live preview; middle-click hides a reminder until the next loading screen"] = "규칙별 스위치와 직업 색상 이름, 파티의 누락된 버프 검사, 선호 음식·플라스크·무기 기름, 공격대와 던전 기준값, 발광 스타일, 크기 조절, 실시간 미리보기를 제공합니다. 가운데 클릭은 다음 로딩 화면까지 알림을 숨깁니다",
    ["Broken numeric values are removed before saving and reported at the next login. A single such value used to reset every setting of the account to defaults"] = "손상된 숫자 값은 저장 전에 제거되고 다음 로그인 때 보고됩니다. 이런 값 하나가 계정의 모든 설정을 기본값으로 되돌리곤 했습니다",
    ["Totemic Recall stands as its own button after the elements on Wrath clients"] = "리치 왕의 분노 클라이언트에서 토템 회수가 원소 뒤의 독립 버튼으로 표시됩니다",
    ["Talent Window – All three talent trees side by side with live ranks and click-to-learn on Wrath clients; glyphs stay one button away"] = "특성 창 – 리치 왕의 분노 클라이언트에서 세 특성 트리를 나란히 표시하고, 실시간 랭크와 클릭 배우기를 지원합니다. 문양은 버튼 하나로 열 수 있습니다",
    ["The string is selected - press Ctrl+C to copy it."] = "문자열이 선택되어 있습니다. Ctrl+C로 복사하세요.",
    ["%d characters"] = "%d자",
    ["Paste the string here with Ctrl+V."] = "여기에 Ctrl+V로 문자열을 붙여넣으세요.",
    ["String captured - %d characters."] = "문자열을 읽었습니다 - %d자.",
    ["Partial string: anything missing is taken from your active profile."] = "부분 문자열: 없는 부분은 현재 활성 프로필에서 가져옵니다.",
    ["Unticked parts keep your current settings."] = "선택 해제한 부분은 현재 설정을 유지합니다.",
    ["Profile '%s' imported. Switch to it now and reload the UI?"] = "'%s' 프로필을 가져왔습니다. 지금 전환하고 UI를 다시 불러올까요?",
    ["Switch and reload"] = "전환 후 다시 불러오기",
    ["Save a backup copy"] = "백업 사본 저장",
    ["Creates a dated copy of the active profile as a restore point. Nothing switches - the copy just sits in the profile list."] = "활성 프로필의 날짜가 표시된 사본을 복원 지점으로 만듭니다. 아무것도 전환되지 않으며, 사본은 프로필 목록에 남아 있을 뿐입니다.",
    ["Backup '%s' created."] = "백업 '%s'을(를) 만들었습니다.",
    ["Go back"] = "뒤로",
    ["Pixel-true plate size"] = "픽셀 단위 이름표 크기",
    ["Sizes the plates in screen pixels instead of interface units: height 27 is then 27 pixels on any monitor and UI scale."] = "이름표 크기를 인터페이스 단위 대신 화면 픽셀로 지정합니다. 높이 27은 어떤 모니터와 UI 배율에서도 27픽셀이 됩니다.",
    -- Patch notes 1.47.0
    ["The boxes now cover their window exactly, in the same dark look as the rest of the interface, with the name centred and shown in orange when the window is docked to another one"] = "상자가 이제 해당 창을 정확히 덮습니다. 인터페이스의 나머지와 같은 어두운 스타일이며, 이름은 가운데에 표시되고 창이 다른 창에 고정되어 있으면 주황색으로 나타납니다",
    ["Outside the editor the small drag handle stays, so an unlocked cooldown bar still accepts dropped spells and test previews stay visible"] = "편집기 밖에서는 작은 손잡이 상자가 유지되어, 잠금 해제된 재사용 대기시간 막대가 계속 주문을 받아들이고 테스트 미리보기도 계속 보입니다",
    ["The cloak equipment slot was translated with the navigation word for back in six languages and now reads correctly everywhere"] = "망토 장비 칸이 여섯 개 언어에서 탐색용 단어인 뒤로로 번역되어 있었으며 이제 모든 언어에서 올바르게 표시됩니다",
    ["Pixel-true plate size – Sizes the plates in screen pixels, so height 27 is 27 pixels on any monitor and interface scale"] = "픽셀 단위 이름표 크기 – 이름표 크기를 화면 픽셀로 지정하여, 높이 27이 어떤 모니터와 인터페이스 배율에서도 27픽셀이 됩니다",
    ["Plate sizes now mean exactly what the sliders say: the game no longer secretly enlarges the target's plate or shrinks distant ones, and the live preview matches the game — making the target larger is now solely the job of the target plate scale option"] = "이름표 크기가 이제 슬라이더에 적힌 그대로입니다. 게임이 대상의 이름표를 몰래 키우거나 먼 이름표를 줄이지 않으며, 실시간 미리보기가 게임과 일치합니다. 대상을 크게 표시하는 일은 이제 대상 이름표 배율 옵션만의 몫입니다",
    ["Save a backup copy – One click keeps a dated copy of the active profile as a restore point"] = "백업 사본 저장 – 클릭 한 번으로 활성 프로필의 날짜가 표시된 사본을 복원 지점으로 보관합니다",
    ["Exporting opens a proper window with the string already selected, and importing shows a preview first: rename the profile and untick the parts you do not want before anything is written"] = "내보내기는 문자열이 미리 선택된 제대로 된 창을 열고, 가져오기는 먼저 미리보기를 보여 줍니다. 무엇이든 기록되기 전에 프로필 이름을 바꾸고 원하지 않는 부분을 선택 해제할 수 있습니다",
    ["Export strings are compressed to a fraction of their old length and fit in a chat message; strings from older versions still import"] = "내보내기 문자열이 압축되어 이전 길이의 몇 분의 일이 되었고 채팅 메시지에 들어갑니다. 이전 버전의 문자열도 계속 가져올 수 있습니다",
    ["On the Wrath client the talent tooltip showed a placeholder instead of the description, and the talent key would open the window but not close it — both fixed"] = "리치 왕 클라이언트에서 특성 툴팁이 설명 대신 자리 표시자를 보여 주었고, 특성 단축키가 창을 열기만 하고 닫지는 못했습니다. 둘 다 고쳤습니다",
    ["%s Locked"] = "%s 잠김",
    ["|cffffffffLOSS OF CONTROL|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffff제어 상실|r\n|cffaaaaaa드래그 또는 방향키|r",
    ["%.1f seconds"] = "%.1f초",
    ["Loss of control mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Press the button again to finish."] = "제어 상실 이동 모드가 켜졌습니다. |cff9b6cff보라색 상자를 끌거나|r |cff9b6cff방향키|r를 사용하세요 (SHIFT = 5픽셀). 끝내려면 버튼을 다시 누르세요.",
    ["Preview"] = "미리 보기",
    ["Loss of Control"] = "제어 상실",
    ["Shows what is controlling you right now -- stun, fear, root, silence, disarm or a school lockout -- with the effect icon, its name and the time left. Where two effects run at once the one that matters is shown large, and the next one as a small icon beside it."] = "지금 자신을 제어하고 있는 효과를 보여줍니다. 기절, 공포, 속박, 침묵, 무장 해제, 계열 봉인 등을 효과 아이콘과 이름, 남은 시간과 함께 표시합니다. 두 효과가 동시에 걸린 경우 더 중요한 쪽이 크게 표시되고 다음 효과는 옆에 작은 아이콘으로 표시됩니다.",
    ["Show loss of control alert"] = "제어 상실 알림 표시",
    ["Show in"] = "표시 위치",
    ["Arena and battlegrounds"] = "투기장 및 전장",
    ["Arena only"] = "투기장에서만",
    ["Name font size"] = "이름 글꼴 크기",
    ["Timer font size"] = "남은 시간 글꼴 크기",
    ["Background and red lines"] = "배경과 빨간 선",
    ["Show the next effect"] = "다음 효과 표시",
    ["Profile changed. Use /reload when you are out of combat."] = "프로필이 변경되었습니다. 전투가 끝나면 /reload 를 사용하세요.",
    ["Profile keybind"] = "프로필 단축키",
    ["Switches to this profile outside combat and then asks to reload the UI. Override bindings are restored at login."] = "전투 중이 아닐 때 이 프로필로 전환한 다음 인터페이스를 다시 불러올지 묻습니다. 단축키는 접속할 때 복원됩니다.",
    ["Use the global font"] = "전역 글꼴 사용",
    ["Name color"] = "이름 색상",
    ["Timer color"] = "남은 시간 색상",
    ["|cffffffffINTERRUPTS|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffff차단|r\n|cffaaaaaa드래그 또는 방향키|r",
    ["Interrupt bar mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Press the button again to finish."] = "차단 바 이동 모드가 켜졌습니다. |cff9b6cff보라색 상자를 끌거나|r |cff9b6cff방향키|r를 사용하세요 (SHIFT = 5픽셀). 끝내려면 버튼을 다시 누르세요.",
    ["Interrupts"] = "차단",
    ["Watches the combat log for enemy interrupts and starts a cooldown for each one, tracked per caster -- two enemies of the same class get an icon each. The border carries the caster's class colour."] = "전투 기록에서 적의 차단 기술을 감시하여 각각의 재사용 대기시간을 시전자별로 표시합니다. 같은 직업의 적이 둘이면 아이콘도 둘입니다. 테두리는 시전자의 직업 색상을 띱니다.",
    ["Show interrupt bar"] = "차단 바 표시",
    ["Show interrupts that are still ready"] = "사용 가능한 차단 기술도 표시",
    ["Timer text on the icons"] = "아이콘에 남은 시간 표시",
    ["Cooldown swipe on the icons"] = "아이콘에 재사용 대기 효과 표시",
    ["Only take over the key while a fishing pole is worn"] = "낚싯대를 장착했을 때만 키를 사용",
    ["Without a pole in hand the key keeps whatever you bound it to, so it stays usable outside fishing. A cast already in the water keeps the key. This switches off auto-equipping a pole, which needs the key exactly while none is worn."] = "낚싯대가 없으면 키는 원래 지정한 기능을 그대로 유지하므로 낚시 외에도 계속 쓸 수 있습니다. 이미 던진 찌는 키를 계속 사용합니다. 이 설정은 낚싯대 자동 장착을 끕니다. 그 기능은 낚싯대가 없을 때 바로 그 키를 필요로 하기 때문입니다.",
    ["Stand-in for an enemy frame: the side strip is placed by the settings below."] = "적 프레임 자리표시: 옆의 아이콘 줄은 아래 설정에 따라 배치됩니다.",
    -- Patch notes 1.48.0
    ["Options Window"] = "설정 창",
    ["Loss of Control – Shows the stun, fear, root, silence or lockout holding you, with its icon, its name and the time left"] = "제어 상실 – 지금 자신을 붙잡고 있는 기절, 공포, 속박, 침묵, 계열 봉인을 아이콘과 이름, 남은 시간과 함께 보여줍니다",
    ["Interrupts – Tracks enemy interrupts from the combat log, one icon per caster, bordered in the caster's class colour"] = "차단 – 전투 기록에서 적의 차단을 추적해 시전자마다 아이콘 하나씩, 테두리는 그 직업 색상으로 표시합니다",
    ["Timer Text On The Icons – Seconds left on the interrupt icons, with their own font, outline and colour"] = "아이콘에 남은 시간 표시 – 차단 아이콘의 남은 초를 자체 글꼴, 외곽선, 색상으로 표시합니다",
    ["Cooldown Swipe On The Icons – Drop the sweeping shade and keep only the number"] = "아이콘에 재사용 대기 효과 표시 – 도는 그림자를 없애고 숫자만 남깁니다",
    ["The icon strip beside the enemy frames has a live preview on the General tab. Those frames exist only inside an arena, so its sliders used to move something you could not see."] = "적 프레임 옆의 아이콘 줄에 일반 탭에서 실시간 미리보기가 생겼습니다. 그 프레임은 투기장 안에서만 존재하므로, 지금까지는 보이지 않는 것을 조절하고 있었습니다.",
    ["An unlocked mover box no longer vanished a moment after the button put it there. The box and a running preview now ignore the zone filter: you place a bar where you are standing, and that is rarely an arena."] = "잠금 해제한 이동 상자가 버튼으로 띄운 직후 사라지지 않습니다. 상자와 진행 중인 미리보기는 이제 지역 필터를 무시합니다. 막대는 서 있는 자리에서 배치하게 되며, 그곳이 투기장인 경우는 드뭅니다.",
    ["The pinned icon strip also appears on the Layout tab, where icon size, spacing, shape and zoom read back off it while the slider moves."] = "고정된 아이콘 줄이 이제 레이아웃 탭에도 나타나며, 슬라이더를 움직이는 동안 아이콘 크기와 간격, 모양, 확대를 그 줄에서 바로 확인할 수 있습니다.",
    ["Moving Blizzard frames no longer marks every Edit Mode window as touched by this addon, which had the pet frame refused in combat. Selecting a layout caused it, and that ran on every editor entry even when nothing had been placed."] = "블리자드 창을 옮겨도 더 이상 편집 모드의 모든 창이 이 애드온이 건드린 것으로 표시되지 않습니다. 그 때문에 전투 중 소환수 프레임 표시가 거부되었습니다. 원인은 레이아웃 선택이었고, 아무것도 배치하지 않았어도 편집기에 들어갈 때마다 실행되었습니다.",
    ["The icon picker has a close button, and no longer floats over the game after the character sheet is shut."] = "아이콘 선택 창에 닫기 버튼이 생겼고, 캐릭터 창을 닫은 뒤에도 화면에 떠 있지 않습니다.",
    ["Only Take Over The Key While A Fishing Pole Is Worn – Without a pole the key keeps whatever you bound it to"] = "낚싯대를 장착했을 때만 키를 사용 – 낚싯대가 없으면 키는 원래 지정한 기능을 유지합니다",
    ["The mouse wheel scrolls the sidebar and the page. The window also shrinks to fit a screen smaller than itself, which is what left it undraggable on a high interface scale."] = "마우스 휠로 측면 목록과 본문을 넘길 수 있습니다. 창은 또한 자신보다 작은 화면에 맞게 줄어듭니다. 인터페이스 배율이 높을 때 창을 옮길 수 없던 원인이 바로 그것이었습니다.",
    ["Profile Keybind – Put a profile on a key and switch to it out of combat"] = "프로필 단축키 – 프로필을 키에 지정하고 전투 밖에서 그 프로필로 전환합니다",
    ["The bag sweep behind the food, flask and weapon oil reminders is kept until the bags change, instead of walking every bag three times over twice a second."] = "음식과 물약, 무기 기름 알림 뒤의 가방 검사는 가방이 바뀔 때까지 유지됩니다. 초당 두 번씩 모든 가방을 세 차례 훑던 방식을 대신합니다.",
    ["The modern player frame style no longer reaches into the pet and totem frames."] = "현대적 플레이어 프레임 방식이 더 이상 소환수 프레임과 토템 프레임에 손대지 않습니다.",
    ["Fine tuning for this slot"] = "이 자리의 세부 조정",
    ["Slot settings"] = "자리 설정",
    ["Border settings"] = "테두리 설정",
    ["Border size"] = "테두리 두께",
    ["How solid the empty part of the bar is."] = "생명력 바의 빈 부분이 얼마나 진한지 정합니다.",
    ["Absorb settings"] = "흡수막 설정",
    ["Border around the cast bar"] = "시전 바에 테두리 표시",
    ["Off leaves the cast bar without its own outline; the health bar keeps one."] = "끄면 시전 바에 자체 테두리가 없어집니다. 생명력 바의 테두리는 그대로 유지됩니다.",
    ["Top text"] = "위쪽 텍스트",
    ["Left text"] = "왼쪽 텍스트",
    ["Right text"] = "오른쪽 텍스트",
    ["Centred text"] = "가운데 텍스트",
    ["Unit name"] = "대상 이름",
    ["Main text positions"] = "주요 텍스트 위치",
    ["|cffaaaaaaOne thing per slot. The level rides at the name's left edge and follows it.|r"] = "|cffaaaaaa자리마다 하나씩. 레벨은 이름 왼쪽에 붙어 함께 움직입니다.|r",
    ["Health and cast bar"] = "생명력 바와 시전 바",
    ["Health bar width"] = "생명력 바 너비",
    ["Health bar height"] = "생명력 바 높이",
    ["Cast icon"] = "시전 아이콘",
    ["Cast icon settings"] = "시전 아이콘 설정",
    ["Cast background"] = "시전 배경",
    ["Cast bar border"] = "시전 바 테두리",
    ["Thickness of the cast bar's own border. 0 removes it; the health bar keeps its own."] = "시전 바 자체 테두리의 두께입니다. 0이면 사라지고 생명력 바의 테두리는 유지됩니다.",
    ["Cast bar border colour"] = "시전 바 테두리 색상",
    ["Cast timer"] = "시전 시간 표시",
    ["Cast timer settings"] = "시간 표시 설정",
    ["Cast bar Y offset"] = "시전 바 Y 위치",
    ["Cast colours and effects"] = "시전 색상과 효과",
    ["The bar's colour while a spell is being cast."] = "주문을 시전하는 동안 바에 쓰이는 색상입니다.",
    ["More cast colours"] = "기타 시전 색상",
    ["Interrupt ready"] = "차단 준비됨",
    ["Interrupt flash"] = "차단 섬광",
    ["Interrupt-ready hint"] = "알림: 차단 준비됨",
    ["Show cast bars in front of nameplates"] = "시전 바를 이름표 앞에 표시",
    ["Casts draw above every plate, so a cast you care about is never hidden behind another unit's bar."] = "모든 이름표 위에 시전 바를 그려서, 중요한 시전이 다른 대상의 바에 가려지지 않습니다.",
    ["The enemy's cast bar flashes and reads 'Interrupted' for a moment when their cast is stopped."] = "적의 시전이 차단되면 시전 바가 번쩍이며 잠시 「차단됨」이라고 표시됩니다.",
    ["Interrupt flash settings"] = "차단 섬광 설정",
    ["Target, focus and hover effects"] = "대상, 주시, 마우스오버 효과",
    ["Target effect"] = "대상 효과",
    ["A coloured edge around the plate you have targeted."] = "대상으로 지정한 이름표에 색이 있는 테두리를 표시합니다.",
    ["Target effect settings"] = "대상 효과 설정",
    ["Target arrows"] = "대상 화살표",
    ["Arrow settings"] = "화살표 설정",
    ["Target bar colour on"] = "대상 색상 사용",
    ["Focus bar colour on"] = "주시 색상 사용",
    ["A coloured edge around the plate you have set as your focus."] = "주시로 지정한 이름표에 색이 있는 테두리를 표시합니다.",
    ["Mouseover effect"] = "마우스오버 효과",
    ["Mouseover effect settings"] = "마우스오버 효과 설정",
    ["General text"] = "일반 텍스트",
    ["Debuff duration"] = "약화 효과 지속시간",
    ["Buff duration"] = "강화 효과 지속시간",
    ["Crowd control duration"] = "군중 제어 지속시간",
    ["Aura stacks"] = "효과 중첩",
    ["Timer text colour"] = "남은 시간 색상",
    ["Stack text colour"] = "중첩 숫자 색상",
    ["Text settings"] = "텍스트 설정",
    ["Spell target"] = "시전 대상",
    ["Background settings"] = "배경 설정",
    ["Hide the gryphons"] = "그리핀 숨기기",
    ["Removes the two beasts at the ends of Blizzard's main action bar. The bar itself stays."] = "기본 행동 단축바 양끝의 두 짐승을 제거합니다. 단축바 자체는 그대로 유지됩니다.",
    ["Extra indicators"] = "추가 표시",
    ["Enemy colours"] = "적 색상",
    ["Enemy types"] = "적 유형",
    ["The health bar colour a unit takes from its reaction to you."] = "대상이 당신에게 보이는 태도에 따라 체력 바가 갖는 색상입니다.",
    ["Neutral enemies"] = "중립 대상",
    ["Units that are not hostile until you make them so."] = "먼저 건드리기 전까지는 적대적이지 않은 대상입니다.",
    ["Other nameplates"] = "다른 이름표",
    ["Nameplate spacing"] = "이름표 간격",
    ["|cffaaaaaaThe game's own settings, changed live and not part of the profile — except the hitbox. Not changeable in combat.|r"] = "|cffaaaaaa게임 자체 설정으로 즉시 적용되며 프로필에 저장되지 않습니다 — 클릭 영역은 예외입니다. 전투 중에는 바꿀 수 없습니다.|r",
    ["Stackable nameplates"] = "겹치지 않는 이름표",
    ["Extra aura options"] = "추가 효과 설정",
    ["Target and focus effects"] = "대상 및 주시 효과",
    ["Plate scale while casting"] = "시전 중 이름표 크기",
    ["A casting unit's plate grows to this size, so the one that matters stands out. 100 = off."] = "시전 중인 대상의 이름표가 이 크기까지 커져서 중요한 대상이 눈에 띕니다. 100이면 사용하지 않습니다.",
    ["Opacity while casting"] = "시전 중 불투명도",
    ["A casting unit's plate is at least this opaque, even when something else is targeted."] = "시전 중인 대상의 이름표는 다른 대상을 지정해도 최소한 이만큼 진하게 유지됩니다.",
    ["The unit's name gives way to the spell name for as long as the cast runs."] = "시전이 진행되는 동안 대상 이름 대신 주문 이름이 표시됩니다.",
    ["Active talent group"] = "활성화된 특성 그룹",
    ["Left-click: show this talent group"] = "왼쪽 클릭: 이 특성 그룹 보기",
    ["Right-click: activate this talent group"] = "오른쪽 클릭: 이 특성 그룹 활성화",
    ["Talent group %d (not active)"] = "특성 그룹 %d (비활성)",
    ["Talents can only be learned in the active talent group."] = "특성은 활성화된 특성 그룹에서만 배울 수 있습니다.",
    ["Talent groups cannot be switched in combat."] = "전투 중에는 특성 그룹을 전환할 수 없습니다.",
    ["This client refused to switch the talent group."] = "이 클라이언트가 특성 그룹 전환을 거부했습니다.",
    ["Input line above the chat"] = "입력창을 대화창 위에",
    ["Puts the chat input line above the message area instead of below it. The panel and the tab bar follow it."] = "입력창을 대화 영역 아래가 아니라 위에 놓습니다. 패널과 탭 막대가 함께 따라갑니다.",
    ["Own background for the input line"] = "입력창 자체 배경",
    ["Draws the input line on our own dark background instead of Blizzard's. The dark background panel already covers the input line, so this shows once that panel is off."] = "입력창을 블리자드 기본 배경 대신 자체 어두운 배경 위에 그립니다. 어두운 배경 패널이 이미 입력창을 덮으므로, 그 패널을 끄면 나타납니다.",
    ["Addon buttons"] = "애드온 버튼",
    ["Click to show or hide the collected buttons."] = "클릭하면 모아둔 버튼을 보이거나 숨깁니다.",
    ["Where other addons' minimap buttons sit: around the map, hidden until the mouse is over it, or gathered in one box under it."] = "다른 애드온의 미니맵 버튼이 놓이는 곳: 지도 둘레, 마우스를 올릴 때까지 숨김, 또는 지도 아래 상자에 모아두기.",
    ["Around the minimap"] = "미니맵 둘레",
    ["Only on mouseover"] = "마우스를 올렸을 때만",
    ["Collected in a box"] = "상자에 모아두기",
    -- Patch notes 1.49.0
    ["Hide The Gryphons – Takes the two beasts off the ends of Blizzard's main bar without dimming anything else"] = "그리핀 숨기기 – 블리자드 기본 주 행동 단축바 양 끝의 두 짐승을 치웁니다. 다른 부분은 어둡게 하지 않습니다",
    ["Switching the module off now switches it off. Its handlers are registered when the addon loads, so a module that was already off at login never ran its shutdown: being stunned in a battleground still popped the loss-of-control display, and the interrupt bar filled up and never emptied again, because the ticker that clears its icons only starts when the module is switched on."] = "모듈을 끄면 이제 정말로 꺼집니다. 처리기는 애드온을 불러올 때 등록되므로, 접속 시점에 이미 꺼져 있던 모듈은 종료 절차를 한 번도 거치지 않았습니다. 그래서 전장에서 기절해도 제어 상실 표시가 나타났고, 방해 시전 막대는 가득 찬 뒤 다시 비워지지 않았습니다. 아이콘을 치우는 타이머가 모듈을 켤 때만 시작되기 때문입니다.",
    ["The interrupt bar no longer reads the whole world's combat log. It registered on load and never unregistered, so every combat line anywhere — several thousand a second in a raid — was taken apart for a bar whose own default is arena and battlegrounds only. It uses the same zone filter as the display beside it now."] = "방해 시전 막대가 더 이상 온 세상의 전투 기록을 읽지 않습니다. 불러올 때 등록되고 한 번도 해제되지 않아, 어디서든 발생한 모든 전투 줄이 — 공격대에서는 초당 수천 줄이 — 자기 기본값이 투기장과 전장뿐인 막대를 위해 분해되었습니다. 이제는 옆의 표시와 같은 지역 필터를 씁니다.",
    ["Switching the module on inside an arena counts as arriving. The zone decision used to live in the loading screen alone, so anyone who enabled it while already in there got no diminishing-returns ticker until the next one."] = "투기장 안에서 모듈을 켜는 것도 도착으로 셉니다. 지역 판단이 불러오기 화면에만 있었기 때문에, 이미 안에 있는 상태에서 켠 사람은 다음 투기장까지 감소 효과 타이머를 받지 못했습니다.",
    ["The item level text size slider works again. It looked for the numbers in two places it hoped they would be, and where a client parents its paper doll buttons elsewhere it found none and quietly did nothing — which from the outside is indistinguishable from the text simply being too small."] = "아이템 레벨 글자 크기 조절기가 다시 작동합니다. 숫자가 있으리라 기대한 두 곳에서 찾았는데, 클라이언트가 장비 칸 버튼을 다른 곳에 매달아 두면 하나도 찾지 못하고 조용히 아무 일도 하지 않았습니다. 밖에서 보면 글자가 그냥 너무 작은 것과 구별되지 않습니다.",
    ["Input Line Above The Chat – Puts the input line over the message area instead of under it, with the panel and the tab bar following it; Wrath client only"] = "입력창을 대화창 위에 – 입력창을 대화 영역 아래가 아니라 위에 놓고, 패널과 탭 막대가 함께 따라갑니다. Wrath 클라이언트 전용",
    ["Own Background For The Input Line – Draws the input line on its own dark background instead of Blizzard's, which is what you saw once the dark panel was off; Wrath client only"] = "입력창 자체 배경 – 입력창을 블리자드 기본 배경 대신 자체 어두운 배경 위에 그립니다. 어두운 배경 패널을 끄면 보이던 그 배경입니다. Wrath 클라이언트 전용",
    ["Icon zoom is now called Icon crop and reads in percent. It is the same question the nameplate sliders ask, and it was answering in hundredths while they answered in percent."] = "아이콘 확대가 이제 아이콘 잘라내기로 불리며 백분율로 표시됩니다. 이름표의 조절기가 묻는 것과 같은 질문인데, 저쪽은 백분율로 답하는 동안 이쪽만 백분율의 소수로 답하고 있었습니다.",
    ["The extra width belongs to the friends tab alone now. The row texts there stretch with the window, but the column headers on the who, guild and raid tabs sit at fixed offsets and stay put, so every point of width you added landed in an empty right half. Those three tabs go back to Blizzard's own proportions, which is what their columns were measured for."] = "추가 너비는 이제 친구 탭만의 것입니다. 그곳의 줄 문구는 창과 함께 늘어나지만, 검색·길드·공격대 탭의 열 머리글은 고정된 위치에 있어 움직이지 않으므로, 늘린 너비가 모두 오른쪽 빈 공간이 되었습니다. 그 세 탭은 열이 원래 맞춰져 있던 블리자드 기본 비율로 돌아갑니다.",
    ["The set list and the icon picker take the character panel's style. In the classic style they used to be a flat dark surface with a purple edge holding Blizzard's red buttons — two materials in a hand's width. They now carry Blizzard's dialog frame there and stand in the same material as the window they hang off, while the modern style keeps the flat look."] = "세트 목록과 아이콘 선택창이 캐릭터 창의 스타일을 따릅니다. 클래식 스타일에서는 보라색 테두리의 평평한 어두운 면 위에 블리자드의 붉은 버튼이 놓여 있었습니다. 한 뼘 안에 두 가지 재질이었던 셈입니다. 이제 그곳에서는 블리자드의 대화 상자 틀을 쓰고 매달린 창과 같은 재질이 되며, 모던 스타일은 평평한 모습을 유지합니다.",
    ["The character panel no longer breaks when the sidebar builds its first set row. The marker bar on the row still reached for an accent colour that had been removed, so the list stayed empty and the panel came up bare."] = "측면 목록이 첫 세트 줄을 만들 때 캐릭터 창이 더 이상 멈추지 않습니다. 줄의 표시 막대가 이미 제거된 강조 색을 계속 찾고 있어서 목록이 비었고 창이 텅 빈 채로 열렸습니다.",
    ["Addon Buttons – Choose where other addons' buttons sit: around the map, hidden until you mouse over it, or gathered in one box below it; Wrath client only"] = "애드온 버튼 – 다른 애드온의 버튼이 놓일 곳을 고릅니다. 지도 둘레, 마우스를 올릴 때까지 숨김, 또는 지도 아래 상자에 모아두기. Wrath 클라이언트 전용",
    ["Icon Crop (%) – How much of the border the game bakes into its icons is cut away, set per aura row and for the cast bar icon"] = "아이콘 잘라내기 (%) – 게임이 아이콘에 새겨 넣은 테두리를 얼마나 잘라낼지, 효과 줄마다 그리고 시전 막대 아이콘에 대해 정합니다",
    ["The rounded bar style no longer leaves dead space at both ends. The round shape does not fill its own image — a transparent border runs all the way round it — and stretching that border across a wide, short bar put roughly eleven points of empty bar at each end and barely one above and below, which is why it showed up sideways and not upright."] = "둥근 막대 스타일이 양 끝에 죽은 공간을 남기지 않습니다. 둥근 모양은 자기 그림을 가득 채우지 않고 둘레에 투명한 테두리가 돌아갑니다. 그 테두리를 넓고 낮은 막대에 늘리면 양 끝에 약 11포인트의 빈 막대가, 위아래에는 겨우 1포인트가 생깁니다. 그래서 가로로만 눈에 띄었습니다.",
    ["The options page is cut by question instead of by mechanism. Sixteen sections had settings that belong together lying far apart, with the bar texture under one heading and the cast bar's texture under another; eight settings were reachable from two sections at once."] = "설정 페이지가 구조가 아니라 질문에 따라 나뉩니다. 열여섯 개 구획에서 함께 쓰이는 설정들이 멀리 떨어져 있었고, 막대 재질은 한 제목 아래, 시전 막대 재질은 다른 제목 아래 있었습니다. 여덟 개 설정은 두 구획에서 동시에 닿을 수 있었습니다.",
    ["Every text on the plate sits in a slot now, the way the aura rows already did: top, left, right or centred, filled with the unit name or the health text. Four on/off switches became position pickers, each starting on the place its text already had."] = "이름표의 모든 글자가 이제 자리를 차지합니다. 효과 줄이 이미 그랬던 것처럼 위, 왼쪽, 오른쪽, 가운데 중 하나에 대상 이름이나 생명력 문구가 들어갑니다. 켜고 끄는 스위치 네 개가 위치 선택기가 되었고, 각각 그 글자가 이미 있던 자리에서 시작합니다.",
    ["The stacking dropdown had no readable value at all. It was reading a setting this client does not have; the one it does have is now read and written, measured in the running game."] = "겹침 방식 선택 메뉴에 읽을 수 있는 값이 전혀 없었습니다. 이 클라이언트에 없는 설정을 읽고 있었습니다. 실제로 있는 설정을 이제 읽고 쓰며, 실행 중인 게임에서 측정했습니다.",
    ["A gear icon on a half-width row opens a small floating window instead of unfolding inside the cell. Half a cell has no room for a slider, and six of them had been squeezed into stubs."] = "절반 너비 줄의 톱니바퀴가 칸 안에서 펼쳐지는 대신 작은 떠 있는 창을 엽니다. 반 칸에는 조절기가 들어갈 너비가 없어서 여섯 개가 뭉툭하게 눌려 있었습니다.",
    ["Colour swatches, eyes, gears and arrows sit directly beside the control they belong to rather than in the icon strip on the right, which stays reserved for the gear and the info dot."] = "색상 견본, 눈, 톱니바퀴, 화살표가 오른쪽 아이콘 줄이 아니라 각자 속한 조작 요소 바로 옆에 놓입니다. 오른쪽 줄은 톱니바퀴와 정보 점을 위해 계속 비워 둡니다.",
    ["On the Wrath client the module stands down completely and the client keeps its own window. Our restyle addresses Blizzard's widgets by name and by region number, and behind those names that client has a different anatomy: black holes where the hidden regions used to be, a stretched title bar, dropdowns over the recipe list — and no error, because nothing throws, it simply lands on the wrong widgets."] = "Wrath 클라이언트에서는 이 모듈이 완전히 물러나고 클라이언트가 자기 창을 그대로 씁니다. 우리 재단장은 블리자드 요소를 이름과 영역 번호로 지목하는데, 그 클라이언트에서는 같은 이름 뒤에 다른 구조가 있습니다. 숨긴 영역 자리에 검은 구멍, 늘어난 제목 줄, 제조법 목록 위로 겹치는 선택 메뉴가 생기며 오류는 나지 않습니다. 아무것도 던지지 않고 그저 엉뚱한 요소에 닿을 뿐입니다.",
    ["Talent group buttons run down the right edge, one for each group you have bought. Left-click shows a group, right-click activates it, the same split Blizzard's own window uses. Talents can only be learned in the active group, so a click in the preview does nothing and the tooltip says so beforehand."] = "오른쪽 가장자리를 따라 특성 그룹 버튼이 늘어섭니다. 구입한 그룹마다 하나씩입니다. 왼쪽 클릭은 그룹을 보여 주고 오른쪽 클릭은 활성화합니다. 블리자드 창이 쓰는 것과 같은 구분입니다. 특성은 활성화된 그룹에서만 배울 수 있으므로 미리 보기에서 누르면 아무 일도 일어나지 않고, 도움말이 미리 그렇게 알려 줍니다.",
    ["The tab carries a book instead of a question mark. That mark is Blizzard's placeholder for a missing icon and read like a defect."] = "탭에 물음표 대신 책이 붙습니다. 그 표시는 아이콘이 없을 때 쓰는 블리자드의 자리 표시자라 고장처럼 보였습니다.",
    ["Glyphs"] = "문양",
    ["CHARACTER"] = "캐릭터",
    ["Packs the selected bar setup into a string you can pass on. Slots, macros and key bindings travel with it."] = "선택한 단축바 구성을 남에게 전달할 수 있는 문자열로 묶습니다. 슬롯과 매크로, 단축키가 함께 담깁니다.",
    ["Reads a bar setup string into your library. Putting it onto your bars stays a separate step."] = "단축바 구성 문자열을 보관함으로 읽어들입니다. 실제 단축바에 적용하는 것은 별도의 단계입니다.",
    ["The bar setup string is damaged."] = "단축바 구성 문자열이 손상되었습니다.",
    ["This is not a bar setup string."] = "이것은 단축바 구성 문자열이 아닙니다.",
    ["Bar setup '%s' imported."] = "단축바 구성 '%s' 을(를) 가져왔습니다.",
    ["Macros left alone: the switch above is off."] = "매크로는 건드리지 않았습니다: 위의 스위치가 꺼져 있습니다.",
    ["Macros: %d restored, |cffff8800%d failed|r -- the macro list may be full."] = "매크로: %d개 복원, |cffff8800%d개 실패|r -- 매크로 목록이 가득 찼을 수 있습니다.",
    ["Macros: %d restored."] = "매크로: %d개 복원했습니다.",
    ["Key bindings left alone: the switch above is off."] = "단축키는 건드리지 않았습니다: 위의 스위치가 꺼져 있습니다.",
    ["Key bindings: %d applied."] = "단축키: %d개 적용했습니다.",
    ["Bar setup '%s' saved: %d slots, %d macros, %d key bindings."] = "단축바 구성 '%s' 저장: 슬롯 %d개, 매크로 %d개, 단축키 %d개.",
    ["|cffff8800No key bindings were captured.|r This client may not report them."] = "|cffff8800단축키를 하나도 수집하지 못했습니다.|r 이 클라이언트가 단축키를 보고하지 않을 수 있습니다.",
    -- Patch notes 1.50.0
    ["Export as string – Packs the selected setup into a string you can pass on, with its slots, macros and key bindings"] = "문자열로 내보내기 – 선택한 구성을 슬롯과 매크로, 단축키까지 담아 남에게 전달할 수 있는 문자열로 묶습니다",
    ["Import from string – Reads someone else's setup into your library; a name you already use gets a number rather than being overwritten"] = "문자열에서 가져오기 – 다른 사람의 구성을 보관함으로 읽어들입니다. 이미 쓰고 있는 이름은 덮어쓰지 않고 번호가 붙습니다",
    ["An imported setup is rebuilt entry by entry before it is stored. The restore walks every entry, so a malformed one would have thrown in the middle of a run with part of your bars already changed. Broken entries are dropped, the rest still arrives."] = "가져온 구성은 보관되기 전에 항목 하나하나가 새로 만들어집니다. 복원 과정은 모든 항목을 훑기 때문에, 형태가 어긋난 항목이 하나라도 있으면 단축바를 절반쯤 바꾼 상태에서 중간에 오류가 났을 것입니다. 망가진 항목만 버리고 나머지는 그대로 들어옵니다.",
    ["Saving and loading say what they did. Both had been counting their work all along and throwing the numbers away, so a setup whose macros all failed looked exactly like one that had none, and a save that captured no key bindings said nothing at all."] = "저장과 불러오기가 무엇을 했는지 알려줍니다. 둘 다 처음부터 작업량을 세고 있었으면서 그 숫자를 버렸습니다. 그래서 매크로가 전부 실패한 구성이 매크로가 아예 없는 구성과 똑같아 보였고, 단축키를 하나도 수집하지 못한 저장은 아무 말도 하지 않았습니다.",
    ["The character window can be placed by hand on the Wrath client. Blizzard's editor does not own that window, so it takes the same direct route the loot window already uses; one box moves the character, reputation and skills tabs together, and the stats panel and set list travel with it."] = "Wrath 클라이언트에서 캐릭터 창을 직접 배치할 수 있습니다. 블리자드 편집기가 그 창을 관리하지 않으므로, 전리품 창이 이미 쓰는 직접 경로를 따릅니다. 상자 하나가 캐릭터·평판·숙련 탭을 함께 옮기며, 능력치 패널과 세트 목록도 같이 따라갑니다.",
    ["The window starts wide on the Wrath client. The slider has always gone to 400 — it simply started at nothing, so the extra room only ever reached whoever went looking for it."] = "Wrath 클라이언트에서는 창이 처음부터 넓게 열립니다. 조절기는 예전부터 400까지 있었지만 시작값이 0이라, 늘어난 공간은 그것을 찾아본 사람에게만 돌아갔습니다.",
    ["The glyph page opens from a button under the talent group buttons, and it is dark now. The rune circle is dimmed rather than removed, because it is what makes that page recognisable; the sockets take the accent colour, and the glyph artwork and the pickup highlight stay as they are."] = "문양 페이지는 특성 그룹 버튼 아래의 버튼으로 열리며, 이제 어둡습니다. 룬 원은 지우지 않고 어둡게만 했습니다. 그 원이 있어야 이 페이지를 알아볼 수 있기 때문입니다. 홈은 강조색을 쓰고, 문양 그림과 집어들 때의 강조 표시는 그대로 둡니다.",
    ["The talent group button shows its tree's icon instead of a question mark. It asked for that icon through an interface that does not answer on every client, and fell back to the placeholder; the answer is now worked out from the ranks themselves, which cannot be misread."] = "특성 그룹 버튼이 물음표 대신 해당 계열의 아이콘을 보여줍니다. 모든 클라이언트에서 답하지 않는 인터페이스로 아이콘을 묻다가 자리 표시자로 물러났었는데, 이제는 잘못 읽힐 수 없는 특성 등급 자체에서 답을 구합니다.",
    ["The level number on the player frame sits where the client puts it on the Wrath client. Our two anchors are measured against one frame sheet, and where a different one ships, the number landed beside the portrait — the client keeps that anchor itself there anyway, moving it as the rest and PvP icons come and go."] = "Wrath 클라이언트에서 플레이어 프레임의 레벨 숫자가 클라이언트가 놓는 자리에 놓입니다. 우리 두 고정점은 하나의 프레임 이미지에 맞춰 측정된 것이라, 다른 이미지가 실린 곳에서는 숫자가 초상화 옆에 떨어졌습니다. 게다가 그곳에서는 클라이언트가 그 고정점을 직접 관리하며 휴식·PvP 아이콘이 나타나고 사라짐에 따라 옮깁니다.",

    -- Character Panel: socket strip
    ["Socket strip under the window"] = "창 아래 홈 막대",
    ["Puts a strip with every socket of your equipped gear under the character window. Click a socket to put a gem from your bags into it. Stays empty on clients whose game has no gems."] = "착용 중인 장비의 모든 홈을 모은 막대를 캐릭터 창 아래에 놓습니다. 홈을 클릭하면 가방에 있는 보석을 그 홈에 박습니다. 보석이 없는 게임의 클라이언트에서는 비어 있습니다.",
    ["Choose a gem"] = "보석 선택",
    ["No gems in your bags."] = "가방에 보석이 없습니다.",
    ["Empty socket"] = "빈 홈",
    ["Click to pick a gem from your bags."] = "클릭하면 가방에서 보석을 고릅니다.",
    ["Cannot socket gems in combat."] = "전투 중에는 보석을 박을 수 없습니다.",
    ["Close the socketing window first."] = "먼저 보석 박기 창을 닫으세요.",
    -- Patch notes 1.51.0
    ["Socket strip under the window – A row of every socket on your equipped gear, hung under the character window; click a socket to put a gem from your bags into it"] = "창 아래 홈 막대 – 착용 중인 장비의 모든 홈을 모은 줄을 캐릭터 창 아래에 놓습니다. 홈을 클릭하면 가방에 있는 보석을 그 홈에 박습니다",
    ["The enchant text on armour slots reads the enchant again instead of the item's difficulty tag. The filter took the first green line of the tooltip, and where an item carries a tag that tag stands above the enchant — so every such slot showed the tag, while a weapon two rows down showed its enchant correctly because nothing stood in front of it. The tag and the client's bracketed hints are both recognised now, in every language rather than only in English and German."] = "방어구 칸의 마법부여 문구가 아이템의 난이도 표시 대신 다시 마법부여를 보여줍니다. 필터가 툴팁의 첫 초록색 줄을 가져왔는데, 표시가 있는 아이템에서는 그 표시가 마법부여보다 위에 있습니다 — 그래서 해당 칸마다 표시가 나왔고, 두 줄 아래의 무기는 앞에 아무것도 없어 마법부여가 제대로 나왔습니다. 이제 표시와 클라이언트의 꺾쇠 안내문을 모두 인식하며, 영어와 독일어뿐 아니라 모든 언어에서 그렇습니다.",
    ["The set list no longer casts a shadow past its own frame. What looked like the background standing out over the border was a drop shadow: not an outline but four filled rectangles reaching up to seven pixels beyond the frame on every side, and behind Blizzard's dialog frame there was nothing for it to fall on. It is gone in both looks."] = "세트 목록이 더 이상 자기 테두리 밖으로 그림자를 드리우지 않습니다. 배경이 테두리 밖으로 삐져나온 것처럼 보이던 것은 그림자였습니다. 윤곽선이 아니라 사방으로 최대 7픽셀까지 테두리를 넘어가는 채워진 사각형 네 장이었고, 블리자드 대화 상자 테두리 뒤에서는 그림자가 드리울 대상도 없었습니다. 두 가지 모양 모두에서 사라졌습니다.",
    ["In the Classic+ look the dark ground stopped short of the ornate line instead of ending on it, and so showed past the frame on every side."] = "Classic+ 모양에서는 어두운 바탕이 장식선 위가 아니라 그 앞에서 끝나, 사방으로 테두리 밖까지 삐져나왔습니다.",

    -- Nameplates: layout preset + health text content
    ["Apply this arrangement"] = "이 배치 적용",
    ["Puts the unit name and the health value inside the bar, crowd control left of it, incoming debuffs above that and buffs to its right, and gives the cast bar its icon, its remaining time and its target. Your current arrangement is saved first and the button beside this one brings it back."] = "유닛 이름과 생명력 값을 막대 안에, 군중 제어를 그 왼쪽에, 들어오는 약화 효과를 그 위에, 강화 효과를 오른쪽에 놓고, 시전 바에 아이콘과 남은 시간과 대상을 붙입니다. 현재 배치는 먼저 저장되며 옆 단추가 되돌립니다.",
    ["Restore my arrangement"] = "내 배치 되돌리기",
    ["Puts every text and aura position back to what it was before the arrangement was applied, and removes the saved copy. Anything you moved by hand since then goes back as well."] = "모든 텍스트와 오라 위치를 배치를 적용하기 전 상태로 되돌리고 저장된 사본을 지웁니다. 그 뒤에 손수 옮긴 것도 함께 돌아갑니다.",
    ["Nameplate layout applied. The button beside it puts your old one back."] = "이름표 배치를 적용했습니다. 옆 단추가 이전 배치를 되돌립니다.",
    ["Nameplate layout restored."] = "이름표 배치를 되돌렸습니다.",
    ["Shows"] = "표시 내용",
    ["Current health"] = "현재 생명력",
    ["Current and maximum"] = "현재와 최대",
    ["Current and percent"] = "현재와 백분율",
    ["Separator"] = "구분 기호",
    ["What goes between the two numbers, when the row above is set to current and percent."] = "위 줄이 현재와 백분율로 설정되어 있을 때 두 숫자 사이에 들어가는 것입니다.",
    ["Brackets"] = "괄호",
    ["Vertical bar"] = "세로줄",
    ["Dash"] = "붙임표",
    ["Space"] = "공백",
    -- Patch notes 1.52.0
    ["The own background for the input line is offered on every client. It was limited to one client generation, and the code already said it would work everywhere."] = "입력줄의 자체 배경을 모든 클라이언트에서 제공합니다. 한 클라이언트 세대에만 한정되어 있었고, 코드에는 어디서든 작동하리라고 이미 적혀 있었습니다.",
    ["The icon borders are pixel-exact. The border there is not a texture of its own but the rim of a plate behind the icon, so the two have to sit on the same pixel grid, the thickness has to be counted in pixels rather than frame units, and the icon size and spacing have to begin on whole pixels. None of the three was true, which is why a rim came out two pixels on one edge and none on the opposite."] = "아이콘 테두리가 픽셀 단위로 정확해졌습니다. 그곳의 테두리는 자체 텍스처가 아니라 아이콘 뒤 판의 가장자리라서, 둘이 같은 픽셀 격자에 놓여야 하고, 두께는 프레임 단위가 아니라 픽셀로 세어야 하며, 크기와 간격도 정수 픽셀에서 시작해야 합니다. 셋 중 어느 것도 맞지 않았고, 그래서 한쪽 모서리는 두 픽셀, 맞은편은 없는 테두리가 나왔습니다.",
    ["Apply this arrangement – Puts the unit name and the health value inside the bar, crowd control left of it, incoming debuffs above that and buffs to its right, with the cast bar carrying its icon, its remaining time and its target"] = "이 배치 적용 – 유닛 이름과 생명력 값을 막대 안에, 군중 제어를 그 왼쪽에, 들어오는 약화 효과를 그 위에, 강화 효과를 오른쪽에 놓고, 시전 바는 아이콘과 남은 시간과 대상을 답니다",
    ["The unit name was hidden behind the health bar fill as soon as a text slot put it inside the bar. The name and the health value hang from different parents: the value is created on the bar, the name on the plate, and the bar is a child of the plate — so it draws over anything the plate draws. While the name only ever sat above the bar this never showed. It has its own layer now, above the bar but not attached to it, because name-only mode hides that bar and a text parented to a hidden frame would go with it."] = "텍스트 자리가 유닛 이름을 막대 안에 놓는 순간, 이름이 생명력 막대의 채움 뒤로 숨었습니다. 이름과 생명력 값은 서로 다른 부모에 달려 있습니다. 값은 막대 위에, 이름은 이름표 위에 만들어지고, 막대는 이름표의 자식이라 이름표가 그리는 모든 것 위에 그려집니다. 이름이 막대 위쪽에만 있을 때는 드러나지 않았습니다. 이제 이름은 막대 위에 있으면서도 막대에 매이지 않은 자체 층에 놓입니다. 이름만 표시하는 방식은 그 막대를 감추고, 감춰진 프레임에 매인 글자는 함께 사라지기 때문입니다.",
    ["The health text has its controls back: what it shows, and which mark goes between the two numbers. Both were still being read and had been unreachable since the page was rebuilt."] = "생명력 문구가 조작 수단을 되찾았습니다. 무엇을 보여줄지, 그리고 두 숫자 사이에 어떤 기호가 들어갈지입니다. 둘 다 계속 읽히고 있었지만 페이지를 다시 만든 뒤로는 어디서도 바꿀 수 없었습니다.",
    ["The active talent group was always reported as the first one on clients that do not carry the newer interface for it. Everything behind that believed group one was running: the header called the group you were standing in not active, the activate button offered to switch to the one already on, and the switch reported success while changing nothing. Five files ask that same question, so profile overrides and bar setups were reading it too."] = "그에 해당하는 최신 인터페이스가 없는 클라이언트에서는 활성 특성 그룹이 언제나 첫 번째로 보고되었습니다. 그 뒤의 모든 것이 그룹 1이 돌아간다고 믿었습니다. 머리글은 여러분이 서 있는 그룹을 활성이 아니라고 불렀고, 활성화 단추는 이미 돌아가는 쪽으로 바꾸자고 제안했으며, 전환은 아무것도 바꾸지 않고 성공을 알렸습니다. 다섯 파일이 같은 질문을 하므로 프로필 재정의와 바 구성도 거기서 읽고 있었습니다.",
    ["The glyph page stands permanently beside the window. It is lifted out of Blizzard's talent frame, where it lives inside the scroll area of the very window we replace, and handed back when ours closes."] = "문양 페이지가 창 옆에 항상 자리합니다. 그것은 블리자드 특성 창에서 들어 올려집니다. 원래 그 페이지는 우리가 대체하는 바로 그 창의 스크롤 영역 안에 있으며, 우리 창을 닫으면 되돌려 줍니다.",
    ["The separate glyph button is gone with it. Its only job was to send you to the page that now stands in front of you."] = "그와 함께 별도의 문양 단추는 사라졌습니다. 그 단추의 유일한 일은 이제 여러분 앞에 놓인 그 페이지로 보내는 것이었습니다.",
    ["A band under the header carries the activate button and the name of the talent group on screen. Until now switching existed only as a right-click on the small side icons, and nothing announced it."] = "머리글 아래 띠에 활성화 단추와 화면에 보이는 특성 그룹의 이름이 놓입니다. 지금까지 전환은 옆쪽 작은 아이콘을 오른쪽 클릭하는 방법으로만 있었고, 그것을 알리는 것은 아무것도 없었습니다.",
    ["Form paging"] = "변신 페이지 전환",
    ["Keep the main bar on its page in every form"] = "모든 변신에서 주 행동 단축바를 현재 페이지로 유지",
    ["|cffaaaaaaCat, bear, stealth, stances and Shadowform normally swap the main bar to their own page. Switch this off to keep the bar you built through every form.|r"] = "|cffaaaaaa표범, 곰, 은신, 태세, 어둠의 형상은 보통 주 행동 단축바를 각자의 페이지로 전환합니다. 이 기능을 끄면 직접 구성한 단축바가 모든 변신에서 그대로 유지됩니다.|r",
    -- Patch notes 1.52.1
    ["Keep the main bar on its page in every form – Cat, bear, stealth, stances and Shadowform stop swapping action bar 1 to a page of their own"] = "모든 변신에서 주 행동 단축바를 현재 페이지로 유지 – 표범, 곰, 은신, 태세, 어둠의 형상이 더 이상 행동 단축바 1을 각자의 페이지로 바꾸지 않습니다",
    ["The ticker that paints cooldown dimming and range colouring no longer walks switched-off bars. It read and repainted every action bar five times a second, including the ones whose buttons nobody can see, so running two bars cost as much as running all of them."] = "재사용 대기시간 어둡게 표시와 사거리 색상을 그리는 티커가 더 이상 꺼진 단축바를 훑지 않습니다. 아무도 볼 수 없는 버튼까지 포함해 모든 행동 단축바를 초당 다섯 번 읽고 다시 칠했기 때문에, 두 개만 쓰는 사람도 전부 쓰는 것과 같은 비용을 냈습니다.",
    ["Leaving a button no longer builds a fresh check each time. The check only ever reads the bar, not the button, so it is built once per bar and shared by all of its buttons."] = "버튼에서 마우스를 뗄 때마다 새 검사 함수를 만들지 않습니다. 이 검사는 버튼이 아니라 단축바만 읽으므로, 단축바마다 한 번만 만들어 그 단축바의 모든 버튼이 함께 씁니다.",
    ["The opponent frames are left alone unless you actually asked for a different arrangement. They are protected frames: anchoring one from our side is allowed outside a fight, but it marks the frame for the rest of the session, and the next time the default interface repositions it during a round its own call is refused and the block is reported against us. There is no way to anchor a protected frame without leaving that mark, so an untouched setup now keeps the default stacking. Order, spacing, grow direction and slot offsets all still work — the message becomes the price of a feature you asked for rather than something every arena hands out for free."] = "직접 다른 배치를 요청하지 않았다면 상대 프레임을 건드리지 않습니다. 이들은 보호된 프레임입니다. 전투 밖에서 고정하는 것은 허용되지만 그 프레임에 남은 세션 내내 표시가 남고, 다음번에 기본 인터페이스가 라운드 도중 위치를 옮기려 하면 그쪽의 호출이 거부되며 그 차단이 우리 탓으로 보고됩니다. 표시를 남기지 않고 보호된 프레임을 고정할 방법은 없으므로, 손대지 않은 설정은 이제 기본 정렬을 그대로 둡니다. 순서, 간격, 성장 방향, 칸 오프셋은 모두 그대로 작동합니다. 이 메시지는 이제 모든 투기장이 공짜로 나눠주는 것이 아니라, 직접 요청한 기능의 대가가 됩니다.",
    ["Move up and move down work again on a category you switched off and back on. The order list was filled once, while it was still empty, so anything that did not exist at that moment never got an entry, and its arrows then did nothing at all for the rest of the session without saying so."] = "껐다가 다시 켠 분류에서 위로, 아래로가 다시 작동합니다. 순서 목록은 아직 비어 있을 때 한 번만 채워졌기 때문에, 그 순간에 없던 항목은 끝내 자리를 얻지 못했고 그 화살표는 남은 세션 내내 아무 말 없이 아무 일도 하지 않았습니다.",
    ["Switching a module off releases its event handlers again. The note recording which module owns a handler stayed behind when the handler was unregistered, and that note kept a hard reference to every handler the module had ever registered."] = "모듈을 끄면 그 이벤트 핸들러가 다시 해제됩니다. 어떤 모듈이 핸들러를 소유하는지 적어 둔 기록이 해제할 때 남아 있었고, 그 기록이 모듈이 등록했던 모든 핸들러를 강하게 붙잡고 있었습니다.",
    -- Patch notes 1.52.2
    ["Casting out of the spell book keeps working after the book was opened from the micro menu. Our micro buttons are stand-ins that hand the click on to the default button behind them, which runs everything that follows inside our own call — and for the spell book that ends in the book writing down which half of itself it is showing. That note then counted as ours, the book reads it on every click on a spell, and so every cast from the book was refused as coming from an addon. Out of combat as well, for the rest of the session, until the interface was reloaded. Opening the book by its key was never affected. The micro menu now carries the default button itself, wearing our icon, so nothing is handed through us any more."] = "마이크로 메뉴로 주문서를 연 뒤에도 주문서에서 주문을 시전할 수 있습니다. 우리 마이크로 단추는 뒤에 있는 기본 단추에 클릭을 넘기는 대역이라, 그 뒤의 모든 과정이 우리 호출 안에서 실행됩니다 — 주문서의 경우 그 끝에서 주문서가 자기 중 어느 쪽을 보여 주는지 기록합니다. 그 기록이 우리 것으로 취급되고, 주문서는 주문을 누를 때마다 그것을 읽기 때문에 주문서에서의 모든 시전이 애드온의 호출로 거부되었습니다. 전투 밖에서도 마찬가지였고, 인터페이스를 다시 불러올 때까지 그 세션 내내 이어졌습니다. 단축키로 연 주문서는 한 번도 영향을 받지 않았습니다. 이제 마이크로 메뉴에는 기본 단추 자체가 우리 아이콘을 달고 들어 있어, 더는 우리를 거쳐 넘어가는 것이 없습니다.",
    ["Pointing at a bag slot shows the tooltip of the bag itself — quality colour, how much it holds, everything the item carries — with the click hints under it, instead of the bare name. In the inventory window as well as at the bank, which had drifted apart although the two bars are the same thing."] = "가방 칸을 가리키면 이름만 뜨는 대신 가방 자체의 툴팁이 나옵니다 — 품질 색, 수용량, 아이템이 지닌 모든 것 — 그 아래에 클릭 안내가 붙습니다. 소지품 창에서도, 은행에서도 그렇습니다. 두 막대는 같은 것인데도 그동안 서로 어긋나 있었습니다.",
    ["The bar in the inventory window takes bags now, the way the one at the bank already did: drag a bag onto a slot to put it there, or left-click a slot with a bag on the cursor. Right-click with an empty hand takes the bag off again, and left-click with an empty hand still shows and hides it. The backpack and the keyring are not slotted bags, so they accept nothing and are not offered the right-click line in the first place."] = "소지품 창의 막대도 이제 가방을 받습니다. 은행 쪽이 이미 하던 대로, 가방을 칸에 끌어다 놓으면 그 자리에 장착되고, 커서에 가방을 든 채 칸을 왼쪽 클릭해도 같습니다. 빈손으로 오른쪽 클릭하면 가방을 다시 빼고, 빈손으로 왼쪽 클릭하면 여전히 보이기와 숨기기를 합니다. 기본 가방과 열쇠 꾸러미는 장착된 가방이 아니므로 아무것도 받지 않고, 오른쪽 클릭 안내도 처음부터 제공되지 않습니다.",
    ["The enchant on the wrist slot sits closer to the rows around it, and the enchant on the weapon sits six pixels lower."] = "손목 칸의 마법부여 글씨가 주변 줄에 더 가까워지고, 무기의 마법부여 글씨는 여섯 픽셀 아래로 내려갑니다.",
    ["The trainer tab is a button of its own now. It used to be a spare tab of the spell book that we wrote on with every update, and the book reads those tabs back in the middle of its own pass. It also goes away with the pet book, where it used to stay behind."] = "교관 탭이 이제 우리 고유의 단추가 되었습니다. 예전에는 주문서의 남는 탭이었고 우리가 갱신할 때마다 거기에 기록했는데, 주문서는 자기 처리 도중에 그 탭들을 다시 읽습니다. 또한 소환수 주문서에서는 이제 함께 사라집니다. 전에는 그대로 남아 있었습니다.",
    -- Nameplates: aura border + CC size
    ["Match the health bar height"] = "생명력 막대 높이에 맞추기",
    ["The icon becomes a square exactly as tall as the health bar. The three size sliders below step aside while this is on."] = "아이콘이 정사각형이 되어 생명력 막대와 정확히 같은 높이가 됩니다. 이 설정이 켜져 있는 동안 아래의 크기 조절 막대 세 개는 물러납니다.",
    ["Border around aura icons"] = "오라 아이콘 테두리",
    ["The thin rim around debuff, damage-over-time, buff and crowd-control icons. Its thickness follows the border size of the plate."] = "약화 효과, 지속 피해, 강화 효과, 군중 제어 아이콘을 두르는 얇은 테두리입니다. 두께는 이름표의 테두리 두께를 따릅니다.",
    ["Aura border colour"] = "오라 테두리 색",
    ["Border in the aura's own school colour"] = "효과의 계열 색으로 테두리 칠하기",
    ["Magic blue, curse purple, disease orange, poison green — instead of the one colour beside it."] = "마법 파랑, 저주 보라, 질병 주황, 독 초록 — 옆의 단일 색 대신.",
    -- Global settings: settings window scale
    ["Settings Window Scale"] = "설정 창 크기",
    ["Scales this settings window on its own. The game's interface keeps the size it has."] = "이 설정 창만 크기를 조절합니다. 게임 인터페이스는 지금 크기 그대로 유지됩니다.",
    -- Patch notes 1.52.3
    ["Match the health bar height – Makes the crowd-control icon a square exactly as tall as the health bar, in place of its own size sliders"] = "생명력 막대 높이에 맞추기 – 군중 제어 아이콘을 자체 크기 조절 막대 대신 생명력 막대와 정확히 같은 높이의 정사각형으로 만듭니다",
    ["Border around aura icons – Switches the rim around debuff, damage-over-time, buff and crowd-control icons on or off, with its colour beside it"] = "오라 아이콘 테두리 – 약화 효과, 지속 피해, 강화 효과, 군중 제어 아이콘을 두르는 테두리를 켜거나 끕니다. 색은 바로 옆에 있습니다",
    ["Text size – Sets how large the unit name and the health value are drawn, in the panel behind each of those two rows"] = "문자 크기 – 대상 이름과 생명력 값을 얼마나 크게 그릴지 정합니다. 각 줄 뒤의 판에 있습니다",
    ["A long unit name is trimmed with three dots instead of running through the health value. The two share the bar as soon as both sit inside it, so the name now gets the width that is actually free — and only a health value at the other end takes room away, because sharing one slot is something you did on purpose. Only a name that would overflow is capped at all, which is what keeps the level number glued to the name instead of hanging off an oversized box."] = "긴 대상 이름은 생명력 값을 뚫고 지나가는 대신 점 세 개로 잘립니다. 둘이 모두 막대 안에 있으면 막대를 나눠 쓰게 되므로, 이름은 이제 실제로 비어 있는 너비를 받습니다 — 자리를 빼앗는 것은 반대쪽 끝의 생명력 값뿐이며, 같은 자리를 함께 쓰는 것은 직접 선택한 일입니다. 넘칠 이름만 제한되고, 그래서 레벨 숫자가 너무 넓은 상자 끝에 매달리지 않고 이름에 붙어 있습니다.",
    ["The aura border can also take the colour of the aura's own school. That switch was read from the start and had no control anywhere."] = "오라 테두리도 효과의 계열 색을 따를 수 있습니다. 그 설정은 처음부터 읽히고 있었지만 어디에도 조작할 곳이 없었습니다.",
    ["Settings Window Scale – Scales this settings window on its own, from 70 to 130 per cent, while the game's interface keeps the size it has"] = "설정 창 크기 – 게임 인터페이스는 그대로 둔 채 이 설정 창만 70에서 130퍼센트까지 조절합니다",
    ["Making the window smaller now gives it back its full size on a screen that was cutting it off. The fitting measured the room in the game's units and the window in its own, so scaling it down changed nothing about what it was allowed to be."] = "창을 작게 하면 이제 창을 잘라내던 화면에서도 원래 크기를 되찾습니다. 맞춤 계산이 공간은 게임의 단위로, 창은 창 자체의 단위로 재고 있었기 때문에 작게 해도 창이 가질 수 있는 크기는 달라지지 않았습니다.",
    -- Nameplates: reverse aura swipe
    ["Reverse the swipe"] = "쓸어내기 방향 반대로",
    ["The shade grows back as the aura runs out, so a nearly clear icon means it is nearly gone."] = "효과가 끝나갈수록 그림자가 다시 차오릅니다. 아이콘이 거의 깨끗해 보이면 거의 끝났다는 뜻입니다.",
    -- Character panel: socket overwrite confirmation
    ["Replace %s with %s? The gem that comes out is destroyed."] = "%s을(를) %s(으)로 교체할까요? 빠지는 보석은 파괴됩니다.",
    ["That socket has changed — nothing was socketed."] = "그 홈이 변경되었습니다 — 아무것도 박지 않았습니다.",
    ["Click to replace the gem — the old one is destroyed."] = "클릭하면 보석을 교체합니다 — 기존 보석은 파괴됩니다.",
    ["Ask before overwriting a gem"] = "보석을 덮어쓰기 전에 확인",
    ["A click on a socket that already holds a gem asks first — putting a gem in destroys the one that comes out."] = "이미 보석이 박힌 홈을 클릭하면 먼저 확인합니다 — 보석을 박으면 빠지는 보석이 파괴됩니다.",
    -- Loadouts: equipping straight out of the bank
    ["%d of them came out of the bank."] = "그중 %d개는 은행에서 꺼냈습니다.",
    ["in the bank — open the bank window to equip it"] = "은행에 있음 — 착용하려면 은행 창을 여세요",
    -- Patch notes 1.52.4
    ["Ask before overwriting a gem – A click on a socket that already holds a gem asks first, because putting a gem in destroys the one that comes out"] = "보석을 덮어쓰기 전에 확인 – 이미 보석이 박힌 홈을 클릭하면 먼저 확인합니다. 보석을 박으면 빠지는 보석이 파괴되기 때문입니다",
    ["Pointing at an occupied socket says what a click on it costs. Clicking one was always allowed, nothing ever said so, and the gem that comes out is destroyed. The question names both gems in their quality colours, and it drops the action when the gear moved while it was standing — otherwise a swap under the open dialog would answer for a socket you never looked at."] = "보석이 박힌 홈을 가리키면 클릭의 대가를 알려줍니다. 클릭은 늘 가능했지만 아무도 알려주지 않았고, 빠지는 보석은 파괴됩니다. 확인 창은 두 보석을 품질 색으로 보여주며, 창이 열려 있는 동안 장비가 바뀌면 작업을 취소합니다 — 그러지 않으면 열린 창 아래에서 일어난 교체가 한 번도 보지 않은 홈을 대신 답하게 됩니다.",
    ["Equipping a set at the bank takes the pieces that are lying in the bank, as long as the bank window is open. Until now they counted as missing, so you could stand at the bank and be told the set was not equippable. The message says how many of them came out of the bank, and the piece that comes off goes into the bank slot the new one came from. With the bank closed, a missing piece in there no longer only names its place, it says to open the bank window."] = "은행에서 세트를 착용할 때, 은행 창이 열려 있는 동안에는 은행에 있는 부위도 가져옵니다. 지금까지는 없는 것으로 셌기 때문에 은행 앞에 서 있어도 세트를 착용할 수 없다는 말을 들었습니다. 메시지는 그중 몇 개가 은행에서 나왔는지 알려주며, 벗은 부위는 새 부위가 있던 은행 칸으로 들어갑니다. 은행이 닫혀 있으면 그곳에 있는 부위는 위치만 알려주는 대신 은행 창을 열라고 말합니다.",
    ["The line that tells you which sets an item belongs to appears in item tooltips. It was built and hooked up from the start, but it went in through the one tooltip mechanism this client offers and never uses, so no line was ever drawn and nothing complained."] = "아이템이 어떤 세트에 속하는지 알려주는 줄이 아이템 툴팁에 나타납니다. 처음부터 만들어져 연결되어 있었지만, 이 클라이언트가 제공하기만 하고 쓰지 않는 툴팁 방식으로만 연결되어 있어서 줄이 그려진 적이 없고 아무 오류도 나지 않았습니다.",
    ["Reverse the swipe – The shade grows back as the aura runs out, so a nearly clear icon means it is nearly gone"] = "쓸어내기 방향 반대로 – 효과가 끝나갈수록 그림자가 다시 차오릅니다. 아이콘이 거의 깨끗해 보이면 거의 끝났다는 뜻입니다",
    ["The cooldown swipe on the aura icons has a control of its own. It was read from the start and could not be changed anywhere."] = "효과 아이콘의 재사용 대기 쓸어내기에 자체 설정이 생겼습니다. 처음부터 읽고만 있었고 어디서도 바꿀 수 없었습니다.",
    ["The raid target marker is visible at all. The eight marks live on one sheet, and the call that picks a tile out of it was working on a frame that never got the sheet — a cut-out of nothing, on every plate and in the preview, since the module was built."] = "공격대 표식이 아예 보입니다. 여덟 개의 표식은 한 장의 이미지에 모여 있고, 그중 한 칸을 고르는 함수가 그 이미지를 한 번도 받지 못한 면 위에서 동작하고 있었습니다 — 아무것도 없는 것에서 잘라낸 조각이며, 모듈을 만든 때부터 모든 이름판과 미리 보기에서 그랬습니다.",
    ["The raid target marker takes one of the six named slots, like the four aura rows. It had three positions of its own and could land on top of a row, which is the very collision the slots exist for. The old choice moves into the matching slot once and then goes, so there is no second control for the same question. Its room is reserved as soon as it is switched on, not only once a unit really carries a mark, so the rows do not jump every time somebody sets a skull."] = "공격대 표식이 네 개의 효과 줄처럼 여섯 개의 이름 붙은 자리 중 하나를 차지합니다. 예전에는 자체 위치가 세 개뿐이어서 효과 줄 위에 겹칠 수 있었는데, 그것이 바로 자리 개념이 생긴 이유입니다. 옛 선택은 한 번 해당 자리로 옮겨진 뒤 사라지므로 같은 질문에 두 개의 설정이 남지 않습니다. 자리는 켜는 순간 예약되며, 대상이 실제로 표식을 달 때만 예약되지 않습니다. 그래야 누군가 해골을 찍을 때마다 줄이 튀지 않습니다.",
    ["The marker's own offset and spacing sliders take effect again. They were writing two fields of their own while the plate read the slot, so the visible control was the one without an effect. The old values move across once."] = "표식 자체의 위치와 간격 슬라이더가 다시 작동합니다. 이름판은 자리를 읽는데 슬라이더는 자체 항목 두 개에 쓰고 있어서, 눈에 보이는 설정이 아무 효과도 없는 쪽이었습니다. 옛 값은 한 번 함께 옮겨집니다.",
    ["A mark set between two aura passes lands where it belongs. Where the marker goes is worked out in the aura pass, because only that knows how far the rows on its side reach, and the plate now remembers that point for the event that shows the marker on its own."] = "두 효과 갱신 사이에 찍힌 표식도 제자리에 나타납니다. 표식의 위치는 효과 갱신에서 계산되는데, 그쪽만 같은 편의 줄이 얼마나 뻗어 있는지 알기 때문입니다. 이제 이름판이 그 지점을 기억해 표식만 따로 표시하는 상황에도 씁니다.",
    ["The cast time and the cast target show something in the preview. Both only exist for a cast that is really running on a real unit, so both stayed empty while their switches, colours and side settings stood next to them with nothing to show."] = "시전 시간과 시전 대상이 미리 보기에도 표시됩니다. 둘 다 실제 대상에게 실제로 진행되는 시전에서만 생기므로, 스위치와 색과 방향 설정이 나란히 있는데도 두 칸은 계속 비어 있었습니다.",
    -- Slot picker: the bags moved under an open picker
    ["Your bags moved — pick the item again."] = "가방이 바뀌었습니다 — 아이템을 다시 선택하세요.",
    -- Bar setups: load confirmation, imported macros left alone
    ["Load '%s'? Every button on your bars is overwritten or cleared."] = "'%s'을(를) 불러올까요? 단축바의 모든 칸이 덮어써지거나 비워집니다.",
    ["Macros: %d restored, %d of your own kept (an import does not rewrite them)."] = "매크로: %d개 복원, 내 매크로 %d개 유지 (가져오기는 덮어쓰지 않습니다).",
    -- Patch notes 1.52.5
    ["The enchant text of the wrist slot sits under its slot instead of beside it. The wrist is the last slot of the left column, and to the right of it lies the weapon row, which is where the line was writing."] = "손목 방어구의 마법부여 문구가 옆이 아니라 칸 아래에 표시됩니다. 손목은 왼쪽 열의 마지막 칸이고 그 오른쪽에는 무기 칸이 있어서, 문구가 바로 그 자리에 쓰이고 있었습니다.",
    ["Search field in the enchanting window – Leaves only the recipes whose name or reagents match what you type"] = "마법부여 창의 검색창 – 입력한 내용이 이름이나 재료와 맞는 제조법만 남깁니다",
    ["The enchanting window is the one profession window that never had a search box. The field sits between the title and the slot dropdown: type into it and only the recipes whose name or one of their reagents matches stay, with the scroll bar shortening along with the list instead of leaving empty rows under the last hit. Recipes you starred still float to the top of what is left, and closing the window clears the text — otherwise the next visit would open on a list with most of the recipes missing and nothing on screen to explain it."] = "마법부여 창은 검색창이 한 번도 없었던 유일한 전문기술 창입니다. 검색창은 제목과 부위 선택 메뉴 사이에 있으며, 입력하면 이름이나 재료 중 하나가 일치하는 제조법만 남고, 목록이 줄어드는 만큼 스크롤 막대도 함께 줄어들어 마지막 결과 아래에 빈 줄이 남지 않습니다. 별표를 단 제조법은 남은 목록에서도 맨 위로 올라오며, 창을 닫으면 입력한 내용이 지워집니다. 그렇지 않으면 다음에 열었을 때 대부분의 제조법이 빠진 목록이 아무 설명도 없이 나타나게 됩니다.",
    -- Patch notes 1.52.5
    ["Diminishing returns and interrupts recognise every rank of a spell. Both lists carried one identifier per spell, usually the one for rank one, so what is really cast at level seventy fell through: no icon for the polymorph, no bar for the kick. All ranks share their name, and the client knows the name behind every identifier already in the list, so one pass builds a name index that covers every rank at once, in the client's own language, which is the one the combat log speaks."] = "약화 효과와 시전 방해가 주문의 모든 등급을 인식합니다. 두 목록 모두 주문마다 식별자를 하나씩만, 대개 1등급의 것만 담고 있어서 70레벨에서 실제로 쓰이는 것이 빠져나갔습니다. 변이에는 아이콘이, 발차기에는 막대가 없었습니다. 모든 등급은 이름을 공유하고, 목록에 이미 있는 식별자의 이름은 클라이언트가 알고 있으므로, 한 번의 순회로 모든 등급을 한꺼번에 덮는 이름 색인을 만듭니다. 클라이언트의 언어로, 즉 전투 기록이 쓰는 바로 그 언어로 만들어집니다.",
    ["Loading a setup asks first. It sets a hundred and twenty slots and empties the ones the setup has nothing for, and a single click in the dropdown was enough. The only warning, for a setup belonging to another class, was a chat line that arrived after the damage was done."] = "설정을 불러올 때 먼저 확인을 묻습니다. 120개의 칸을 채우고 설정에 없는 칸은 비우는데, 드롭다운에서 한 번 클릭하는 것으로 충분했습니다. 다른 직업의 설정에 대한 유일한 경고는 이미 덮어쓴 뒤에 도착하는 대화 창 한 줄이었습니다.",
    ["Importing a setup leaves your own macros and keybindings alone. Macros are matched by name, and a name like Pull belongs to everyone, so a foreign setup replaced the contents of your own macro of that name with the switch on by default and without a word about it. Imported setups are marked as foreign now and keep what is already there, and the message says how many were kept. A backup entry carrying no keys at all no longer gets restored either, which used to clear the keys of that command and save the result."] = "설정을 가져와도 직접 만든 매크로와 단축키는 그대로 둡니다. 매크로는 이름으로 짝지어지고 Pull 같은 이름은 누구나 쓰기 때문에, 남의 설정이 같은 이름의 내 매크로 내용을 기본값으로 켜진 스위치와 함께 아무 말 없이 덮어썼습니다. 가져온 설정은 이제 외부 것으로 표시되어 기존 내용을 남겨두고, 몇 개를 지켰는지 알려줍니다. 키가 하나도 없는 백업 항목도 더는 복원되지 않습니다. 지금까지는 그 명령의 키를 지우고 그 결과를 저장했습니다.",
    ["The enchant text of a weapon sits above its slot. Beside a weapon there is the next weapon, and to the left the whole text column, so the line had nowhere to go; above the weapon row the paper doll is empty. It is centred over its own slot and wraps upward, so two enchanted weapons no longer write across each other."] = "무기의 마법부여 문구가 해당 칸 위에 표시됩니다. 무기 옆에는 다음 무기가 있고 왼쪽에는 문구 열 전체가 있어서 문구가 놓일 자리가 없었지만, 무기 줄 위쪽의 인형 영역은 비어 있습니다. 문구는 자기 칸 위에 가운데 정렬되고 위쪽으로 줄바꿈되므로, 마법부여된 무기 두 개가 서로 겹쳐 쓰이지 않습니다.",
    ["The question before overwriting a gem is only armed once the dialog is really standing. If one was already open the client reuses it, and rebuilding it cleared the note that had just been made, so the second question answered nothing at all and said nothing about it. The recheck now compares the item as well, and an open window on its own no longer counts as proof that it is the right one."] = "보석을 덮어쓰기 전의 확인 질문은 대화 상자가 실제로 떠 있을 때에만 작동합니다. 이미 열려 있으면 클라이언트가 그것을 재사용하는데, 다시 만드는 과정에서 방금 남긴 메모가 지워져 두 번째 질문은 아무것도 답하지 못했고 그 사실조차 알리지 않았습니다. 재확인은 이제 아이템까지 비교하며, 창이 열려 있다는 것만으로는 올바른 창이라는 증거가 되지 않습니다.",
    ["The item level of a piece the client has not cached yet appears once it arrives. The retry ran into the very gate that had excluded it and drew nothing, ever. It is capped at twenty attempts per item so it cannot turn into a loop that runs every tenth of a second."] = "클라이언트가 아직 저장해두지 않은 장비의 아이템 레벨이 도착하는 즉시 표시됩니다. 재시도는 자기를 배제했던 바로 그 관문으로 들어가 아무것도 그리지 못했습니다. 이제 아이템당 스무 번으로 제한되어 0.1초마다 도는 반복이 되지 않습니다.",
    ["Deleting an entry removes the one you clicked. It went by the position the row was built with, and the list is rewritten behind the open page whenever the trinket matching adds or removes entries after an equipment change, so the neighbour disappeared instead."] = "항목을 지우면 클릭한 그 항목이 지워집니다. 줄이 만들어질 때의 위치를 기준으로 삼았는데, 장신구 맞춤이 장비 교체 후 항목을 넣거나 빼면 열려 있는 페이지 뒤에서 목록이 다시 쓰이기 때문에 옆 항목이 대신 사라졌습니다.",
    ["Logging in no longer opens the edit mode behind your back. Restoring frame positions used to apply the layout by showing the client's own edit mode manager, and that rebuilds every system the editor owns out of our call stack, which hands them to the addon for the rest of the session. Measured in game: one such call three seconds after login, and twenty seconds later 1593 refused actions in combat, party and raid frames among them. The layout is still written, and the client applies it the next time it does so itself. A frame you drag by hand still settles immediately."] = "접속할 때 편집 모드가 몰래 열리지 않습니다. 창 위치를 되돌리는 과정에서 클라이언트의 편집 모드 관리자를 띄워 배치를 적용했는데, 그 관리자는 편집기가 소유한 모든 시스템을 우리 호출 스택에서 다시 만들기 때문에 남은 세션 동안 그것들이 애드온의 것이 됩니다. 게임에서 측정한 결과, 접속 3초 뒤에 그런 호출이 있었고 20초 뒤 전투 중에 파티와 공격대 창을 포함해 1593건의 동작이 거부되었습니다. 배치는 계속 저장되며, 클라이언트가 다음에 스스로 적용할 때 반영됩니다. 손으로 끌어 옮긴 창은 여전히 즉시 자리를 잡습니다.",
    ["A frame dropped after a fight has started keeps the spot you dropped it at. A drag can only begin out of combat but it can end in one, and letting go wrote the anchor onto a protected frame without asking. The position was already saved by then, so the saved value and the frame on screen would have disagreed for the rest of the session. The write now waits for the fight to end and is made good afterwards."] = "전투가 시작된 뒤에 놓은 창은 놓은 자리에 그대로 있습니다. 끌기는 전투 밖에서만 시작할 수 있지만 전투 중에 끝날 수는 있는데, 손을 뗄 때 보호된 창에 좌표를 묻지도 않고 썼습니다. 그 시점에 위치는 이미 저장되어 있었으므로 저장된 값과 화면 속 창이 남은 세션 내내 어긋났을 것입니다. 이제 쓰기는 전투가 끝나기를 기다렸다가 뒤늦게 처리됩니다.",
    ["The client settings the fishing mode borrows survive a crash. The backup of your own values lived in memory only, so a reload, a disconnect or a crash while fishing mode was running took it along, and music, ambience, auto loot and soft targeting stayed on the fishing values for good with nothing left anywhere to say what they had been."] = "낚시 모드가 빌려 쓰는 클라이언트 설정이 튕김에도 살아남습니다. 원래 값의 백업이 메모리에만 있어서 다시 불러오기, 접속 끊김, 낚시 모드 중의 튕김이 그것을 가져가 버렸고, 음악과 주변음, 자동 획득, 부드러운 대상 지정이 영영 낚시용 값에 머문 채 이전 값이 어디에도 남지 않았습니다.",
    ["Switching the camera zoom option off returns the zoom to the client's default. The comment promised as much and the code did nothing of the sort, so with the option already on from an earlier session there was no value of ours to fall back to and the maximum stayed for every session after. It is only reset while the value still is our maximum, so anything you have set yourself since then stays."] = "카메라 확대 옵션을 끄면 확대가 클라이언트 기본값으로 돌아갑니다. 주석은 그렇게 약속했지만 코드는 전혀 그러지 않았고, 이전 세션에서 이미 옵션이 켜져 있었다면 되돌릴 우리 값 자체가 없어 최대값이 이후 모든 세션에 남았습니다. 값이 아직 우리 최대값일 때만 되돌리므로 그동안 직접 맞춘 값은 그대로 유지됩니다.",
    ["Unit tooltips no longer throw a Lua error on a unit without an identifier. The fallback one line above did the arithmetic on the missing identifier itself and handed the result to the very call that cannot take it."] = "대상 정보 창이 식별자가 없는 대상에서 더는 Lua 오류를 내지 않습니다. 한 줄 위의 대비책이 없는 식별자로 직접 계산을 해서 그 결과를 그것을 받을 수 없는 바로 그 호출에 넘겼습니다.",
    ["A set finds its own piece when two items share an identifier, the way the owl's ring and the bear's ring do. Sets store the full reference but searched by the bare identifier; the search goes by identifier and suffix now, while enchants and gems stay out of it because those change during an item's life and would make a set report its own piece as missing."] = "두 아이템이 식별자를 공유해도 세트가 자기 부품을 찾습니다. 부엉이의 반지와 곰의 반지가 그렇습니다. 세트는 전체 참조를 저장하면서도 식별자만으로 찾았는데, 이제 식별자와 접미사로 찾습니다. 마법부여와 보석은 일부러 제외했습니다. 아이템의 일생 동안 바뀌는 값이라 세트가 자기 부품을 없는 것으로 보고하게 만들기 때문입니다.",
    ["The name comes back after a cast the same way the interrupt flash already decides it. A retired field was still being asked, although the options page says it is read nowhere any more."] = "시전이 끝난 뒤 이름이 돌아오는 방식이 시전 방해 섬광이 이미 판단하는 방식과 같아졌습니다. 옵션 페이지에는 더 이상 어디서도 읽지 않는다고 적힌 폐기된 항목을 계속 확인하고 있었습니다.",
    ["The click area of a plate returns to its measured size. The value that means the client's own size was only right as long as the setter had never run, so afterwards the old area stood until a reload and the sliders went up without ever coming back."] = "이름표의 클릭 영역이 측정된 크기로 돌아옵니다. 클라이언트 고유 크기를 뜻하는 값은 설정 함수가 한 번도 실행되지 않았을 때만 맞았고, 그 뒤로는 다시 불러오기 전까지 예전 영역이 유지되어 조절기가 올라가기만 하고 결코 돌아오지 않았습니다.",
    ["An installation from before the schema stamp runs its migrations instead of skipping them. No stamp meant two opposite things, a fresh installation with nothing to migrate or one older than the stamp with everything still pending, and both were stamped current and skipped, so the older one silently lost every migration, its bar setups in their old storage place among them. The two are told apart now by whether there is any module data at all."] = "스키마 표식이 생기기 전의 설치본이 이전 작업을 건너뛰지 않고 실행합니다. 표식이 없다는 것은 정반대의 두 가지, 즉 옮길 것이 없는 새 설치이거나 표식보다 오래되어 전부 밀려 있는 설치를 뜻했는데, 둘 다 최신으로 표식이 찍히고 건너뛰어져서 오래된 쪽은 예전 저장 위치의 바 설정을 포함해 모든 이전 작업을 조용히 잃었습니다. 이제 모듈 데이터가 하나라도 있는지로 둘을 구분합니다.",
    ["The strip for the weapon slots opens downward instead of sideways. The three weapons are the only slots standing in a row rather than a column, at the bottom of the paper doll, where sideways always runs into their own neighbour. It grows away from the middle of the screen so it cannot pass the near edge, and it tips upward when the window sits at the bottom of the screen."] = "무기 칸의 목록이 옆이 아니라 아래로 펼쳐집니다. 세 무기는 열이 아니라 행으로 놓인 유일한 칸이고 인형 아래쪽에 있어서, 옆으로 펼치면 늘 자기 이웃과 부딪혔습니다. 목록은 화면 중앙에서 멀어지는 쪽으로 자라 가까운 가장자리를 넘지 않으며, 창이 화면 아래에 붙어 있으면 위쪽으로 뒤집힙니다.",
    ["A click in the picker can no longer hit whatever has moved into that bag slot in the meantime. It remembered bag and slot from the moment it was filled and listened to no bag event, so after a sort run a click hit what was lying there by then, which with a merchant window open would have been a sale. It follows bag changes now, and every click checks the item in place against the one the button was built for."] = "선택 창의 클릭이 그 사이에 해당 가방 칸으로 옮겨온 물건을 더는 건드리지 않습니다. 채워질 때의 가방과 칸을 기억할 뿐 어떤 가방 이벤트도 듣지 않아서, 정렬 후에는 그때 그 자리에 있던 것이 클릭되었고 상인 창이 열려 있었다면 판매가 되었을 것입니다. 이제 가방 변화를 따라가며, 클릭할 때마다 그 자리의 아이템을 버튼이 만들어질 때의 아이템과 대조합니다.",
    ["The merchant lock covers both trinket slots. A mixed-up condition left it applying to the lower one only."] = "상인 잠금이 장신구 두 칸 모두에 적용됩니다. 조건이 뒤바뀌어 아래쪽 칸에만 적용되고 있었습니다.",
    ["The addon no longer stamps the client's own health text and target classification with its taint. Both called the client's updaters from our call stack, the very thing the same file forbids two hundred lines further down in writing and with a reason, which makes the client's next pass over those frames unsafe. Both write what they need themselves now. The standard border returns the moment the client next classifies your target."] = "애드온이 클라이언트의 생명력 문구와 대상 분류에 더는 자기 오염을 남기지 않습니다. 둘 다 우리 호출 스택에서 클라이언트의 갱신 함수를 불렀는데, 같은 파일이 이백 줄 아래에서 이유까지 적어 명시적으로 금지한 일이며 클라이언트가 그 창들을 다음에 처리할 때를 불안정하게 만듭니다. 이제 둘 다 필요한 것을 스스로 씁니다. 기본 테두리는 클라이언트가 다음에 대상을 분류할 때 돌아옵니다.",
    ["|cffff7777What it costs, and why this is off unless you switch it on: the answer has to sit on a name the client's own protected code reads, which hands the party and raid frames to this addon for the rest of the session. In combat they then refuse to resize and name this addon while doing it. Switching it back off stops it happening again but does not undo the session it already happened in - that takes a reload.|r"] = "|cffff7777대가와, 직접 켜기 전까지 꺼져 있는 이유: 이 대답은 클라이언트의 보호된 코드가 직접 읽는 이름 위에 놓여야 하며, 그 때문에 파티와 공격대 창이 남은 접속 시간 동안 이 애드온의 것이 됩니다. 그러면 전투 중에 창들이 크기 변경을 거부하면서 이 애드온의 이름을 함께 알립니다. 다시 끄면 재발만 막을 뿐, 이미 그렇게 된 이번 접속을 되돌리지는 못합니다. 그러려면 다시 불러와야 합니다.|r",
} end)
